// The v2 rule layer's vocabulary (docs/factory-loop/v2/SPEC.md): the issue record and its states
// (section 3), the transition table's events and rows (4), the action kinds of appendix B with
// their outcomes, the State fields v2 reads (2.4), the labels and notices of appendix D and the
// rule ids of 14.1. Each closed list is a frozen array here, and its type is derived from it, so
// a value read from text is checked against the same list the code is typed by. Types and
// constants only: the pure planner imports this, so nothing here may run a command or read a
// clock.
import type { PlanCtx } from '../foundation'
import type { Snapshot } from '../settings-snapshot'
import type { ActionBase, ActionClass, Config, LedgerEntry, LedgerStatus, Ms, Source } from '../types'
import type { V2Event } from './events'
import type { CheckoutBase } from './reconcile'
import type { InterventionFacts } from './sources-interventions'
import type { PrsRead } from './sources-prs'
import type { FactsShadow } from './sources-facts'
import type { FlakesRead } from './sources-flakes'
import type { RecordsShadow } from './sources-records'
import type { WindDownRead } from './wind-down'
import type { WorkspaceRead } from './workspace'

// --- states, steps and the record (v2 SPEC 3.1, 3.2) ------------------------------------------------

export const ISSUE_STATES = ['queued', 'designing', 'building', 'reviewing', 'fixing', 'merge-queue', 'parked', 'waiting', 'closed'] as const
export type IssueState = (typeof ISSUE_STATES)[number]

export const STEP_KINDS = ['lease', 'design', 'build', 'review', 'fix', 'queue', 'triage'] as const
export type StepKind = (typeof STEP_KINDS)[number]

export const CLOSED_WHYS = ['merged', 'merged-by-hand', 'dropped', 'split', 'closed-on-github', 'claim-lost', 'done'] as const
export type ClosedWhy = (typeof CLOSED_WHYS)[number]

// The states that hold a slot and count in flight (3.1): designing to merge-queue.
export const SLOT_STATES: readonly IssueState[] = ['designing', 'building', 'reviewing', 'fixing', 'merge-queue']

// The step each state runs (4.2). Parked, waiting and closed run none; a merge-queue record runs `queue`
// only while it is the queue's head (9.1).
export const STATE_STEP: Readonly<Record<IssueState, StepKind | null>> = {
  queued: 'lease',
  designing: 'design',
  building: 'build',
  reviewing: 'review',
  fixing: 'fix',
  'merge-queue': 'queue',
  parked: null,
  waiting: null,
  closed: null,
}

// The steps an agent runs (4.2), each in the issue's slot.
export const AGENT_STEPS = ['design', 'build', 'review', 'fix', 'triage'] as const
export type AgentStep = (typeof AGENT_STEPS)[number]

// Writers may write only inside their slot and push only the record's branch; readers may not
// write inside the repository (4.2, 10.4).
export type Role = 'writer' | 'reader'
export const STEP_ROLE: Readonly<Record<AgentStep, Role>> = { design: 'reader', build: 'writer', review: 'reader', fix: 'writer', triage: 'reader' }

// The class of an agent step (appendix B): develop for design and build, drive for the rest.
export const STEP_CLASS: Readonly<Record<AgentStep, ActionClass>> = { design: 'develop', build: 'develop', review: 'drive', fix: 'drive', triage: 'drive' }

// The loop-owned agent type each step spawns (5.2, 8.3, 8.7). The model is never offered them
// (register.ts agent.offer). designer-v2 is renamed designer at the delete wave.
export const STEP_AGENT: Readonly<Record<AgentStep, `factory-loop:${string}`>> = {
  design: 'factory-loop:designer-v2',
  build: 'factory-loop:builder',
  review: 'factory-loop:reviewer',
  fix: 'factory-loop:fixer',
  triage: 'factory-loop:triage',
}

// One condition a waiting record waits on (3.2, 8.7): an issue closed, a PR merged or a release
// tag that carries a commit. A record waits until every one holds. `repo` (owner/name, lower-case) names
// another repository for issue-closed and tag-contains; absent means the loop's own repo.
export type WaitCondition = { kind: 'issue-closed'; issue: number; repo?: string } | { kind: 'pr-merged'; pr: number } | { kind: 'tag-contains'; sha: string; repo?: string }

// The parts of a structured question for the owner (3.2, 11): what the agent gave before the loop
// rendered them into `question`. `decision` is the one sentence; options are 2 to 6 closed, with a
// null detail when none was given; `recommended` names one of the options, `recommendation` is why.
export type OptionKey = 'A' | 'B' | 'C' | 'D' | 'E' | 'F'
export type ParkParts = {
  decision: string
  context: string | null
  options: { key: OptionKey; title: string; detail: string | null }[] | null
  recommended: OptionKey | null
  recommendation: string | null
}

// The record (3.2). The slot is not a field: a record holds the slot whose lease holder is
// `factory-loop:<N>:<life>` (10.1).
export type IssueRecord = {
  issue: number
  // the claim's start time in base-36 seconds: unique per life (3.3, keys.ts lifeOf)
  life: string
  // +1 on every transition; part of every per-seq key
  seq: number
  // when this seq's transition happened
  seqAt: Ms
  state: IssueState
  // when it entered this state
  since: Ms
  // queued: where a lease leads (default designing); parked and waiting: where a resume leads
  resumeTo: IssueState | null
  // fixed for the life (3.5)
  branch: string
  // adopted at claim, or set when reviewing ends (8.1)
  pr: number | null
  // the head a writer step last confirmed on origin
  head: string | null
  // the patch id the reviewer approved (8.4)
  approvedPatch: string | null
  // the design brief comment URL
  brief: string | null
  // the step this seq runs: the state's own, or 'triage'; null when waiting
  step: StepKind | null
  // attempt of that step: 1 or 2 (5.1)
  attempt: number
  // this attempt already had its one free re-run (row U1)
  cut: boolean
  // triage calls in this life, at most maxTriages
  triages: number
  // entries to fixing in this life, at most fixCap
  fixes: number
  // entries to reviewing in this life
  round: number
  // parked: the question for the owner
  question: string | null
  // parked: the parts of that question when an agent structured it, else null (always null in any
  // other state); `question` is their rendering
  parts: ParkParts | null
  // waiting: the conditions it waits on, every one of which must hold; null in any other state
  wait: WaitCondition[] | null
  // closed: why
  why: ClosedWhy | null
  // owner, triage and decline notes for the step of this seq
  notes: string[]
  // GitHub's closedAt of the newest hand close the record has handled (E4, P1)
  prClosedAt: string | null
  // this life's number among the issue's lives since its count last started (6.4, lives.ts): 1
  // for the first claim, and again for the first claim after the owner lifts factory:rejected
  lives: number
}

// A record's identity at one seq: what the transition executor compares before it stores (3.3).
export type RecordRef = { issue: number; life: string; seq: number }

// --- the table's input and rows (v2 SPEC 4.1, 4.6, 5) -------------------------------------------------

export const EVENT_KINDS = ['ok', 'not-ok', 'unknown', 'triage', 'drop', 'cleared', 'unpark', 'issue-closed', 'pr-merged', 'pr-closed', 'claim-lost', 'timeout'] as const
export type EventKind = (typeof EVENT_KINDS)[number]

// The causes outside the issue that earn one free re-run per attempt (5.1, row U1).
export const OUTSIDE_CAUSES = ['load', 'usage', 'breaker', 'slot'] as const
export type OutsideCause = (typeof OUTSIDE_CAUSES)[number]

// Why a step ended unknown (7.2, intervention `unknown:<why>`). rate-limited is an API rate limit
// (a 429, or the usage window); api is any other API error (a 5xx, overloaded).
export const UNKNOWN_WHYS = ['timeout', 'agent-dead', 'bad-answer', 'api', 'rate-limited', 'spawn', 'cli', 'github-wait'] as const
export type UnknownWhy = (typeof UNKNOWN_WHYS)[number]

// The outside cause an unknown's why is by itself (5.1): a rate limit is `usage`, a free re-run
// that the step-unknown breaker does not count (5.3). Every other why is unexplained unless a fact
// plan holds (the load, the tier, the breaker, the lease) says otherwise.
export const WHY_CAUSE: Readonly<Partial<Record<UnknownWhy, OutsideCause>>> = { 'rate-limited': 'usage' }

// The triage menu (5.2).
export const TRIAGE_CHOICES = ['retry', 'fix', 'redesign', 'park', 'drop'] as const
export type TriageChoice = (typeof TRIAGE_CHOICES)[number]

// One event for a record (4.6): its kind and what the row's guard and change read.
export type TableEvent = { kind: EventKind; reason?: string; cause?: OutsideCause; why?: UnknownWhy; choice?: TriageChoice; data?: unknown }

// The reused event states a seq logs beside its `transition` on entry to a state (4.5, 7.1).
export const EMIT_STATES = ['delegated', 'fix_requested', 'merge_ready', 'abandoned'] as const
export type EmitState = (typeof EMIT_STATES)[number]

// One row of the table (4.6). `rowFor` in table.ts is the only lookup.
export type Row = {
  id: string
  states: readonly IssueState[]
  on: EventKind
  // pure guard: the guards on one (state, step, event) are exclusive and exhaustive
  when?: (r: IssueRecord, e: TableEvent, c: Config) => boolean
  next: IssueState | 'same' | 'resumeTo'
  // pure: the fields the row changes
  change: (r: IssueRecord, e: TableEvent, now: Ms) => Partial<IssueRecord>
  // the transition note's `via` code
  via: string
}

// --- what a step reports (v2 SPEC 4.2, 5.1, 10.8) -----------------------------------------------------

// A step's result, as steps.ts records it on the step's ledger entry and plan reads it: ok,
// not-ok with a reason, or unknown with why. head: a writer's head, read on origin. choice: a
// triage's. data: the checked answer the step's contract gave (contracts-*.mjs).
export type StepResult = {
  event: 'ok' | 'not-ok' | 'unknown'
  reason: string | null
  why: UnknownWhy | null
  head: string | null
  choice: TriageChoice | null
  data: unknown
}

// unknownResult: a step's unknown, with why and a short reason.
export function unknownResult(why: UnknownWhy, reason: string): StepResult {
  return { event: 'unknown', reason: reason.length > 200 ? `${reason.slice(0, 197)}...` : reason, why, head: null, choice: null, data: null }
}

// The guard's FAIL classes in --patch mode (9.3, 9.4).
export const GUARD_CLASSES = ['behind', 'conflict', 'checks', 'patch', 'linkage', 'read', 'policy'] as const
export type GuardClass = (typeof GUARD_CLASSES)[number]

export const SLOT_OPS = ['lease', 'prepare', 'kill', 'free'] as const
export type SlotOp = (typeof SLOT_OPS)[number]

// The outcomes the v2 executors record (one member of types.ts Outcome each).
export type V2Outcome =
  | { kind: 'step'; step: AgentStep; result: StepResult }
  // what a transition did, so the breaker and the interventions read it from the ledger (5.3, 7.2)
  | {
      kind: 'transition'
      row: string
      event: EventKind
      cause: OutsideCause | null
      from: IssueState | null
      to: IssueState
      step: StepKind | null
      // false from the entry's start until the executor stored the record (a lost entry may carry
      // false: the seq is the record's when the store holds it at that seq)
      stored: boolean
      // the transition note's via code (table.ts viaOf), carried from the entry's start (ledger.ts
      // start): the row's own code, with the detail its event gave where the row takes one:
      // `free:<cause>` (U1), `unknown:<why>` (U2 to U4), `fix:<review|ci|conflict>` (T9),
      // `triage:<choice>` (X1 to X5), `unpark:<op|label>` (P1). The seq's entry actions log it and
      // the interventions read it (rules-interventions.ts), so nothing is inferred from other entries.
      via: string
    }
  | { kind: 'pr'; pr: number; created: boolean; reopened: boolean }
  | { kind: 'split'; child: number }
  // F1: the flake bug filed or found, with what its tell says (rules-flake-bugs.ts)
  | { kind: 'flake-bug'; issue: number; made: boolean; ready: boolean; test: string; flakes: number; windowDays: number; firstFlakeAt: string; reason: string }
  // a close-tracker check: the split parent found (null: the issue is no split child), whether it was closed, and the sub-issues still open
  | { kind: 'close-tracker'; parent: number | null; closed: boolean; open: number[] }
  // leftovers: the patch file a prepare or a free saved the slot's leftovers to (10.2): its uncommitted
  // work and its commits not on origin, against the commit the next step starts from; a retry's
  // prompt names it (5.1), and a resumed life finds a free's through rules-agent.ts leftoversOf; null
  // when nothing would have been lost
  | { kind: 'slot'; op: SlotOp; path: string | null; lease: string | null; head: string | null; killed: number | null; leftovers?: string | null }
  | { kind: 'queue'; op: 'update' | 'merge'; merged: boolean; head: string | null; failClass: GuardClass | null; lines: string[] }
  // an open PR adopted at claim (3.5)
  | { kind: 'adopt'; branch: string; pr: number | null; others: number[] }

// --- the action kinds (appendix B) ----------------------------------------------------------------

// How deep trackers nest: observe reads sub-issues this many levels down, and a close-tracker chain
// checks this many trackers up (state.ts re-exports it).
export const TRACKER_DEPTH = 3

export const V2_ACTION_KINDS = ['transition', 'label', 'comment', 'event', 'pr', 'split', 'agent-step', 'ci-rerun', 'queue-update', 'queue-merge', 'slot', 'link', 'close-tracker', 'flake-bug', 'released'] as const
// What F1 asks of the flake-bug executor: the test and its hash (the marker's), the bug's title and
// body (without its markers; flakeIds are the flakes it lists), whether `ready` is allowed, the epic to link under, and what the bug's tell records.
export type FlakeBugSpec = { hash: string; test: string; title: string; body: string; flakeIds: string[]; ready: boolean; epic: number | null; flakes: number; windowDays: number; firstFlakeAt: string; reason: string }

export type V2ActionKind = (typeof V2_ACTION_KINDS)[number]

// What the transition executor re-checks against the live ledger and records before it stores
// (3.3): the life's claim entry (row S0), a step's entry as plan saw it, or an owner or GitHub
// fact (an edge whose time the record already carries).
export type Trigger =
  | { kind: 'claim'; key: string }
  | { kind: 'entry'; key: string; status: LedgerStatus; startedAt: Ms }
  | { kind: 'fact'; fact: string }

// The step marker the slot carries in its git dir (10.2), which the companion reads.
export type StepMarker = {
  v: 1
  repo: string
  issue: number
  life: string
  seq: number
  step: AgentStep
  role: Role
  branch: string
  // the issue's PR, when it has one (the companion's notes carry it); an older marker has none
  pr: number | null
  gateCommands: string[]
  gateTimeoutMs: Ms
  loopDir: string
  // the step attempt's scratch folder (keys.ts scratchOf), which the companion exports as TMPDIR; the
  // slot executor fills it, like loopDir
  scratch: string
  // the stop gates the companion runs at once, resolved from the config and the CPU count by the slot
  // executor (the planner does not know the CPUs); absent: no limit, as an older loop wrote it
  gateConcurrency?: number
  // the longest a finished writer waits for its gate's turn, set by the slot executor
  gateWaitTimeoutMs?: Ms
}

// The four reasons of a designer's split (8.7; contracts-work.mjs REASON_KEYS).
export type SplitReasons = { why_split: string; why_count: string; why_parts: string; why_order: string }

// A child a designer's split asks for (8.7).
export type SplitChild = { key: string; title: string; why: string; body: string; blockedBy: string[]; ready: boolean; decision: string | null; decisionParts?: ParkParts | null }

export type V2Action =
  // cause: the outside cause of an unknown (5.1), which the breaker reads; via: the note's code;
  // fromState and fromStep: the state and step the record leaves, which the entry carries from its
  // start (ledger.ts start), so a crash before it is saved done loses none of them (3.3)
  | (ActionBase & {
      kind: 'transition'
      row: string
      event: EventKind
      from: RecordRef | null
      next: IssueRecord
      trigger: Trigger
      cause?: OutsideCause | null
      via?: string
      fromState?: IssueState | null
      fromStep?: StepKind | null
    })
  // set: add the state's label and remove the other six; ensure: create the eight; clear: remove
  // the seven state labels (3.4); requeue: the seven off and `ready` on (ready: the repo's ready
  // label); reject: the seven off and factory:rejected on (both R1's release, 6.4)
  | (ActionBase & { kind: 'label'; op: LabelOp; label: FactoryLabel | null; ready?: string })
  // the body carries the hidden key <!-- factory-loop:<ledger key> --> (4.5)
  | (ActionBase & { kind: 'comment'; on: 'issue' | 'pr'; number: number; body: string })
  // built only by events.ts (7.1); logged: the event log already holds it (events.ts logOnce), so
  // the executor settles it done with no second write
  | (ActionBase & { kind: 'event'; event: V2Event; logged?: true; target?: 'new' })
  | (ActionBase & {
      kind: 'pr'
      op: 'ensure' | 'body'
      branch: string
      base: string
      pr: number | null
      title: string
      summary: string
      evidence: string | null
      brief: string | null
    })
  // a waiting record's issue linked as blocked by an issue it waits on (blocker): the GitHub dependency
  // link, once per condition; a closed blocker is skipped, a pull request is no blocker (act-split.ts)
  | (ActionBase & { kind: 'link'; blocker: number })
  // a merged split child's check upward: issue is the one to check from; its split parent is closed when every sub-issue is closed (act-tracker.ts)
  | (ActionBase & { kind: 'close-tracker' })
  // F1: one bug for a flaky test, found again by its hidden marker or filed; ready: the cap allowed `ready` (rules-flake-bugs.ts)
  | (ActionBase & { kind: 'flake-bug'; bug: FlakeBugSpec })
  // O4: log a release tag (callum-flow-released); source: the loop's own release task made it, or the workflow
  | (ActionBase & { kind: 'released'; tag: string; source: 'loop' | 'workflow' })
  // one child per action; blockedBy: the issue numbers it waits on: siblings made, or existing issues
  | (ActionBase & { kind: 'split'; parent: number; child: SplitChild; blockedBy: number[] })
  | (ActionBase & { kind: 'agent-step'; step: AgentStep; life: string; seq: number; attempt: number; branch: string; slot: string | null; notes: string[] })
  | (ActionBase & { kind: 'ci-rerun'; pr: number; runId: string; round: number })
  // base: main's head at plan time (the key's); head: the PR's head as observe read it
  | (ActionBase & { kind: 'queue-update'; pr: number; base: string; head: string })
  | (ActionBase & { kind: 'queue-merge'; issue: number; pr: number; head: string; patch: string })
  | (ActionBase & { kind: 'slot'; op: SlotOp; life: string; path: string | null; lease: string | null; branch: string | null; marker: StepMarker | null; keepScratch: boolean })

// --- labels and notices (appendix D) ---------------------------------------------------------------

export const LABEL_OPS = ['set', 'ensure', 'clear', 'requeue', 'reject'] as const
export type LabelOp = (typeof LABEL_OPS)[number]

export const FACTORY_LABEL_PREFIX = 'factory:'

export type FactoryLabel = `factory:${Exclude<IssueState, 'closed'>}`

// Each state's label (closed has none), with its colour and description (appendix D).
export const FACTORY_LABELS: Readonly<Record<Exclude<IssueState, 'closed'>, { name: FactoryLabel; color: string; description: string }>> = {
  queued: { name: 'factory:queued', color: 'c5def5', description: 'Factory loop: claimed, waiting for a slot' },
  designing: { name: 'factory:designing', color: 'bfd4f2', description: 'Factory loop: the designer is at work' },
  building: { name: 'factory:building', color: '0e8a16', description: 'Factory loop: the implementer is at work' },
  reviewing: { name: 'factory:reviewing', color: 'fbca04', description: 'Factory loop: review and CI on the PR' },
  fixing: { name: 'factory:fixing', color: 'd93f0b', description: 'Factory loop: a fixer is at work' },
  'merge-queue': { name: 'factory:merge-queue', color: '5319e7', description: 'Factory loop: approved and green, waiting to merge' },
  parked: { name: 'factory:parked', color: 'b60205', description: 'Factory loop: waits on the owner; remove this label to resume' },
  waiting: { name: 'factory:waiting', color: 'fef2c0', description: 'Factory loop: waits on a condition the loop checks; it resumes by itself' },
}

// resumeStep: how the owner resumes a parked issue (11), one text for every message that says so:
// the park comment, its tell and reminders, and the triage prompt's park choice.
export function resumeStep(issue: number): string {
  return `answer on the issue and ${resumeAction(issue)}; a comment alone does not resume`
}

// resumeAction: the two things that resume, which the park comment's numbered list (park-text.ts)
// says after its first step.
export function resumeAction(issue: number): string {
  return `remove the \`factory:parked\` label, or run \`/factory resume ${issue} "your answer"\``
}

// The label of an issue R1 released at its last life (6.4): not a state, since the issue is out of
// the factory. S1 never claims an issue carrying it; the owner removing it and adding `ready`
// brings the issue back with its life count started again.
export const REJECTED_LABEL: { name: 'factory:rejected'; color: string; description: string } = {
  name: 'factory:rejected',
  color: '6a737d',
  description: 'Factory loop: its last life ended without a merge; remove this label and add ready to try again',
}

// The owner's hold on a merge (9.1): set on the issue or its PR, the loop reads it and never makes,
// adds or removes it, so it is not in ALL_FACTORY_LABELS. It is a hold, not a state.
export const DONT_MERGE_LABEL = "don't-merge"

// sameLabel: label names are equal ignoring case.
export const sameLabel = (a: string, b: string): boolean => a.toLowerCase() === b.toLowerCase()

// Every label the loop makes (op ensure): the seven state labels, then factory:rejected.
export const ALL_FACTORY_LABELS: readonly { name: string; color: string; description: string }[] = [...Object.values(FACTORY_LABELS), REJECTED_LABEL]

// labelOf: a state's label, or null for closed.
export function labelOf(state: IssueState): FactoryLabel | null {
  return state === 'closed' ? null : FACTORY_LABELS[state].name
}

// The notice (TELL) kinds v2 adds; the owner items (V2_OWNER_TELLS) go out before any other
// wake (O2). The foundation's own (runaway, blind, heartbeat-other, old-watcher, schema-behind, pass-error) stay.
export const V2_OWNER_TELLS = ['parked', 'breaker', 'stalled', 'checkout', 'workspace', 'rejected', 'keep-open-blocks', 'reopened', 'records-shadow', 'facts-shadow', 'wait-unreadable', 'starved', 'actions-refused'] as const
export const V2_TELLS = [...V2_OWNER_TELLS, 'waiting', 'task-timeout', 'wind-down-stale', 'done', 'flake-bug', 'actions-resumed'] as const
export type V2Tell = (typeof V2_TELLS)[number]

// --- rule ids (v2 SPEC 14.1) -------------------------------------------------------------------------

export const V2_RULES = [
  'G1', 'G2', 'G3', 'G4', 'H1', 'H2', 'R1', 'R2', 'S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'Q1', 'Q2', 'W1', 'W2', 'O1', 'O2', 'O3', 'O4', 'O5', 'M1', 'F1',
] as const
export type V2Rule = (typeof V2_RULES)[number]

// --- interventions (v2 SPEC 7.2) ---------------------------------------------------------------------

export type InterventionWho = 'person' | 'loop' | 'judge'

// The cause families; `op:<name>`, `unknown:<why>`, `free:<cause>`, `fix:<what>`, `queue:<what>`
// and `guard:<what>` take their suffix from the lists above or the op's name.
export const PERSON_CAUSES = ['op', 'unpark', 'push', 'hand-merge', 'pr-closed', 'issue-closed', 'control-file', 'config-file', 'restart', 'reconcile', 'unreject', 'rescue', 'hold'] as const
export const LOOP_CAUSES = [
  'triage', 'unknown', 'free', 'park', 'fix', 'ci-rerun', 'queue', 'guard', 'gate-unknown', 'prompt-denied', 'tripwire', 'breaker', 'stalled', 'workspace', 'reconcile', 'rejected', 'reclaim', 'wake',
] as const

// --- what v2 reads (v2 SPEC 2.4) ---------------------------------------------------------------------

// A pool slot's lease, by its holder (10.1): `factory-loop:<N>:<life>` names the loop's own.
export type Lease = { path: string; lease: string; holder: string; issue: number | null; life: string | null; status: string; busy: boolean }

// The newest issue read observe holds, and when it was taken: the parked label's absence in a
// read newer than the park is the unpark signal (3.4).
export type IssueRead = { at: Ms; open: boolean | null; labels: string[] | null }

// One wait condition as the last successful read showed it, and when that read was taken (4.4).
// `tag`: the release tag a tag-contains read compared against, so it is read again only when the tag changes.
export type WaitRead = { at: Ms; held: boolean; tag?: string }

// A condition the loop cannot read, since when: its read failed, or (tag-contains) its repo has no release tag.
export type WaitUnread = { since: Ms; why: 'read-failed' | 'no-release' }

// An open release bump PR (sources-release.ts): its branch and GitHub's creation time, which the
// merge queue's hold window runs from (9.1).
export type ReleasePr = { pr: number; branch: string; createdAt: Ms }
// What the merge queue's release hold reads: the open bump PRs, and how the ones that left the list
// ended (merged or closed), until their end is logged.
export type ReleasePrsRead = { prs: ReleasePr[]; left: Record<number, 'merged' | 'closed'> }

// A trusted comment on an issue (callum-flow-issue-read --comments), for a resume's note (11).
export type IssueComment = { body: string; at: Ms; url: string | null }

// When observe first saw a PR head (2.4): it bounds the waits on GitHub (4.4).
export type HeadSeen = { pr: number; at: Ms }

// The newest completed run of a workflow on the default branch (sources-main.ts).
export type MainRun = { id: number; attempt: number; head: string; event: string; conclusion: string }
// One active workflow as the main read showed it: its newest completed run (null: none) and whether
// a newer run is queued or in progress.
export type MainWorkflow = { id: number; name: string; run: MainRun | null; running: boolean }
// The newest deployment of an environment at the head, and its newest status (null: none).
export type MainDeployment = { environment: string; id: number; state: string | null }
// What one read of the default branch showed (sources-main.ts, the schema main_state.v1): when (ISO, 3 ms digits), the
// branch and its head, the merged PR the head came from, the workflows and the deployments.
export type MainReading = { observedAt: string; branch: string; head: string; pr: number | null; workflows: MainWorkflow[]; deployments: MainDeployment[] }

export const V2_SOURCES = ['store', 'leases', 'prs', 'interventions', 'comments', 'dualWrite', 'releasePrs', 'main', 'flakes'] as const
// What the new event log holds, read once per load when dual write is on (sources-dualwrite.ts): when it
// was read and the "<issue>:<life>:<seq>" of this device's transitions it holds.
export type DualWrite = { readAt: Ms; seen: ReadonlySet<string> }

export type V2SourceName = (typeof V2_SOURCES)[number]

// One issue of the blocker tree (sources-blockers.ts): what its single read showed. `blockers` are its
// open blockers in this repo, `foreign` its open blockers elsewhere (`owner/name#N`, never read);
// `read` is how its read ended: refused (an untrusted author, exit 3) or failed.
export type BlockerNode = { open: boolean; labels: string[]; title: string | null; blockers: number[]; foreign: string[]; read: 'ok' | 'refused' | 'failed' }

// The blockers of the queue's blocked issues, read for one starved spell and one 24 h period of it.
// `nodes` are by issue number; a blocker that has no node was not read (the cap stopped the walk).
export type BlockerTree = { since: Ms; period: number; readAt: Ms; nodes: Record<number, BlockerNode>; truncated: boolean; error: string | null }

// What S1 says of a pass (rules-claim.ts): `starved` is true when the queue is not empty, nothing is
// queued or in flight, no owner hold or stopping tier applies and every queue issue was skipped by a claim
// filter; null when a source failed (unknown). `skips`: each queue issue's filter reason, `blocked`: those
// skipped for their blockers.
export type StarvedVerdict = { starved: boolean | null; skips: Map<number, string>; blocked: number[] }

// The State fields v2 adds (2.4), as State.v2: observeV2 reads them every pass; absent in a state
// built outside a pass.
export type V2State = {
  sources: Record<V2SourceName, Source>
  records: IssueRecord[]
  // where the records came from: the store (act mode's), the event log (a rebuild), or neither
  recordsFrom: 'store' | 'events' | 'none'
  // by head sha
  heads: Record<string, HeadSeen>
  leases: Lease[]
  // the newest read of each issue observe holds, by issue number
  reads: Record<number, IssueRead>
  // trusted comments of parked records whose label a person removed, by issue number
  comments: Record<number, IssueComment[]>
  prs: PrsRead
  // the conditions waiting records wait on, by key (`issue:57`, `pr:812`, `tag:35bb655`): the last read that
  // showed one; a condition with no entry was not read, or its read failed, and stays open
  waits?: Record<string, WaitRead>
  // the conditions that cannot be read, by key, and since when; absent: none
  waitsUnread?: Record<string, WaitUnread>
  // the open release bump PRs (sources-release.ts) the merge queue holds for; absent: none read
  releasePrs?: ReleasePrsRead
  // the default branch as the last read that succeeded showed it (sources-main.ts); absent: none this pass
  main?: MainReading
  // the flakes in the window and the open flake bugs (sources-flakes.ts); absent: not read this pass
  flakes?: FlakesRead
  // when the PR reads showed each issue's PR closed or merged (GitHub's closedAt), by issue number:
  // an older read of the issue is due at once, and pr-closed waits for it (4.1)
  changed: Record<number, Ms>
  interventions: InterventionFacts
  // the onceKeys (events.ts) of this device's events in the pass's read of the event log (the facts
  // read, 2.4, or the rebuild's week): which facts are logged, when a wiped store lost their ledger
  // keys (7.2)
  logged: string[]
  // the main checkout the tripwire last settled on, which R1 compares this pass's read with
  // (10.7; reconcile.ts checkoutBaseOf); null before the first read that did not fail
  checkoutBase: CheckoutBase | null
  // the new log's transitions; null when dual write is off or not read (act mode, planner v2 only)
  dualWrite: DualWrite | null
  // the last compare of the record rebuild's two stores (sources-records.ts), as of the pass that made it; absent: none made this load
  recordsShadow?: RecordsShadow
  // the last compare of the facts' and ledger rebuild's two stores (sources-facts.ts); absent: none made this load
  factsShadow?: FactsShadow
  // the workspace rail: the companion's handshake for this session (10.9; workspace.ts); absent
  // when not read, which holds nothing
  workspace?: WorkspaceRead
  // the wind-down request, stop-now file and last status (10.11; wind-down.ts); absent when not read
  windDown?: WindDownRead
  // when the current starved spell began (the store's `starved:<repo>`); absent: no spell (S1)
  starvedSince?: Ms
  // the blocker tree read for the spell and its current period (sources-blockers.ts); absent: not read
  blockers?: BlockerTree
  // the settings in force now, the last snapshot kept in the store (null: none valid) and the config ops that landed since (rules-settings.ts); absent: not read
  settings?: { now: Snapshot; nowAt: Ms; before: Snapshot | null; beforeAt: Ms | null; ops: SettingsOp[] }
}

// a config op that landed (driver-controls.ts), kept in the store until the snapshot after it
export type SettingsOp = { key: string; by: 'person' | 'judge'; at: Ms }

// The pure planner's context: the foundation's, with the v2 fields every rule reads.
export type V2Ctx = PlanCtx & { v2: V2State; starved?: StarvedVerdict }

// --- what the executors may change beside the ledger (v2 SPEC 3.3, 4.6) -------------------------------

// The live records: only the transition executor updates them, under the act lock. update applies
// fn to the records as they are now (null: no change), saves them to the store, and resolves once
// saved; changed is false when fn changed nothing or the store refused the write.
export type V2Io = {
  records: () => readonly IssueRecord[]
  // the live ledger, which the transition executor re-checks its trigger against (3.3)
  ledger?: () => readonly LedgerEntry[]
  updateRecords: (fn: (records: readonly IssueRecord[]) => IssueRecord[] | null) => Promise<{ changed: boolean; saved: boolean }>
  // asks the driver for the next pass at once: a transition's next event is taken without delay
  ping: (why: string) => void
}

// --- settings (appendix A) ------------------------------------------------------------------------

// the model aliases the agent tool accepts; a setting named *Model takes one of them
export const MODELS = ['sonnet', 'opus', 'haiku', 'fable'] as const
export type Model = (typeof MODELS)[number]

// The timeouts and tell periods of 4.4, by step and waiting state.
export type StateTimeouts = { design: Ms; build: Ms; review: Ms; fix: Ms; triage: Ms; queued: Ms; queueWait: Ms; parked: Ms; waiting: Ms }

files.hooks/v2/workspace.ts:
// The loop's side of the companion plugin `factory-loop-workspace` (docs/factory-loop/v2/SPEC.md
// 10.3, 10.5, 10.9), pure: the slot line and folder each agent step's spawn carries, the Bash
// timeout the loop sets for its session, and the workspace rail. The companion writes a handshake
// for each session it runs in, again every minute; without a fresh one for this session, an agent
// would start in the main checkout, unguarded, so every agent step is held with the skip line
// `workspace`, and the owner is told once (tell(workspace)). sources-workspace.ts reads and judges
// the handshake, observeV2 puts it in the State, and rules-state.ts and plan.ts hold and tell
// from it.
import { skip, wake, want } from '../foundation'
import type { Ms } from '../types'
import { AGENT_STEPS } from './types'
import type { StepKind, V2Ctx } from './types'

// The 10-minute Bash timeout (10.5): the loop's session.start sets BASH_DEFAULT_TIMEOUT_MS and
// BASH_MAX_TIMEOUT_MS to it; the companion also gives a loop agent's Bash call with no timeout the
// same value.
export const BASH_TIMEOUT_MS = '600000'

// The rail's owner notice waits this long after the module loaded, so the companion's own
// session.start, which may finish after the loop's first pass, is not told as missing. The hold
// starts at once.
export const WORKSPACE_GRACE_MS = 2 * 60_000

// withSlotLine: the spawn's prompt, opening with `factory-slot: <slot>`, which the companion reads
// to start the agent in its slot (10.3). A prompt that opens with it already is kept; one that
// opens with another slot's has that line replaced. No slot: the prompt as it is.
export function withSlotLine(prompt: string, slot: string | undefined): string {
  if (slot === undefined) return prompt
  const line = `factory-slot: ${slot}`
  const nl = prompt.indexOf('\n')
  const first = nl === -1 ? prompt : prompt.slice(0, nl)
  if (first === line) return prompt
  if (first.startsWith('factory-slot: ')) return nl === -1 ? line : `${line}${prompt.slice(nl)}`
  return `${line}\n${prompt}`
}

// handshakePath: where the companion says it runs in a session (its hooks/register.ts
// handshakePath): one file per session under the loop's base directory.
export function handshakePath(loopBase: string, session: string): string {
  return `${loopBase}/workspace/${session.replace(/[^A-Za-z0-9._-]/g, '_')}.json`
}

// processIdOf: the process that /proc/<pid>/stat describes, by its pid and start time, as the
// companion names its own in the handshake (its hooks/register.ts processIdOf). No other process
// has it: not a child, not a later one given the same pid. undefined: no stat to read.
export function processIdOf(stat: string | null): string | undefined {
  const pid = stat?.split(' ', 1)[0] ?? ''
  const start = stat?.slice(stat.lastIndexOf(') ') + 2).split(' ')[19] ?? ''
  return /^\d+$/.test(pid) && /^\d+$/.test(start) ? `${pid}:${start}` : undefined
}

// What the rail read for this session and this process (null: its id is unknown): the handshake
// is there, names both, and is fresh, or why not (sources-workspace.ts workspaceRead).
export type WorkspaceRead = { session: string; process: string | null } & ({ ok: true; version: string | null } | { ok: false; why: string })

// workspaceHold: why a record's step may not start: an agent step while the rail fails. null: it
// may (the rail passed, or was not read).
export function workspaceHold(ctx: V2Ctx, step: StepKind | null): string | null {
  const w = ctx.v2.workspace
  if (w === undefined || w.ok || step === null || !(AGENT_STEPS as readonly string[]).includes(step)) return null
  return `workspace: ${w.why}; agent steps are held`
}

// workspaceTell: the owner told once per process the rail failed in, after the grace: the
// supervisor resumes the same session in each new process, and each outage is told.
export function workspaceTell(ctx: V2Ctx): void {
  const w = ctx.v2.workspace
  if (w === undefined || w.ok) return
  const since: Ms = ctx.state.loadedAt
  if (ctx.state.now - since < WORKSPACE_GRACE_MS) {
    skip(ctx, 'O2', null, `workspace: told after ${WORKSPACE_GRACE_MS / 60_000} minutes without the companion: ${w.why}`)
    return
  }
  const key = `tell:workspace:${`${w.session}/${w.process ?? 'unknown'}`.replace(/[^A-Za-z0-9._-]/g, '_')}`
  const context = [w.why, 'Enable the factory-loop-workspace plugin beside factory-loop in this workspace, then restart the session. Until then no agent step starts.']
  want(ctx, wake('tell', 'workspace', key, 'O2', null, { session: w.session }, context))
}

files.hooks/act.ts:
// The act step (v2 SPEC 13.2, 13.6, 13.7, 13.8, 13.10): the one dispatcher from an action's kind to its executor,
// what an act-mode pass does once observe has read the factory (what the agent list proves,
// wakes past their timeout, plan, then plan's actions in order: start each ledger entry,
// pre-check usage for a token-spending class, run the executor, finish the entry with what it
// reported), and what the hooks between passes do to the ledger (an agent's answer, in text or
// through its answer tool, a wake's turn, the wake answer tool, `/factory retry`). Every entry
// that moves gets its `loop` event, once.
// register.ts holds $, builds the ActIo and keeps the store; everything here works through the
// ActIo and the live ledger, so the tests drive whole passes, and the argv safety test every
// executor, with a recording fake. The layer that plans is v2/plan.ts (v2 SPEC 2.3).
import { cliExecutors } from './act-cli'
import { mergeExecutors } from './act-merge'
import type { ActIo, EventFields, Exec, ExecCtx, Executor, RunInit, RunResult } from './exec'
import { GITHUB_V2, turnEnded } from './foundation'
import { changedEntries, finish, loopEvent, reconcileAgents, start } from './ledger'
import type { Runtime } from './observe'
import { preCheck } from './rails'
import type { BreakerNotice } from './rails'
import type { Action, ActionKind, AgentStatus, Config, Control, LedgerEntry, Ms, PlanResult, State } from './types'
import { planV2 } from './v2/plan'
import { V2_EXECUTORS, executorOf } from './v2/registry'
import { stepAnswers, stepRecorded } from './v2/steps'
import { gateHoldMs } from './v2/steps-gate'
import { V2_ACTION_KINDS } from './v2/types'
import { expireWakes, wakeExecutors } from './wake'

const HOUR = 3_600_000
const SUMMARY_MAX = 200
// callum-flow-event is one jq call and one append; a minute is ample
const EVENT_TIMEOUT_MS = 60_000

// Every kind's executor (v2 SPEC 13.6.1): the shared kinds', and v2's for its new kinds (v2/registry.ts).
// act.test.ts checks that no ActionKind lacks one.
export const EXECUTORS: Partial<Record<ActionKind, Executor>> = {
  ...cliExecutors,
  ...mergeExecutors,
  ...wakeExecutors,
  ...Object.fromEntries(V2_ACTION_KINDS.map(kind => [kind, V2_EXECUTORS[kind]])),
}

const WAKES: readonly ActionKind[] = ['judge', 'task', 'tell']

// dispatch: the action's executor, v2's own for the kind first (a reused kind may have a v2
// behaviour), run again after a GitHub blip (registry.ts). A kind with no executor, or an
// executor that throws, is a failed attempt; neither is a reason to stop the pass.
export async function dispatch(ctx: ExecCtx, action: Action): Promise<Exec> {
  const run = executorOf(action.kind, EXECUTORS)
  if (run === undefined) return { status: 'failed', summary: `no executor for ${action.kind}`, noRetry: true }
  try {
    return await run(ctx, action)
  } catch (err) {
    return { status: 'failed', summary: clip(`${action.kind}: the executor threw: ${message(err)}`) }
  }
}

// --- commands and events (v2 SPEC 13.6.1, 13.7.4, 13.11.1) ---------------------------------------------------

// commandOf: ExecCtx.cmd: the argv from the main checkout (or init.cwd) with the runtime's
// environment, which carries the repo, the configured labels and, when not acting, the event
// sink. stdin passes through as given, an empty string included. Each command joins the pass's
// list for the decision log.
export function commandOf(io: ActIo, rt: Runtime, log: string[]): ExecCtx['cmd'] {
  return (argv: string[], init: RunInit): Promise<RunResult> => {
    log.push(argv.join(' ').slice(0, 160))
    const run: RunInit & { cwd: string; env: Record<string, string> } = { cwd: init.cwd ?? rt.cwd, env: rt.env, timeoutMs: init.timeoutMs }
    if (init.stdin !== undefined) run.stdin = init.stdin
    return io.run(argv, run)
  }
}

// eventArgv: `callum-flow-event <state>` with the fields as its flags.
export function eventArgv(state: string, f: EventFields): string[] {
  const argv = ['callum-flow-event', state]
  if (f.issue !== undefined && f.issue !== null) argv.push('--issue', String(f.issue))
  if (f.run !== undefined && f.run !== null) argv.push('--run', f.run)
  if (f.branch !== undefined && f.branch !== null) argv.push('--branch', f.branch)
  if (f.pr !== undefined && f.pr !== null) argv.push('--pr', String(f.pr))
  if (f.head !== undefined && f.head !== null) argv.push('--head', f.head)
  if (f.note !== undefined && f.note !== null) argv.push('--note', f.note)
  return argv
}

// eventOf: ExecCtx.event. callum-flow-event exits non-zero only on a usage error (2); the error
// carries the exit as `exitCode`, which the executors read to never retry it.
export function eventOf(cmd: ExecCtx['cmd']): ExecCtx['event'] {
  return async (state, fields) => {
    const r = await cmd(eventArgv(state, fields), { timeoutMs: EVENT_TIMEOUT_MS })
    if (r.exitCode === 0) return
    const why = r.stderr.trim().split('\n').pop() ?? ''
    throw Object.assign(new Error(`callum-flow-event ${state}: exit ${r.exitCode}${why === '' ? '' : `: ${why}`}`), { exitCode: r.exitCode })
  }
}

// --- the live ledger ---------------------------------------------------------------------------

// The ledger as the driver holds it: one array, replaced whole by every transition. The pass and
// the hooks that fire during it (an agent's answer, a wake's turn) apply their transitions to the
// array as it is then, with no await between the read and the write, so neither loses the other's.
// logged: the loop event last logged for each key (logLoop); a ledger loaded from the store or the
// event log starts it with loggedOf, since each of its entries was logged as it got there.
export type Live = { ledger: LedgerEntry[]; logged?: Map<string, string> }

// loggedOf: the loop event each entry of a loaded ledger already logged.
export function loggedOf(ledger: readonly LedgerEntry[]): Map<string, string> {
  const out = new Map<string, string>()
  for (const entry of ledger) {
    const argv = loopEvent(entry)
    if (argv !== null) out.set(entry.key, JSON.stringify(argv))
  }
  return out
}

// transition: apply fn to the live ledger; the entries it changed, for their loop events.
export function transition(live: Live, fn: (ledger: LedgerEntry[]) => LedgerEntry[]): LedgerEntry[] {
  const before = live.ledger
  live.ledger = fn(before)
  return changedEntries(before, live.ledger)
}

// What an act step works with.
export type ActEnv = {
  io: ActIo
  // the acting runtime: its env sends events to the real log
  rt: Runtime
  live: Live
  // the pass's command list, for the decision log
  commands: string[]
  // a fresh wake id (v2 SPEC 13.8.1 `id=`)
  wakeId: () => string
  // $.session.id(): the session a wake it submits belongs to ('' when unknown)
  session: string
  // writes the live ledger to the store: an attempt's start before its executor runs, and every
  // transition before its loop event, so a reload at any point finds what already happened;
  // false when it was not written
  save: () => Promise<boolean>
  // this session still holds the act lock, renewed now; once it does not, the pass runs nothing
  // more. Asked before every action.
  holds: () => Promise<boolean>
  // the kill switch is set (v2 SPEC 13.11.3): one stat, asked before every action but the title and
  // before a notice goes out; once it is, the pass runs nothing more
  killed: () => Promise<boolean>
  // what went wrong outside any one action (a loop event not logged), for the decision log
  problems: string[]
}

export function ctxOf(env: ActEnv, state: State, entry: LedgerEntry): ExecCtx {
  const cmd = commandOf(env.io, env.rt, env.commands)
  return { io: env.io, rt: env.rt, state, entry, cmd, event: eventOf(cmd), wakeId: env.wakeId }
}

// logLoop: the `loop` event of each entry a transition moved that logs one: agents, wakes and
// owner notices (D-09, ledger.ts loopEvent), one per transition: an entry whose event would say
// just what its key's last one said is not logged again. A wake's turn taking its id, its
// reminder going out, and a turn that starts inside its submit (so turn.start moves the entry
// before the executor finishes it) each change the entry but not its event (run 2, #536). A
// failed log is noted, never retried.
export async function logLoop(env: Pick<ActEnv, 'io' | 'rt' | 'commands' | 'problems' | 'live'>, entries: readonly LedgerEntry[]): Promise<void> {
  const cmd = commandOf(env.io, env.rt, env.commands)
  const logged = (env.live.logged ??= new Map())
  for (const entry of entries) {
    const argv = loopEvent(entry)
    if (argv === null) continue
    const said = JSON.stringify(argv)
    if (logged.get(entry.key) === said) continue
    logged.set(entry.key, said)
    try {
      const r = await cmd(argv, { timeoutMs: EVENT_TIMEOUT_MS })
      if (r.exitCode !== 0) env.problems.push(clip(`loop event ${entry.key}: exit ${r.exitCode}`))
    } catch (err) {
      env.problems.push(clip(`loop event ${entry.key}: ${message(err)}`))
    }
  }
  // a key the ledger no longer holds (pruned, or a notice a retry cleared) is forgotten
  const held = new Set(env.live.ledger.map(e => e.key))
  for (const key of logged.keys()) if (!held.has(key)) logged.delete(key)
}

// --- one pass's actions ------------------------------------------------------------------------

// One action's result, for the decision log (v2 SPEC 13.12); at: when it started, for the trace (#552),
// absent for an action held before it started.
export type ActOutcome = { key: string; kind: ActionKind; status: Exec['status']; ms: Ms; summary: string; at?: Ms }

export type ActReport = {
  outcomes: ActOutcome[]
  // an executor met a GitHub rate limit: register sets the backoff (v2 SPEC 13.10 item 2)
  rateLimited: boolean
  // the title the title action set, when it did
  title: string | null
  // the kill switch stopped the pass between actions: register shows the loop off at once
  killed: boolean
}

// runActions: plan's actions in plan's order (finish in-flight work before starting new work).
// The kill switch is asked before each action but the title (bookkeeping only): an action
// already running finishes, and once the switch is seen every action left is skipped (#557).
export async function runActions(env: ActEnv, state: State, actions: readonly Action[]): Promise<ActReport> {
  const report: ActReport = { outcomes: [], rateLimited: false, title: null, killed: false }
  for (const action of actions) {
    if (!report.killed && action.kind !== 'title' && (await env.killed())) report.killed = true
    if (report.killed) {
      report.outcomes.push({ key: action.key, kind: action.kind, status: 'skipped', ms: 0, summary: 'kill switch' })
      continue
    }
    if (!(await env.holds())) {
      report.outcomes.push({ key: action.key, kind: action.kind, status: 'skipped', ms: 0, summary: 'held: the act lock is no longer this session\'s' })
      continue
    }
    if (report.rateLimited && GITHUB_V2.includes(action.kind)) {
      report.outcomes.push({ key: action.key, kind: action.kind, status: 'skipped', ms: 0, summary: 'held: GitHub rate limit met this pass' })
      continue
    }
    const out = await actOne(env, state, action)
    report.outcomes.push(out.outcome)
    if (out.exec.status === 'failed' && out.exec.rateLimited === true) report.rateLimited = true
    if (action.kind === 'title' && out.exec.status === 'done') report.title = action.text
  }
  return report
}

// actOne: one action through the ledger (v2 SPEC 13.7): start (a retry keeps the key and counts an
// attempt), the usage pre-check for start, develop and drive (a refusal puts the entry back as
// it stood, v2 SPEC 13.10 item 7), the running entry saved, the executor, then finish with its Exec and
// { config, prev }. The title is compared, not keyed (v2 SPEC 13.5.8 O1), so it runs without an entry.
export async function actOne(env: ActEnv, state: State, action: Action): Promise<{ outcome: ActOutcome; exec: Exec }> {
  const t0 = await env.io.now()
  const done = async (exec: Exec) => {
    const ms = (await env.io.now()) - t0
    return { exec, outcome: { key: action.key, kind: action.kind, status: exec.status, ms, summary: clip(exec.summary), at: t0 } }
  }
  if (action.kind === 'title') return done(await dispatch(ctxOf(env, state, start([], action, t0).entry), action))

  const s = start(env.live.ledger, action, t0, env.session)
  // no loop event yet: the start and its finish are one transition, logged once
  env.live.ledger = s.ledger
  const opts = { config: env.rt.config, prev: s.prev }
  const refused = await preCheck({ usage: env.io.usage, now: env.io.now }, action, env.rt.config, state.control.usageOverride)
  if (refused !== null) {
    const now = await env.io.now()
    env.live.ledger = finish(env.live.ledger, action.key, refused, now, opts)
    await env.save()
    return done(refused)
  }
  // the entry is in the store, running, before anything happens: a reload, a crash or a restart
  // (restart-self ends the session) mid-action finds it and marks it lost, so its attempt counts
  // and its rule re-derives what to do (v2 SPEC 13.7.5). A ledger that cannot be saved starts nothing.
  if (!(await env.save())) {
    const held: Exec = { status: 'skipped', summary: 'held: the ledger was not saved, so nothing starts' }
    env.live.ledger = finish(env.live.ledger, action.key, held, await env.io.now(), opts)
    return done(held)
  }
  const exec = await dispatch(ctxOf(env, state, s.entry), action)
  await record(env, action.key, s.entry, exec, opts)
  return done(exec)
}

// record: finish the attempt with the executor's Exec, saved before its loop event, unless a hook
// already ended it: a wake answered (or a tell delivered) before its submit returned stays
// answered, and an entry a later attempt or a hook replaced is left alone (v2 SPEC 13.8.2, wake.ts
// onTurnStart); the hook saved it.
async function record(
  env: ActEnv,
  key: string,
  started: LedgerEntry,
  exec: Exec,
  opts: { config: Runtime['config']; prev: LedgerEntry | null },
): Promise<void> {
  const now = await env.io.now()
  const current = env.live.ledger.find(e => e.key === key)
  if (current === undefined || current.startedAt !== started.startedAt || current.attempts !== started.attempts) return
  if (exec.status === 'running' && current.status !== 'running') return
  const moved = transition(env.live, l => finish(l, key, exec, now, opts))
  await env.save()
  await logLoop(env, moved)
}

// --- notices from outside plan (v2 SPEC 13.9.2, 13.11.2, 13.11.4) --------------------------------------------

// openWake: a judge, task or tell that is still running. Only one wake is open at a time (O2).
export function openWake(ledger: readonly LedgerEntry[]): LedgerEntry | undefined {
  return ledger.find(e => e.status === 'running' && WAKES.includes(e.kind))
}

// sendNotice: a tell that comes from outside plan (a rail, the ping breaker, failing passes) goes
// out through the wake executor under its own key, once, and only while no wake is open: a key
// the ledger holds was sent, unless it was lost (the engine dropped it before its turn); an open
// wake keeps it waiting (the caller keeps it pending), as does the kill switch.
export async function sendNotice(env: ActEnv, state: State, tell: Action): Promise<'sent' | 'waiting' | 'failed'> {
  if (env.live.ledger.some(e => e.key === tell.key && e.status !== 'lost')) return 'sent'
  if (openWake(env.live.ledger) !== undefined || (await env.killed())) return 'waiting'
  const { exec } = await actOne(env, state, tell)
  return exec.status === 'running' || exec.status === 'done' ? 'sent' : 'failed'
}

// passErrorTell: three passes in a row threw (v2 SPEC 13.10 item 9): the owner hears of it once per spell.
export function passErrorTell(since: Ms, passes: number, error: string): Action {
  return {
    kind: 'tell',
    wake: 'pass-error',
    key: `tell:pass-error:${since}`,
    class: 'owner',
    rule: 'O2',
    reason: 'tell pass-error',
    issue: null,
    fields: { passes: String(passes) },
    context: [`last error: ${error.replace(/\s+/g, ' ').slice(0, 300)}`],
  }
}

// --- rate-cap holds (v2 SPEC 13.11.4, D-24) ---------------------------------------------------------------

// capKey: a rate cap plan tripped (a bucket, or '<kind>:<issue>') as its hourly loop event's key.
export function capKey(capped: string, now: Ms): string {
  return `cap:${capped}:${Math.floor(now / HOUR)}`
}

// capEventArgv: a rate-cap hold has no ledger entry of its own, so its `loop` event is built
// here: one per capped bucket or kind and issue per hour, status held.
export function capEventArgv(capped: string, now: Ms): string[] {
  const [kind = capped, issue] = capped.split(':')
  const argv = ['callum-flow-event', 'loop']
  if (issue !== undefined && /^\d+$/.test(issue)) argv.push('--issue', issue)
  argv.push('--note', `kind=${kind} key=${capKey(capped, now)} status=held`)
  return argv
}

// breakerEventArgv: the ping-storm breaker opened (v2 SPEC 13.2, 13.11.4, D-39): its `loop` event, beside
// its one tell.
export function breakerEventArgv(b: BreakerNotice): string[] {
  return ['callum-flow-event', 'loop', '--note', `kind=breaker key=breaker:pings:${b.since} status=open passes=${b.passes} until=${b.until}`]
}

// --- what a reload and the agent list prove (v2 SPEC 13.3.3, 13.7.5, 13.10 item 4) --------------------------------

export type ListedAgent = { id: string; status: AgentStatus }

// How long an agent sent the repair message counts as at work while the list still shows its
// turn ended, idle or completed (reconcilable): the engine resumes it from its transcript (#548),
// and when the list shows that is not proven. Past it, the usual one pass of grace, then lost.
export const REPAIR_GRACE_MS = 5 * 60_000

// reconcilable: the agent list as reconcileAgents should judge it. An agent listed idle has ended
// its turn as one listed completed has (foundation.ts turnEnded, #560), and each rule here reads them
// alike. An agent whose answer is being handled counts as running, listed or not, so a pass in
// between never marks it lost: that covers an agent whose repair message is on its way, since
// agentAnswered holds it in `answering` until the engine answers the send. So does one whose
// turn ended within REPAIR_GRACE_MS of its repair message being delivered (repairing: when each
// went out, until its next turn.complete), for the loop awaits its reply; an agent first listed
// with its turn ended counts as running for that pass, since its turn.complete may still be on
// its way (seen: when each id was first so listed, idle then completed being one sighting). seen
// and repairing are updated in place. So does a gated writer whose answer is held for its stop
// gate line (gateHeld: since when), within holdMs, listed or not: the hold, not the list, says
// when its step ends.
export function reconcilable(
  agents: readonly ListedAgent[],
  answering: ReadonlySet<string>,
  seen: Map<string, Ms>,
  now: Ms,
  repairing: Map<string, Ms>,
  gateHeld: Map<string, Ms> = new Map(),
  holdMs: Ms = 0,
): ListedAgent[] {
  for (const [id, at] of [...repairing]) if (now - at > REPAIR_GRACE_MS) repairing.delete(id)
  // a hold past its bound counts for nothing here but stays in the map: gateRule (steps.ts) owns its
  // start and takes the answer once the bound runs out, which a deleted hold would restart
  const holding = (id: string): boolean => {
    const at = gateHeld.get(id)
    return at !== undefined && now - at <= holdMs
  }
  const out = agents.map(a => {
    if (answering.has(a.id) || holding(a.id)) return { id: a.id, status: 'running' as AgentStatus }
    if (!turnEnded(a.status)) return a
    if (repairing.has(a.id)) return { id: a.id, status: 'running' as AgentStatus }
    const first = seen.get(a.id)
    if (first === undefined) seen.set(a.id, now)
    return first === undefined || first === now ? { id: a.id, status: 'running' as AgentStatus } : a
  })
  for (const id of [...answering, ...[...gateHeld.keys()].filter(holding)]) if (!agents.some(a => a.id === id) && !out.some(a => a.id === id)) out.push({ id, status: 'running' })
  for (const id of [...seen.keys()]) if (!agents.some(a => a.id === id && turnEnded(a.status))) seen.delete(id)
  return out
}

// updateDone: rule H4's restart for this update ran and the workspace came back: its entry is
// lost (the session restarted under it), or done before this module loaded. dev-restart-self
// returns once Coder accepts the build, minutes before the container is replaced, so a restart
// this module saw end is not done yet: the drain holds until the new session loads (D-15).
// control.updateDue is then cleared, or the loop would drain forever. A failed restart keeps the
// drain, and plan tells the owner (agent-failed).
export function updateDone(ledger: readonly LedgerEntry[], control: Control, loadedAt: Ms): boolean {
  const due = control.updateDue
  if (due === null) return false
  const restart = ledger.find(e => e.key === `restart:${due.at}`)
  return restart?.status === 'lost' || (restart?.status === 'done' && (restart.endedAt ?? loadedAt) < loadedAt)
}

// --- one act-mode pass, from what observe read (v2 SPEC 13.2) --------------------------------------------

// What the hooks between passes share with the pass: the agents whose answer is being handled,
// when each agent was first listed with its turn ended (idle or completed), and when each was
// sent its repair message (reconcilable), and since when each gated writer's answer has waited for
// its stop gate line (steps-gate.ts).
export type Between = { answering: Set<string>; completedSeen: Map<string, Ms>; repairing: Map<string, Ms>; gateHeld: Map<string, Ms> }

// The pass's agent list: only a read that worked may mark agents lost.
export type Listed = { ok: boolean; agents: ListedAgent[] }

// planned: when plan handed its actions over and how long it took (performance.now()), for the
// trace (#552)
export type Acted = { state: State; result: PlanResult; report: ActReport; planned: { at: Ms; ms: number } }

// planPass: the planner's plan (v2 SPEC 2.3).
export function planPass(state: State, config: Config): PlanResult {
  return planV2(state, config)
}

// finishAsRead: an answer read for an entry, applied only while the entry still runs as it was
// read (its turn.complete may have finished it during the read); the entries it moved.
function finishAsRead(env: ActEnv, was: LedgerEntry, exec: Exec, now: Ms): LedgerEntry[] {
  const current = env.live.ledger.find(e => e.key === was.key)
  if (current?.status !== 'running' || current.agentId !== was.agentId || current.startedAt !== was.startedAt) return []
  return transition(env.live, l => finish(l, was.key, exec, now, { config: env.rt.config }))
}

// answeredBeforeLost: the agent entries the agent list would mark lost (gone from it, or its turn
// ended with no answer read) whose agent recorded an answer with the answer script that passes its
// checks (#561): each is finished with that answer, as its turn.complete would have finished it
// (act-agents.ts scriptAnswered). An entry its turn.complete finished during the read is left
// alone.
async function answeredBeforeLost(env: ActEnv, state: State, agents: readonly ListedAgent[], now: Ms, between: Between): Promise<LedgerEntry[]> {
  const before = env.live.ledger
  // reconcileAgents keeps the ledger's order, entry for entry
  const reconciled = reconcileAgents(before, agents, now)
  const lost = before.filter((e, i) => e.status === 'running' && reconciled[i]?.status === 'lost')
  const moved: LedgerEntry[] = []
  for (const was of lost) {
    // a gated writer with no settling gate line is held (gateHeld), not lost: reconcilable then counts it
    const exec = await stepRecorded(ctxOf(env, state, was), was, true, undefined, between.gateHeld)
    if (exec !== null) moved.push(...finishAsRead(env, was, exec, now))
  }
  return moved
}

// actPass: the act-mode pass once the rails passed and observe read the factory: what the agent
// list proves (v2 SPEC 13.3.3, 13.10 item 4) and wakes past their timeout (v2 SPEC 13.8.2) go into the ledger first,
// then plan reads the state with that ledger, and its actions run in plan's order.
export async function actPass(env: ActEnv, observed: State, listed: Listed, between: Between): Promise<Acted> {
  const now = observed.now
  const moved: LedgerEntry[] = []
  if (listed.ok) {
    const holdMs = gateHoldMs(env.rt.config)
    const of = () => reconcilable(listed.agents, between.answering, between.completedSeen, now, between.repairing, between.gateHeld, holdMs)
    moved.push(...(await answeredBeforeLost(env, observed, of(), now, between)))
    // an entry that ended, or whose agent is gone from the ledger, holds nothing
    for (const id of [...between.gateHeld.keys()]) if (!env.live.ledger.some(e => e.agentId === id && e.status === 'running')) between.gateHeld.delete(id)
    const agents = of()
    moved.push(...transition(env.live, l => reconcileAgents(l, agents, now)))
  }
  for (const u of expireWakes(env.live.ledger, now, env.rt.config)) moved.push(...transition(env.live, l => finish(l, u.key, u, now)))
  // a recorded answer ends its step when read (v2 SPEC 10.8)
  for (const r of await stepAnswers(env.live.ledger, e => ctxOf(env, observed, e), undefined, between.gateHeld)) moved.push(...finishAsRead(env, r.entry, r.exec, now))
  if (moved.length > 0) {
    await env.save()
    await logLoop(env, moved)
  }
  const state = { ...observed, ledger: env.live.ledger }
  const from = performance.now()
  const result = planPass(state, env.rt.config)
  const planned = { ms: performance.now() - from, at: await env.io.now() }
  const report = await runActions(env, state, result.actions)
  return { state, result, report, planned }
}

// --- small helpers --------------------------------------------------------------------------------

export function clip(text: string): string {
  return text.length > SUMMARY_MAX ? `${text.slice(0, SUMMARY_MAX - 3)}...` : text
}

function message(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

files.hooks/act-between.ts:
// Between passes: the hooks that feed the ledger (v2 SPEC 13.2, 13.8.2, 13.10 item 4). What an agent's answer, a
// wake's turn, the wake answer tool and `/factory retry` do to the live ledger. act.ts holds the
// pass and the executors; this module reads them and is read by driver-between.ts alone, so nothing
// here is imported back by act.ts.
import { clip, ctxOf, logLoop, transition } from './act'
import type { ActEnv, Between } from './act'
import type { AgentAnswer } from './exec'
import { finish, retryIssue } from './ledger'
import type { LedgerEntry, State } from './types'
import { stepAnswered } from './v2/steps'
import { answerTool, onTurnComplete, onTurnStart } from './wake'
import type { TurnEnd } from './wake'

// The one repair message to an agent of the loop, of the type it runs as (a step's agent type,
// plugin:name): null once delivered, else why not, in the engine's own words.
export type Repair = (agentId: string, text: string, type: `${string}:${string}`) => Promise<string | null>

// What an agent's answer did: 'applied' (its entry finished; repaired when a repair message went
// out before it), 'repair' (unreadable, so the agent was asked once more), 'recorded' (its tool
// already answered), 'held' (a gated writer's answer waits for its stop gate line, the entry
// running on), 'dropped' or 'not ours'. key: its entry; undelivered: why its repair message
// was not delivered, whole, for the decision log (the entry's summary keeps a clipped copy, #559).
export type Answered = {
  result: 'applied' | 'repair' | 'held' | 'recorded' | 'dropped' | 'not ours'
  why?: string
  key?: string
  repaired?: boolean
  undelivered?: string
}

// agentAnswered: an agent step of the loop finished (its turn.complete): its answer is read by
// steps.ts (the file it recorded with the answer script) and its entry finished. 'applied' asks
// for a pass. An agent the ledger never held is 'not ours'; an answer for an entry that no longer
// runs (a stop timed it out, a retry replaced it) is logged and dropped, never applied. An answer
// that does not read first gets one repair message to the same agent, naming what was wrong and
// asking again (#548, #561): the entry runs on with its attempt unspent, and only an answer still
// unreadable after it, or a message that could not be delivered, fails the attempt as before.
export async function agentAnswered(
  env: ActEnv,
  state: State,
  answer: AgentAnswer,
  between: Between,
  repair: Repair = async () => 'the loop sends no messages from here',
): Promise<Answered> {
  const id = answer.agentId
  const entry = env.live.ledger.find(e => e.agentId === id && e.kind === 'agent-step')
  if (entry === undefined) return { result: 'not ours' }
  if (entry.status === 'done') return { result: 'recorded', key: entry.key }
  if (entry.status !== 'running') return { result: 'dropped', why: `late answer for ${entry.key} (${entry.status})` }
  between.answering.add(id)
  between.repairing.delete(id)
  try {
    // a v2 agent step's answer is read by steps.ts, and is never interim (v2 SPEC 10.8)
    const step = await stepAnswered(ctxOf(env, state, entry), entry, answer, undefined, between.gateHeld)
    // a gated writer's turn ended before its stop gate line: the entry runs on until a pass finds it
    if (step.held === true) return { result: 'held', key: entry.key }
    let exec = step.exec
    const ours = (e: LedgerEntry | undefined): e is LedgerEntry => e !== undefined && e.agentId === id && e.startedAt === entry.startedAt
    const still = () => {
      const current = env.live.ledger.find(e => e.key === entry.key)
      return ours(current) && current.status === 'running' ? current : null
    }
    // the attempt no longer runs: a stop or a retry ended it
    const ended = (): Answered => {
      const current = env.live.ledger.find(e => e.key === entry.key)
      return ours(current) && current.status === 'done' ? { result: 'recorded', key: entry.key } : { result: 'dropped', why: `answer for ${entry.key} came after the entry ended` }
    }
    if (still() === null) return ended()
    const at = await env.io.now()
    const current = still()
    if (current === null) return ended()
    const repaired = current.reminded === true
    let refused: string | undefined
    if (step.repair !== null && !repaired) {
      const problem = step.problem ?? 'no machine line'
      // the repair is on the entry before it goes out, so a reload never sends a second one
      const marked = transition(env.live, l => finish(l, entry.key, { status: 'running', reminded: true }, at))
      await env.save()
      await logLoop(env, marked)
      // a v2 step's own repair asks for the script again
      const undelivered = await repair(id, step.repair, step.subagentType)
      if (undelivered === null) {
        // listed idle or completed until the message resumes it, which the list may show late: the
        // passes take it as at work for a while, then count that listing afresh
        between.completedSeen.delete(id)
        between.repairing.set(id, at)
        return { result: 'repair', why: problem, key: entry.key }
      }
      refused = undelivered
      exec = { ...exec, summary: clip(`${exec.summary}; the repair message was not delivered: ${undelivered}`) }
    }
    const now = await env.io.now()
    if (still() === null) return ended()
    const moved = transition(env.live, l => finish(l, entry.key, exec, now, { config: env.rt.config }))
    await env.save()
    await logLoop(env, moved)
    const applied: Answered = { result: 'applied', key: entry.key, repaired }
    if (refused !== undefined) applied.undelivered = refused
    return applied
  } finally {
    between.answering.delete(id)
  }
}

// The refusal of a tool call that could not be decided in time (#558): the agent answers in text.
export const TOOL_LATE = 'Not recorded: the factory loop could not check this answer in time; reply with your text lines instead.'

// Asked just before a tool call changes the ledger: false once the caller has answered the call
// without it (register.ts bounded), and then nothing changes.
export type Claim = () => boolean

// keep: what follows a transition a hook made at once in the live ledger (#558): the ledger
// saved, then the moved entries' loop events.
export async function keep(env: ActEnv, moved: readonly LedgerEntry[]): Promise<void> {
  if (moved.length === 0) return
  await env.save()
  await logLoop(env, moved)
}

const WAKE_HEAD = /^(JUDGE|TASK|TELL) /m

// wakeStarted: a turn that opens with a wake's first line is that wake's turn (wake.ts
// onTurnStart). A frame the engine puts before a plugin's prompt is skipped to that line.
export async function wakeStarted(env: ActEnv, said: string, turnId: string): Promise<boolean> {
  const at = said.search(WAKE_HEAD)
  if (at < 0) return false
  const now = await env.io.now()
  const u = onTurnStart(env.live.ledger, said.slice(at), turnId)
  if (u === null) return false
  const moved = transition(env.live, l => finish(l, u.key, u, now))
  await env.save()
  await logLoop(env, moved)
  return true
}

// wakeEnded: a main-loop turn ended (wake.ts onTurnComplete): its ANSWER blocks close their
// wakes, a tell's own turn delivers it, an unanswered wake gets its one reminder. The caller
// submits the prompts (never awaiting them inside the turn's own hook), logs the problems, and
// pings when a wake moved.
export async function wakeEnded(env: ActEnv, turn: TurnEnd): Promise<{ moved: boolean; prompts: string[]; problems: string[] }> {
  const now = await env.io.now()
  const out = onTurnComplete(env.live.ledger, turn, env.rt.repo)
  const moved = out.updates.flatMap(u => transition(env.live, l => finish(l, u.key, u, now)))
  if (moved.length > 0) {
    await env.save()
    await logLoop(env, moved)
  }
  return { moved: out.updates.length > 0, prompts: out.prompts, problems: out.problems }
}

// wakeAnswered: mcp__factory-loop__answer, checked as the ANSWER block is (wake.ts answerTool)
// and recorded in the live ledger at once, with no await between the check and the change, as an
// agent's tool was (#558); `moved` asks for keep, once the call has its answer. claim: asked
// just before the ledger changes.
export async function wakeAnswered(
  env: ActEnv,
  input: unknown,
  agentId: string | undefined,
  claim: Claim = () => true,
): Promise<{ ok: boolean; text: string; moved: LedgerEntry[] }> {
  const now = await env.io.now()
  const r = answerTool(env.live.ledger, input, env.rt.repo, agentId === undefined ? {} : { agentId })
  const update = r.update
  if (update === null) return { ok: r.ok, text: r.text, moved: [] }
  if (!claim()) return { ok: false, text: TOOL_LATE, moved: [] }
  return { ok: r.ok, text: r.text, moved: transition(env.live, l => finish(l, update.key, update, now)) }
}

// retried: `/factory retry <N>` clears the issue's exhausted entries in the live ledger at once
// (D-38, ledger.ts retryIssue): the keys it cleared, and the entries it moved, for keep once the
// op has its answer (#558).
export function retried(env: Pick<ActEnv, 'live' | 'rt'>, issue: number): { cleared: string[]; moved: LedgerEntry[] } {
  let cleared: string[] = []
  const moved = transition(env.live, l => {
    const r = retryIssue(l, issue, env.rt.config)
    cleared = r.cleared
    return r.ledger
  })
  return { cleared, moved }
}

