// The safety rails (v2 SPEC 13.2, 13.10 item 7, 13.11.2, 13.11.4; DECISIONS D-28, D-39): what must hold before the
// loop acts at all, the usage pre-check before each token-spending action, and the pass
// scheduler with its ping-storm breaker. Every decision is a pure function over a file's text, a
// query's rows or a clock reading; the thin wrappers read files and run commands through the io
// the driver passes, so the tests and the replay drive the decisions without the engine. Every
// rail fails safe: a read it cannot make keeps the loop in observe, with its own reason.
import type { ActIo, Exec, ExecCtx } from './exec'
import { parseCsv } from './parse'
import { tierOf } from './foundation'
import { schemaRail } from './rail-schema'
import type { SchemaNotice } from './rail-schema'
import type { Action, ActionClass, Config, Control, Ms, Tier } from './types'

const SECOND = 1_000
const MINUTE = 60_000
const PROBE_TIMEOUT_MS = 10_000
const QUERY_TIMEOUT_MS = 30_000
// flock waits 5 s for another session's write of the lock; the whole write is well inside this
const LOCK_TIMEOUT_MS = 15_000

// What a rail reads and runs: the ledger-free part of ActIo and ExecCtx, since the rails run at
// the start of a pass, before any action has an entry.
export type LockIo = Pick<ActIo, 'readFile'> & { cmd: ExecCtx['cmd'] }
export type RailIo = LockIo

// --- the act lock (v2 SPEC 13.11.2) ---------------------------------------------------------------

// A lease lasts a few passes and never under fifteen minutes: longer than the longest single step
// (a merge, 600 s, then its rollout read), so a step can never outlive it and let a second session
// in. The driver also renews it before every action and on a timer while a pass runs.
export const LEASE_PASSES = 5
export const LEASE_MIN_MS = 15 * MINUTE

export type Lease = { session: string; renewedAt: Ms; expiresAt: Ms }

export function actLockPath(loopDir: string): string {
  return `${loopDir}/act.lock`
}

export function leaseMsOf(config: Config): Ms {
  return Math.max(LEASE_PASSES * config.passEveryMs, LEASE_MIN_MS)
}

// parseLease: the lock file's lease; null for a missing, empty or malformed file, which any
// session may take (every write is a compare-and-set, so two cannot both take it).
export function parseLease(text: string | null): Lease | null {
  if (text === null) return null
  try {
    const v: unknown = JSON.parse(text)
    if (v === null || typeof v !== 'object' || Array.isArray(v)) return null
    const o = v as Record<string, unknown>
    const ms = (x: unknown): x is number => typeof x === 'number' && Number.isFinite(x)
    if (typeof o.session !== 'string' || o.session === '' || !ms(o.renewedAt) || !ms(o.expiresAt)) return null
    return { session: o.session, renewedAt: o.renewedAt, expiresAt: o.expiresAt }
  } catch {
    return null
  }
}

export function leaseText(lease: Lease): string {
  return JSON.stringify(lease) + '\n'
}

// took: the other session's expired lease this one replaced, for the decision log.
export type LockDecision = { hold: true; lease: Lease; took: Lease | null } | { hold: false; holder: Lease }

// decideLock: renew this session's own lease, take a missing or expired one, and refuse while
// another session's lease is live (up to the instant it expires).
export function decideLock(text: string | null, session: string, now: Ms, leaseMs: Ms): LockDecision {
  const current = parseLease(text)
  if (current !== null && current.session !== session && now < current.expiresAt) return { hold: false, holder: current }
  return {
    hold: true,
    lease: { session, renewedAt: now, expiresAt: now + leaseMs },
    took: current !== null && current.session !== session ? current : null,
  }
}

// releasedLease: this session's lease, expired now, for session.end; null when the file holds no
// lease of this session's (another session's lease is never touched).
export function releasedLease(text: string | null, session: string, now: Ms): Lease | null {
  const current = parseLease(text)
  if (current === null || current.session !== session) return null
  return { ...current, expiresAt: Math.min(current.expiresAt, now) }
}

export type LockResult = { held: true; lease: Lease; took: Lease | null } | { held: false; reason: string }

function heldBy(lease: Lease): string {
  return `act lock: session ${lease.session} holds it until ${new Date(lease.expiresAt).toISOString()}`
}

// The lock file's one writer: a compare-and-set under flock(1), the kernel lock a dying process
// lets go of. $1 the lock, $2 its text as this session read it (empty when missing), the new
// lease on stdin. It writes only while the file still holds what was read, and lands by rename,
// so of two sessions that both read the lock free one writes and the other gets exit 3, and no
// reader ever sees half a lease. Exit 2: the file cannot be written; 4: flock timed out.
export const LOCK_CAS_SCRIPT = [
  'mkdir -p -- "${1%/*}" || exit 2',
  'exec 9>>"$1.flock" || exit 2',
  'flock -w 5 9 || exit 4',
  'cur=$(cat -- "$1" 2>/dev/null)',
  '[ "$cur" = "$2" ] || exit 3',
  'cat > "$1.$$" && mv -f -- "$1.$$" "$1" || exit 2',
].join('\n')

// lockCasArgv: the compare-and-set of one lease; `read` is the file's text as read (null: none).
// The shell's $(cat) drops trailing newlines, so the expected text is compared without them.
export function lockCasArgv(path: string, read: string | null): string[] {
  return ['sh', '-c', LOCK_CAS_SCRIPT, 'act-lock', path, (read ?? '').replace(/\n+$/, '')]
}

// writeLease: the lease written over the text read, or why not.
async function writeLease(io: LockIo, path: string, read: string | null, lease: Lease): Promise<'written' | 'changed' | string> {
  const r = await io.cmd(lockCasArgv(path, read), { stdin: leaseText(lease), timeoutMs: LOCK_TIMEOUT_MS })
  if (r.exitCode === 0) return 'written'
  if (r.exitCode === 3) return 'changed'
  const why = r.stderr.trim().split('\n').pop() ?? ''
  return `act lock: ${path} not written (exit ${r.exitCode}${why === '' ? '' : `: ${why.slice(0, 200)}`})`
}

// holdActLock: acquire or renew the lease. The write is a compare-and-set (LOCK_CAS_SCRIPT), so a
// lease that changed since it was read is never written over: whoever holds it now decides.
export async function holdActLock(io: LockIo, path: string, session: string, now: Ms, leaseMs: Ms): Promise<LockResult> {
  if (session === '') return { held: false, reason: 'act lock: this session has no id' }
  try {
    const read = await io.readFile(path)
    const d = decideLock(read, session, now, leaseMs)
    if (!d.hold) return { held: false, reason: heldBy(d.holder) }
    const wrote = await writeLease(io, path, read, d.lease)
    const back = parseLease(await io.readFile(path))
    if (wrote === 'changed') {
      // another session took it meanwhile, or this one renewed it from elsewhere (still ours)
      if (back !== null && back.session === session && now < back.expiresAt) return { held: true, lease: back, took: null }
      return { held: false, reason: back === null ? `act lock: ${path} changed while it was taken` : heldBy(back) }
    }
    if (wrote !== 'written') return { held: false, reason: wrote }
    if (back === null) return { held: false, reason: `act lock: ${path} did not read back` }
    if (back.session !== session) return { held: false, reason: heldBy(back) }
    return { held: true, lease: d.lease, took: d.took }
  } catch (err) {
    return { held: false, reason: `act lock: ${String(err).slice(0, 200)}` }
  }
}

// releaseActLock: at session.end, expire this session's lease so the next session acts at once.
export async function releaseActLock(io: LockIo, path: string, session: string, now: Ms): Promise<boolean> {
  try {
    const read = await io.readFile(path)
    const released = releasedLease(read, session, now)
    if (released === null) return false
    return (await writeLease(io, path, read, released)) === 'written'
  } catch {
    return false
  }
}

// --- the role (v2 SPEC 13.11.2, D-28) ---------------------------------------------------------------

export const ORCHESTRATOR_ROLE = 'orchestrator'

// roleProblem: a desktop session with the plugin installed never acts by accident; the
// repo-local allowActOutsideOrchestrator lifts it for a testbed.
export function roleProblem(role: string | undefined, config: Config): string | null {
  if (role === ORCHESTRATOR_ROLE || config.allowActOutsideOrchestrator) return null
  return `role: DEV_ROLE is ${role ? role : 'unset'}, act needs ${ORCHESTRATOR_ROLE}`
}

// --- the old watcher (v2 SPEC 13.11.2, D-28) ----------------------------------------------------------

// The session environment the rails read: the role, and what orchestrator-watch.sh places its
// lock by.
export type RailEnv = {
  DEV_ROLE?: string
  ORCHESTRATOR_WATCH_LOCK_DIR?: string
  XDG_RUNTIME_DIR?: string
  TMPDIR?: string
  // the startup migrate's status file (rail-schema.ts)
  DEV_FACTORY_DB_MIGRATE_STATUS?: string
}

// watcherLockPath: the lock orchestrator-watch.sh takes for a repo, computed as it does:
// ${ORCHESTRATOR_WATCH_LOCK_DIR:-${XDG_RUNTIME_DIR:-${TMPDIR:-/tmp}}} (an empty value falls
// through, as `:-` does), then the repo with every byte outside A-Za-z0-9._- made `_` (GNU tr
// works on bytes, so a multibyte character gives one `_` per byte).
export function watcherLockPath(env: RailEnv, repo: string): string {
  const dir = env.ORCHESTRATOR_WATCH_LOCK_DIR || env.XDG_RUNTIME_DIR || env.TMPDIR || '/tmp'
  let safe = ''
  for (const ch of repo) {
    const cp = ch.codePointAt(0) ?? 0
    safe += /^[A-Za-z0-9._-]$/.test(ch) ? ch : '_'.repeat(cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4)
  }
  return `${dir}/orchestrator-watch-${safe}.lock`
}

// pidOf: the pid file's text as `$(cat "$lock/pid")` gives it (trailing newlines dropped). The
// watcher writes its own `$$`, always decimal, so nothing else is probed.
export function pidOf(text: string | null): string | null {
  const p = (text ?? '').replace(/\n+$/, '')
  return /^[0-9]+$/.test(p) ? p : null
}

// namesWatcher: /proc/<pid>/cmdline as `tr '\0' ' ' | grep -q orchestrator-watch` reads it.
export function namesWatcher(cmdline: string): boolean {
  return cmdline.replace(/\0/g, ' ').includes('orchestrator-watch')
}

// watcherAlive: the watcher's own alive_watcher: `kill -0` reached the pid, and its cmdline is
// unreadable (no /proc) or names the watcher, so a pid reused by another program is stale.
export function watcherAlive(signalled: boolean, cmdline: string | null): boolean {
  return signalled && (cmdline === null || namesWatcher(cmdline))
}

export type WatcherCheck = { kind: 'none' } | { kind: 'live'; pid: string; path: string } | { kind: 'error'; reason: string }

// findWatcher: a live orchestrator-watch.sh lock for the repo, as given and lower-cased (the
// skill's REPO and the origin URL may differ in case). The pid reaches each command as an
// argument, never inside a shell string. A lock directory with no readable decimal pid blocks
// (fail safe): its owner may be between mkdir and writing its pid, and a stale one is the
// watcher's own to take over.
export async function findWatcher(io: RailIo, env: RailEnv, repo: string): Promise<WatcherCheck> {
  const paths = [...new Set([watcherLockPath(env, repo), watcherLockPath(env, repo.toLowerCase())])]
  for (const path of paths) {
    try {
      const pid = pidOf(await io.readFile(`${path}/pid`))
      if (pid === null) {
        const dir = await io.cmd(['test', '-d', path], { timeoutMs: PROBE_TIMEOUT_MS })
        if (dir.exitCode === 1) continue
        return { kind: 'error', reason: `old watcher: ${path} ${dir.exitCode === 0 ? 'exists with no readable pid' : `cannot be checked (exit ${dir.exitCode})`}` }
      }
      // signal 0 delivers nothing: it only asks whether the pid exists
      const probe = await io.cmd(['sh', '-c', 'kill -0 "$1" 2>/dev/null', 'sh', pid], { timeoutMs: PROBE_TIMEOUT_MS })
      if (probe.exitCode === 1) continue
      if (probe.exitCode !== 0) return { kind: 'error', reason: `old watcher: cannot probe pid ${pid} (exit ${probe.exitCode})` }
      const proc = await io.cmd(['cat', `/proc/${pid}/cmdline`], { timeoutMs: PROBE_TIMEOUT_MS })
      if (watcherAlive(true, proc.exitCode === 0 ? proc.stdout : null)) return { kind: 'live', pid, path }
    } catch (err) {
      return { kind: 'error', reason: `old watcher: cannot check ${path}: ${String(err).slice(0, 200)}` }
    }
  }
  return { kind: 'none' }
}

// --- the heartbeat guard (D-28) -----------------------------------------------------------------

// Another orchestrator's heartbeat this recent holds acting, and the same window is the quiet the
// loop waits for once it stops (heartbeat-loop beats every 60 s, so a live one is never quiet).
export const HEARTBEAT_QUIET_MS = 120 * SECOND

// Every other device's orchestrator row for the repo, aged by the database's clock through
// factory.workers_status, as heartbeat-loop asks readers to (it stores the repo lower-cased).
export const HEARTBEAT_SQL = `select device, extract(epoch from age) as age_s
from factory.workers_status
where role = 'orchestrator'
  and lower(repo) = lower(:'repo')
  and device <> :'device'
order by age, device;
`

export function heartbeatArgv(repo: string, device: string): string[] {
  return ['dev-query', '--csv', '-v', `repo=${repo}`, '-v', `device=${device}`]
}

export type Beat = { device: string; ageMs: Ms }

// parseBeats: the query's CSV as beats; null when it is not the query's output. A row with no
// age (no last_seen) is no heartbeat; a negative age (a clock step) counts as just now.
export function parseBeats(stdout: string): Beat[] | null {
  const header = (stdout.split(/\r?\n/, 1)[0] ?? '').trim()
  if (header !== 'device,age_s') return null
  return parseCsv(stdout).flatMap(row => {
    const device = row.device ?? ''
    const age = row.age_s === undefined || row.age_s.trim() === '' ? Number.NaN : Number(row.age_s)
    return device !== '' && Number.isFinite(age) ? [{ device, ageMs: Math.max(0, age * SECOND) }] : []
  })
}

// A blocking spell: when this loop first saw it, and the device it saw.
export type Spell = { since: Ms; device: string }

// notice: the spell that started this pass, told once (TELL heartbeat-other).
export type GuardVerdict = { ok: boolean; reason: string | null; spell: Spell | null; notice: Spell | null }

// heartbeatVerdict: block while any beat is at most HEARTBEAT_QUIET_MS old. A spell starts at
// the first pass that sees one, with its one notice, and ends at the first pass that sees none.
// A failed query (beats null) blocks too, fail safe, and leaves the spell as it was.
export function heartbeatVerdict(beats: Beat[] | null, prev: Spell | null, now: Ms, error = 'no output'): GuardVerdict {
  if (beats === null) return { ok: false, reason: `heartbeat: query failed (${error})`, spell: prev, notice: null }
  const recent = beats.filter(b => b.ageMs <= HEARTBEAT_QUIET_MS).sort((a, b) => a.ageMs - b.ageMs)
  const newest = recent[0]
  if (newest === undefined) return { ok: true, reason: null, spell: null, notice: null }
  const seen = recent.map(b => `${b.device} ${Math.round(b.ageMs / SECOND)}s ago`).join(', ')
  const spell = prev ?? { since: now, device: newest.device }
  return {
    ok: false,
    reason: `heartbeat: another orchestrator on this repo is up (${seen})`,
    spell,
    notice: prev === null ? spell : null,
  }
}

// heartbeatGuard: one dev-query per pass. A device with no name cannot tell its own beat from
// another's, so it refuses rather than guess.
export async function heartbeatGuard(io: RailIo, repo: string, device: string, prev: Spell | null, now: Ms): Promise<GuardVerdict> {
  if (device === '') {
    return { ok: false, reason: 'heartbeat: this device has no name (DEV_MACHINE_NAME), so its own beat cannot be told apart', spell: prev, notice: null }
  }
  try {
    const r = await io.cmd(heartbeatArgv(repo, device), { stdin: HEARTBEAT_SQL, timeoutMs: QUERY_TIMEOUT_MS })
    if (r.exitCode !== 0) {
      const last = r.stderr.trim().split('\n').pop()?.slice(0, 200) ?? ''
      return heartbeatVerdict(null, prev, now, `exit ${r.exitCode}${last === '' ? '' : `: ${last}`}`)
    }
    return heartbeatVerdict(parseBeats(r.stdout), prev, now, 'unexpected output')
  } catch (err) {
    return heartbeatVerdict(null, prev, now, String(err).slice(0, 200))
  }
}

// --- the rails together (v2 SPEC 13.11.2) ------------------------------------------------------------

// The released skill's single-shot watcher exits on every event and is armed again at the end of
// the model's turn, so its lock comes and goes while that skill drives. The loop acts only after
// the lock has been gone this long, which outlasts a turn's handling of an event.
export const WATCHER_QUIET_MS = 10 * MINUTE

// What the rails remember between passes, so each blocking spell is told once. Plain JSON: the
// driver keeps it beside the ledger in the store, so a reload does not tell a spell again.
// seenAt: the last pass that saw the watcher's lock, for its quiet window.
export type WatcherSpell = { since: Ms; pid: string; seenAt: Ms }
export type RailMemory = { heartbeat: Spell | null; watcher: WatcherSpell | null }
export const EMPTY_RAIL_MEMORY: RailMemory = { heartbeat: null, watcher: null }

export type RailNotice = { kind: 'heartbeat-other'; device: string; since: Ms } | { kind: 'old-watcher'; pid: string; since: Ms } | SchemaNotice

export type RailInput = {
  repo: string
  device: string
  // $.session.id(): the act lock's holder
  session: string
  loopDir: string
  config: Config
  env: RailEnv
  now: Ms
  memory: RailMemory
  // refusals the driver found itself (the checkout's repo), named first; they keep the lease alone
  refusals?: string[]
}

// act: every rail passed and this session holds the lease. reasons: each refusal, in the fixed
// order. lock: the lease outcome, null when another rail refused (the lease is left alone).
export type RailResult = { act: boolean; reasons: string[]; notices: RailNotice[]; memory: RailMemory; lock: LockResult | null }

// checkRails: run at the start of every act-mode pass, before any action, in a fixed order:
// the role, the old watcher, the heartbeat guard, the schema, then the act lock. The first four always run,
// so the log names every refusal and each spell is tracked; the lock is taken only when they
// pass. A session that fails the role check can never act, so it tells nothing.
export async function checkRails(io: RailIo, input: RailInput): Promise<RailResult> {
  const { config, env, now, memory } = input
  const reasons: string[] = [...(input.refusals ?? [])]
  const notices: RailNotice[] = []

  const role = roleProblem(env.DEV_ROLE, config)
  if (role !== null) reasons.push(role)

  const watcher = await findWatcher(io, env, input.repo)
  let watcherSpell = memory.watcher
  if (watcher.kind === 'live') {
    reasons.push(`old watcher: orchestrator-watch.sh holds ${watcher.path} (pid ${watcher.pid})`)
    if (watcherSpell === null) notices.push({ kind: 'old-watcher', pid: watcher.pid, since: now })
    watcherSpell = { since: watcherSpell?.since ?? now, pid: watcher.pid, seenAt: now }
  } else if (watcher.kind === 'error') {
    reasons.push(watcher.reason)
  } else if (watcherSpell !== null && now - watcherSpell.seenAt < WATCHER_QUIET_MS) {
    // gone between two of the released skill's turns, perhaps: the spell holds until it is quiet
    reasons.push(`old watcher: its lock was seen ${new Date(watcherSpell.seenAt).toISOString()}; acting after ${WATCHER_QUIET_MS / MINUTE} minutes without it`)
  } else {
    watcherSpell = null
  }

  const guard = await heartbeatGuard(io, input.repo, input.device, memory.heartbeat, now)
  if (guard.reason !== null) reasons.push(guard.reason)
  if (guard.notice !== null) notices.push({ kind: 'heartbeat-other', device: guard.notice.device, since: guard.notice.since })

  const schema = await schemaRail(io, env, now)
  if (schema.reason !== null) reasons.push(schema.reason)
  if (schema.notice !== null) notices.push(schema.notice)

  let lock: LockResult | null = null
  if (reasons.length === 0) {
    lock = await holdActLock(io, actLockPath(input.loopDir), input.session, now, leaseMsOf(config))
    if (!lock.held) reasons.push(lock.reason)
  }
  return {
    act: reasons.length === 0,
    reasons,
    notices: role === null ? notices : [],
    memory: { heartbeat: guard.spell, watcher: watcherSpell },
    lock,
  }
}

// --- the usage pre-check (v2 SPEC 13.10 item 7) -------------------------------------------------------------

// The classes each tier lets run: the planner's own matrix (ALLOWED in foundation.ts), mirrored
// here and held to its behaviour by rails.test.ts.
export const TIER_CLASSES: Record<Tier, readonly ActionClass[]> = {
  normal: ['free', 'owner', 'drive', 'develop', 'start'],
  slow: ['free', 'owner', 'drive', 'develop', 'start'],
  'stop-new': ['free', 'owner', 'drive'],
  'stop-all': ['free', 'owner'],
}

// The token-spending classes, read against the session's usage again just before they run.
export const PRECHECKED: readonly ActionClass[] = ['start', 'develop', 'drive']

export type UsageReading = { fiveHour: number | null; sevenDay: number | null }

const pct = (v: number | null) => (v === null ? 'n/a' : `${v}%`)

// usageVerdict: why this reading forbids the class now, or null. tierOf decides the tier, the
// owner's override included; a missing reading is Normal, as plan fails open.
export function usageVerdict(
  reading: UsageReading,
  klass: ActionClass,
  config: Config,
  override: Control['usageOverride'],
  now: Ms,
): string | null {
  if (!PRECHECKED.includes(klass)) return null
  const usage = { ...reading, fiveHourResetsAt: null, sevenDayResetsAt: null, unavailable: false }
  const { tier } = tierOf(usage, config, override, now)
  if (TIER_CLASSES[tier].includes(klass)) return null
  return `usage: tier ${tier} forbids ${klass} (5h ${pct(reading.fiveHour)}, 7d ${pct(reading.sevenDay)})`
}

// preCheck: before a start, develop or drive action, the session's usage read again (it is
// free); a tier that now forbids the class skips the action, no attempt counted, and the next
// pass re-plans. A failed read leaves plan's tier standing.
export async function preCheck(
  io: Pick<ActIo, 'usage' | 'now'>,
  action: Action,
  config: Config,
  override: Control['usageOverride'],
): Promise<Extract<Exec, { status: 'skipped' }> | null> {
  if (!PRECHECKED.includes(action.class)) return null
  let reading: UsageReading
  try {
    reading = await io.usage()
  } catch {
    return null
  }
  const why = usageVerdict(reading, action.class, config, override, await io.now())
  return why === null ? null : { status: 'skipped', summary: why }
}

// --- the pass scheduler and the ping-storm breaker (v2 SPEC 13.2, 13.11.4, D-39) --------------------------

export const PASS_GAP_MS = 5 * SECOND
export const STORM_PASSES = 30
export const STORM_WINDOW_MS = 10 * MINUTE
export const STORM_QUIET_MS = 10 * MINUTE

export type PassSource = 'ping' | 'timer'

export type Scheduler = {
  running: boolean
  // the one pass wanted next: the timer's when any tick asked for it, else a ping's
  queued: PassSource | null
  lastStart: Ms | null
  // a wait for the end of the gap is set (one timer, however many requests arrive)
  wakeAt: Ms | null
  // when each ping-driven pass of the last STORM_WINDOW_MS started
  pingStarts: Ms[]
  // the breaker: pings are ignored until then, timer ticks never are
  pingsIgnoredUntil: Ms | null
}

export type NextPass = { do: 'start'; source: PassSource } | { do: 'wait'; ms: Ms } | { do: 'idle' }

// The breaker's one notice: TELL breaker kind=ping, plus a loop event.
export type BreakerNotice = { kind: 'breaker'; since: Ms; until: Ms; passes: number }

export function newScheduler(): Scheduler {
  return { running: false, queued: null, lastStart: null, wakeAt: null, pingStarts: [], pingsIgnoredUntil: null }
}

export function pingsIgnored(s: Scheduler, now: Ms): boolean {
  return s.pingsIgnoredUntil !== null && now < s.pingsIgnoredUntil
}

// requestPass: a ping or a timer tick arrived, during a pass or not. Requests merge into one
// queued pass; a ping is dropped while the breaker is open.
export function requestPass(s: Scheduler, source: PassSource, now: Ms): Scheduler {
  if (source === 'ping' && pingsIgnored(s, now)) return s
  return { ...s, queued: s.queued === 'timer' || source === 'timer' ? 'timer' : 'ping' }
}

// nextPass: what the driver does now; call it after every request, pass end and wait. Passes
// never overlap and start PASS_GAP_MS apart: `wait` asks for one timer, whose callback calls
// waitOver and then nextPass again. Starting the ping-driven pass that makes more than
// STORM_PASSES in STORM_WINDOW_MS opens the breaker for STORM_QUIET_MS, with its one notice.
export function nextPass(s: Scheduler, now: Ms): { scheduler: Scheduler; next: NextPass; notice: BreakerNotice | null } {
  if (s.running || s.queued === null || (s.wakeAt !== null && now < s.wakeAt)) return { scheduler: s, next: { do: 'idle' }, notice: null }
  if (s.lastStart !== null && now < s.lastStart + PASS_GAP_MS) {
    const wakeAt = s.lastStart + PASS_GAP_MS
    return { scheduler: { ...s, wakeAt }, next: { do: 'wait', ms: wakeAt - now }, notice: null }
  }
  const source = s.queued
  let pingStarts = s.pingStarts.filter(t => now - t < STORM_WINDOW_MS)
  let pingsIgnoredUntil = pingsIgnored(s, now) ? s.pingsIgnoredUntil : null
  let notice: BreakerNotice | null = null
  if (source === 'ping') {
    pingStarts = [...pingStarts, now]
    if (pingStarts.length > STORM_PASSES) {
      pingsIgnoredUntil = now + STORM_QUIET_MS
      notice = { kind: 'breaker', since: now, until: pingsIgnoredUntil, passes: pingStarts.length }
      pingStarts = []
    }
  }
  return {
    scheduler: { running: true, queued: null, lastStart: now, wakeAt: null, pingStarts, pingsIgnoredUntil },
    next: { do: 'start', source },
    notice,
  }
}

// waitOver: the wait's timer fired (early or late, nextPass judges the gap again).
export function waitOver(s: Scheduler): Scheduler {
  return { ...s, wakeAt: null }
}

// passEnded: the pass is over; nextPass then starts the one queued meanwhile, if any.
export function passEnded(s: Scheduler): Scheduler {
  return { ...s, running: false }
}

// --- notices as tell wakes (v2 SPEC 13.9.2) -----------------------------------------------------------

export type Notice = RailNotice | BreakerNotice

// noticeTell: the tell wake a notice becomes, keyed by its spell so it goes out once:
// `TELL heartbeat-other device=<d>` under tell:heartbeat-other:<since>, `TELL breaker kind=ping`
// under tell:breaker:pings:<since> (plan's breaker keys name an action kind, never `pings`).
// old-watcher is a kind of its own (v2 SPEC 13.9.2); 13.11.2 says the owner is told.
export function noticeTell(n: Notice): Action {
  const tell = (wake: string, key: string, fields: Record<string, string>): Action => ({
    kind: 'tell',
    wake,
    key,
    class: 'owner',
    rule: 'O2',
    reason: `tell ${wake}`,
    issue: null,
    fields,
    context: [],
  })
  switch (n.kind) {
    case 'heartbeat-other':
      return tell('heartbeat-other', `tell:heartbeat-other:${n.since}`, { device: n.device })
    case 'old-watcher':
      return tell('old-watcher', `tell:old-watcher:${n.since}`, { pid: n.pid })
    case 'schema-behind':
      return tell('schema-behind', `tell:schema-behind:${n.since}`, { to: n.to, error: n.error })
    case 'breaker':
      return tell('breaker', `tell:breaker:pings:${n.since}`, { kind: 'ping' })
  }
}

files.hooks/trace.ts:
// Trace mode (#552): with config `trace` on, each pass writes one record to
// <loop dir>/trace-YYYY-MM-DD.jsonl beside its decision-log line, for troubleshooting and for
// measuring the loop: what asked for the pass, how long it and each of its phases took, every
// command it ran (the source it read, its exit, its bytes), each action's times, the wakes'
// latencies, and what each issue waits on and since when. The files stay within config
// traceMaxBytes: the oldest go first, and today's is cut short rather than pass it (traceRoom).
// register.ts holds the clock and the files; a Tracer only times the calls it is handed, and the
// rest here is pure.
import type { ActOutcome } from './act'
import type { ActIo, RunResult } from './exec'
import type { Io } from './observe'
import type { ActionKind, LedgerEntry, LedgerStatus, Ms, PlanResult, Skip, SourceName, Stage, State } from './types'

// A pass's phases in the order they run, each ending where the next begins: setup (the settings,
// the kill switch, the agent list), rails (act mode's checks and the act lock), observe, plan, act
// (the actions, the title, the notices and the store writes after them) and log (the decision log,
// a recorded state, the daily prune).
export const PHASES = ['setup', 'rails', 'observe', 'plan', 'act', 'log'] as const
export type Phase = (typeof PHASES)[number]

// What an observe command reads: a State source, or the main checkout.
export type TraceSource = SourceName | 'checkout'

// One command or engine call: the phase it ran in, the source it read (observe's reads), when it
// started (t, ms into the pass), how long it took, its exit and the bytes it printed; error when
// it threw or was refused.
export type Command = { phase: Phase; source?: TraceSource; cmd: string; t: number; ms: number; exit?: number | null; bytes?: number; error?: string }

export type Tracer = {
  // performance.now(), and its reading when the pass started
  now: () => number
  t0: number
  // the loop's clock at one reading of `now`: a clock time (an action's start) as a pass time
  anchor: { at: Ms; t: number }
  phase: Phase
  lapAt: number
  phases: Record<Phase, number>
  commands: Command[]
  // the pass's time in store writes, event writes and the act lock, whatever phase they ran in
  persistMs: number
  eventsMs: number
  lockMs: number
}

const CMD_MAX = 160
const ERROR_MAX = 200
const WAKES: readonly ActionKind[] = ['judge', 'task', 'tell']
const LIVE: readonly Stage[] = ['designing', 'implementing', 'in pipeline', 'parked', 'waiting', 'ready to merge']
const encoder = new TextEncoder()

// to a tenth of a millisecond: plan takes a few
const tenth = (ms: number) => Math.round(ms * 10) / 10
const iso = (ms: Ms) => new Date(ms).toISOString()

export function byteLength(text: string): number {
  return encoder.encode(text).length
}

// newTracer: a pass that started at t0 (a reading of now), with the loop's clock at `at` now.
export function newTracer(now: () => number, t0: number, at: Ms): Tracer {
  const t = now()
  return {
    now,
    t0,
    anchor: { at, t },
    phase: 'setup',
    lapAt: t0,
    phases: { setup: 0, rails: 0, observe: 0, plan: 0, act: 0, log: 0 },
    commands: [],
    persistMs: 0,
    eventsMs: 0,
    lockMs: 0,
  }
}

// begin: the phase running ends now and the next one starts.
export function begin(tr: Tracer | null, phase: Phase) {
  if (tr === null) return
  const t = tr.now()
  tr.phases[tr.phase] += t - tr.lapAt
  tr.lapAt = t
  tr.phase = phase
}

// carve: ms of the phase running belong to another (act mode plans inside its act step).
export function carve(tr: Tracer | null, phase: Phase, ms: number) {
  if (tr === null) return
  tr.phases[phase] += ms
  tr.lapAt += ms
}

// passTime: a time on the loop's clock as ms into the pass.
export function passTime(tr: Tracer, at: Ms): number {
  return tenth(at - tr.anchor.at + tr.anchor.t - tr.t0)
}

// spent: work, its time added to one of the pass's totals.
export async function spent<T>(tr: Tracer | null, total: 'persistMs' | 'eventsMs' | 'lockMs', work: () => Promise<T>): Promise<T> {
  if (tr === null) return work()
  const start = tr.now()
  try {
    return await work()
  } finally {
    tr[total] += tr.now() - start
  }
}

// timed: one call, recorded in the order calls start.
async function timed<T>(tr: Tracer, cmd: string, work: () => Promise<T>, read: (r: T) => Partial<Command> = () => ({}), source?: TraceSource): Promise<T> {
  const start = tr.now()
  const at = { cmd: cmd.slice(0, CMD_MAX), t: tenth(start - tr.t0), ms: 0 }
  const c: Command = source === undefined ? { phase: tr.phase, ...at } : { phase: tr.phase, source, ...at }
  tr.commands.push(c)
  try {
    const r = await work()
    Object.assign(c, read(r))
    return r
  } catch (err) {
    c.exit = null
    c.error = (err instanceof Error ? err.message : String(err)).slice(0, ERROR_MAX)
    throw err
  } finally {
    c.ms = tenth(tr.now() - start)
  }
}

// called: an engine call the driver makes itself (the pass's agent list), recorded.
export function called<T>(tr: Tracer | null, cmd: string, work: () => Promise<T>, read?: (r: T) => Partial<Command>): Promise<T> {
  return tr === null ? work() : timed(tr, cmd, work, read)
}

const ran = (r: RunResult): Partial<Command> => ({ exit: r.exitCode, bytes: byteLength(r.stdout) })

// sourceOf: the State source an observe command reads (observe.ts), from its program.
export function sourceOf(argv: readonly string[]): TraceSource | undefined {
  const [cmd = '', ...args] = argv
  const tool = cmd.slice(cmd.lastIndexOf('/') + 1)
  if (cmd === 'callum-flow-factory-state') return 'factory'
  if (cmd === 'dev-query') return 'facts'
  if (tool === 'pipeline-watch.sh') return 'runs'
  if (tool === 'queue-watch.sh' || (cmd === 'callum-flow-issue-read' && args.includes('--list'))) return 'queue'
  if (cmd === 'callum-flow-issue-read') return 'github'
  if (tool === 'usage-check.sh') return 'usage'
  // a pool slot's reflog or tree (git -C <slot>, #563) is the pool's
  if (cmd === 'treehouse' || (cmd === 'git' && args[0] === '-C')) return 'pool'
  if (cmd === 'git') return 'checkout'
  if (cmd === 'callum-flow-milestone') return 'milestone'
  return undefined
}

// tracedIo: observe's engine calls, each recorded with the source it reads.
export function tracedIo(tr: Tracer, io: Io): Io {
  return {
    ...io,
    run: (argv, init) => timed(tr, argv.join(' '), () => io.run(argv, init), ran, sourceOf(argv)),
    readFile: path => timed(tr, `fs.read ${path}`, () => io.readFile(path), text => (text === null ? {} : { bytes: byteLength(text) })),
    sessionLimits: () => timed(tr, 'session.usage', () => io.sessionLimits()),
  }
}

// tracedActIo: the act half's engine calls, each recorded; event writes also count in eventsMs.
export function tracedActIo(tr: Tracer, io: ActIo): ActIo {
  const refused = (r: { deny?: string; error?: string }): Partial<Command> => {
    const why = r.deny ?? r.error
    return why === undefined ? {} : { error: why.slice(0, ERROR_MAX) }
  }
  return {
    ...io,
    run: (argv, init) => {
      const call = () => timed(tr, argv.join(' '), () => io.run(argv, init), ran)
      return argv[0] === 'callum-flow-event' ? spent(tr, 'eventsMs', call) : call()
    },
    spawnAgent: input => timed(tr, `agent.spawn ${input.name ?? input.subagentType}`, () => io.spawnAgent(input), refused),
    stopAgent: agentId => timed(tr, `TaskStop ${agentId}`, () => io.stopAgent(agentId), refused),
    submit: text => timed(tr, `prompt.submit ${text.split('\n', 1)[0] ?? ''}`, () => io.submit(text)),
    rename: title => timed(tr, 'rename', () => io.rename(title)),
    usage: () => timed(tr, 'session.usage', () => io.usage()),
    readFile: path => timed(tr, `fs.read ${path}`, () => io.readFile(path), text => (text === null ? {} : { bytes: byteLength(text) })),
    writeFile: (path, text) => timed(tr, `fs.write ${path}`, () => io.writeFile(path, text), () => ({ bytes: byteLength(text) })),
  }
}

// lockTimed: one write of the act lock (rails.ts LOCK_CAS_SCRIPT), recorded as `act lock`, its
// time, the flock wait included, counted in lockMs.
export function lockTimed<T extends RunResult>(tr: Tracer | null, work: () => Promise<T>): Promise<T> {
  if (tr === null) return work()
  return spent(tr, 'lockMs', () => timed(tr, 'act lock', work, r => ({ exit: r.exitCode })))
}

// --- the record's parts -----------------------------------------------------------------------

// One source as the pass found it: read (`reads` commands, `ms` in all) or taken from the observe
// cache, how old State says its data is, and why it failed.
export type SourceRow = { ok: boolean; cached: boolean; reads: number; ms: number; ageMs: Ms | null; error?: string }

// sourceRows: each State source and the main checkout. A source that ran no command of its own
// this pass took its data from the observe cache (GitHub when no issue was due), unless it is one
// of `made`, built each pass from another source (a shadow's runs from the event log, its pool
// from the pool size).
export function sourceRows(state: State, commands: readonly Command[], made: readonly SourceName[] = []): Record<string, SourceRow> {
  const read = (name: TraceSource) => {
    const own = commands.filter(c => c.source === name)
    return { reads: own.length, ms: tenth(own.reduce((n, c) => n + c.ms, 0)) }
  }
  const out: Record<string, SourceRow> = {}
  for (const [name, s] of Object.entries(state.sources) as [SourceName, State['sources'][SourceName]][]) {
    const r = read(name)
    const row: SourceRow = { ok: s.ok, cached: r.reads === 0 && s.at !== null && !made.includes(name), ...r, ageMs: s.at === null ? null : state.now - s.at }
    if (s.error !== undefined) row.error = s.error
    out[name] = row
  }
  if (state.checkout !== null) {
    const failed = 'error' in state.checkout ? state.checkout.error : null
    out.checkout = { ok: failed === null, cached: false, ...read('checkout'), ageMs: failed === null ? 0 : null, ...(failed === null ? {} : { error: failed }) }
  }
  return out
}

// One executed action: when plan handed it over, when it started and ended (ms into the pass;
// null for one held before it started), and how long it ran. A spawn's ms is its time to start:
// it returns once the agent started.
export type ActionRow = { key: string; kind: ActionKind; status: ActOutcome['status']; queued: number | null; started: number | null; ended: number | null; ms: Ms }

export function actionRows(tr: Tracer, outcomes: readonly ActOutcome[], queuedAt: Ms | null): ActionRow[] {
  return outcomes.map(o => {
    const started = o.at === undefined ? null : passTime(tr, o.at)
    return {
      key: o.key,
      kind: o.kind,
      status: o.status,
      queued: queuedAt === null ? null : passTime(tr, queuedAt),
      started,
      ended: started === null ? null : tenth(started + o.ms),
      ms: o.ms,
    }
  })
}

// attemptOf: one attempt of a ledger entry (a retry keeps the key, not the start).
export function attemptOf(e: LedgerEntry): string {
  return `${e.key}@${e.startedAt}`
}

// One wake's latencies: queued (its submit), delivered (its turn started), ended (answered, or
// timed out or lost), the ms between them.
export type WakeRow = {
  key: string
  wake: string | null
  status: LedgerStatus
  queued: string
  delivered: string | null
  ended: string | null
  deliverMs: Ms | null
  answerMs: Ms | null
}

// wakeRows: every open wake, and each wake that ended at or after `since` and was not reported
// yet, with the attempts it reports ended (attemptOf), so the caller reports each once.
// delivered: when each attempt's turn first started (register.ts records it at turn.start).
export function wakeRows(
  ledger: readonly LedgerEntry[],
  delivered: ReadonlyMap<string, Ms>,
  reported: ReadonlySet<string>,
  since: Ms,
): { rows: WakeRow[]; reported: string[] } {
  const rows: WakeRow[] = []
  const ended: string[] = []
  for (const e of ledger) {
    if (!WAKES.includes(e.kind)) continue
    const end = e.status === 'running' ? null : (e.endedAt ?? e.startedAt)
    if (end !== null && (reported.has(attemptOf(e)) || end < since)) continue
    if (end !== null) ended.push(attemptOf(e))
    const at = delivered.get(attemptOf(e)) ?? null
    rows.push({
      key: e.key,
      wake: e.wake ?? null,
      status: e.status,
      queued: iso(e.startedAt),
      delivered: at === null ? null : iso(at),
      ended: end === null ? null : iso(end),
      deliverMs: at === null ? null : at - e.startedAt,
      answerMs: at === null || end === null ? null : end - at,
    })
  }
  return { rows, reported: ended }
}

// What one issue waits on (null: the whole pass, a source down), since when, and for how long.
export type WaitRow = { issue: number | null; stage: Stage | null; rule: string | null; on: string; since: string | null; forMs: Ms | null }

const waitKey = (s: Skip) => `${s.issue}:${s.rule}`

// waitSince: when each skip, by issue and rule, was first seen in a run of passes: one that keeps
// coming keeps its start, so a stall shows as a growing age (its words may change, as a
// countdown's do); one that stops is forgotten.
export function waitSince(prev: ReadonlyMap<string, Ms>, skipped: readonly Skip[], now: Ms): Map<string, Ms> {
  const next = new Map<string, Ms>()
  for (const s of skipped) if (!next.has(waitKey(s))) next.set(waitKey(s), prev.get(waitKey(s)) ?? now)
  return next
}

// waitingRows: each skip plan gave (the rule's reason, with how long it has been given), each
// running ledger entry an issue waits for, and each live issue of this device that nothing acts
// on and nothing names, waiting in its stage.
export function waitingRows(state: State, result: PlanResult, ledger: readonly LedgerEntry[], since: ReadonlyMap<string, Ms>): WaitRow[] {
  const stageOf = (n: number | null) => (n === null ? null : (state.issues.find(i => i.number === n)?.stage ?? null))
  const rows: WaitRow[] = []
  const seen = new Set<string>()
  for (const s of result.skipped) {
    if (seen.has(waitKey(s))) continue
    seen.add(waitKey(s))
    const at = since.get(waitKey(s)) ?? state.now
    rows.push({ issue: s.issue, stage: stageOf(s.issue), rule: s.rule, on: s.why, since: iso(at), forMs: state.now - at })
  }
  for (const e of ledger) {
    if (e.status !== 'running' || e.issue === null) continue
    rows.push({ issue: e.issue, stage: stageOf(e.issue), rule: e.rule, on: `${e.key} running`, since: iso(e.startedAt), forMs: state.now - e.startedAt })
  }
  for (const i of state.issues) {
    if (i.stage === null || !LIVE.includes(i.stage) || i.holder !== state.device) continue
    if (rows.some(r => r.issue === i.number) || result.actions.some(a => a.issue === i.number)) continue
    const at = i.stageSince
    rows.push({ issue: i.number, stage: i.stage, rule: null, on: 'no rule acts on it', since: at === null ? null : iso(at), forMs: at === null ? null : state.now - at })
  }
  return rows.sort((a, b) => (a.issue ?? 0) - (b.issue ?? 0))
}

export type TraceInput = {
  tr: Tracer
  // the decision-log line's fields the record repeats, so the two join
  line: { at: string; pass: number; loaded: string; mode: string; executed: boolean; trigger: string }
  state: State
  // the sources built each pass from another (sourceRows)
  made: readonly SourceName[]
  outcomes: readonly ActOutcome[]
  // when plan handed the actions over, on the loop's clock; null when the pass did not act
  queuedAt: Ms | null
  wakes: WakeRow[]
  waiting: WaitRow[]
}

// traceRecord: the pass's record, its log phase ending now: start and end on the loop's clock
// (`at` is the decision log's, when observe began), ms between them.
export function traceRecord(input: TraceInput): Record<string, unknown> {
  const { tr } = input
  begin(tr, 'log')
  const start = Math.round(tr.anchor.at - (tr.anchor.t - tr.t0))
  const ms = tenth(tr.lapAt - tr.t0)
  return {
    v: 1,
    ...input.line,
    start: iso(start),
    end: iso(Math.round(start + ms)),
    ms,
    phases: Object.fromEntries(PHASES.map(p => [p, tenth(tr.phases[p])])),
    persistMs: tenth(tr.persistMs),
    eventsMs: tenth(tr.eventsMs),
    lockMs: tenth(tr.lockMs),
    sources: sourceRows(input.state, tr.commands, input.made),
    commands: tr.commands,
    actions: actionRows(tr, input.outcomes, input.queuedAt),
    wakes: input.wakes,
    waiting: input.waiting,
  }
}

// --- the files and their cap --------------------------------------------------------------------

const TRACE_NAME = /^trace-\d{4}-\d{2}-\d{2}\.jsonl$/
// a record is written only while the line that cuts today's file short would still fit after it
export const CUT_ROOM = 256

export function traceName(day: string): string {
  return `trace-${day}.jsonl`
}

// cutLine: the last line of a trace file the cap cut short (under CUT_ROOM bytes).
export function cutLine(at: string, cap: number): string {
  return JSON.stringify({ v: 1, at, cut: cutText(cap) }) + '\n'
}

function cutText(cap: number): string {
  return `the trace cap (${cap} bytes) is reached: nothing more is traced today`
}

// isCutLine: the line is the cut line of this cap, so the file it ends stays closed today; a cut
// under another cap does not close it (v2 SPEC 13.12.1).
export function isCutLine(line: string, cap: number): boolean {
  try {
    const v: unknown = JSON.parse(line)
    return v !== null && typeof v === 'object' && (v as { cut?: unknown }).cut === cutText(cap)
  } catch {
    return false
  }
}

export type Room = { remove: string[]; write: 'record' | 'cut' | 'none' }

// traceRoom: what one more record of `bytes` takes under the cap, given the loop dir's files:
// the oldest trace files are deleted first (by the day in their names, never today's) until it
// fits; when today's file alone leaves no room, it is cut short with one line (cutLine), and
// once cut (`cut`) nothing more goes in it. The files never pass the cap.
export function traceRoom(files: readonly { name: string; size: number }[], day: string, bytes: number, cap: number, cut: boolean): Room {
  if (cut) return { remove: [], write: 'none' }
  const today = traceName(day)
  const traces = files.filter(f => TRACE_NAME.test(f.name)).sort((a, b) => a.name.localeCompare(b.name))
  let total = traces.reduce((n, f) => n + f.size, 0)
  const fits = (more: number) => total + more <= cap
  const remove: string[] = []
  for (const f of traces) {
    if (fits(bytes + CUT_ROOM)) break
    if (f.name === today) continue
    remove.push(f.name)
    total -= f.size
  }
  if (fits(bytes + CUT_ROOM)) return { remove, write: 'record' }
  return { remove, write: fits(CUT_ROOM) ? 'cut' : 'none' }
}

files.hooks/types.ts:
// The factory loop's data: what observe builds (State), what plan returns (Action), and
// what the ledger keeps. docs/factory-loop/v2/SPEC.md section 13 is the contract; the section numbers below
// are its. Types only, so the pure planner can import it. The v2 rule layer's vocabulary
// (docs/factory-loop/v2/SPEC.md) is v2/types.ts's; its action kinds, actions, outcomes and State
// fields join the unions here, so the dispatcher, the ledger and the store carry them.
import type { AgentStep, Model, ParkParts, SplitReasons, StateTimeouts, V2Action, V2ActionKind, V2Outcome, V2State } from './v2/types'

export type Ms = number

export type Tier = 'normal' | 'slow' | 'stop-new' | 'stop-all'

// Each action has one class; the tier decides which classes may run (v2 SPEC 13.5.2).
export type ActionClass = 'free' | 'owner' | 'drive' | 'develop' | 'start'

export type Stage =
  | 'queued'
  | 'designing'
  | 'implementing'
  | 'in pipeline'
  | 'parked'
  | 'waiting'
  | 'ready to merge'
  | 'merged'
  | 'closed without merge'

export type SourceName = 'factory' | 'facts' | 'runs' | 'queue' | 'github' | 'usage' | 'pool' | 'milestone'

// ok: the last read worked. at: when the data in State was read (null: never).
export type Source = { ok: boolean; at: Ms | null; error?: string }

// Each window's reading and when it resets: a reading taken before its window reset counts as
// zero once the reset has passed (the next read confirms it).
export type Usage = {
  fiveHour: number | null
  sevenDay: number | null
  fiveHourResetsAt: Ms | null
  sevenDayResetsAt: Ms | null
  unavailable: boolean
}

export type Brief = { url: string; at: Ms }

export type IssueView = {
  number: number
  stage: Stage | null
  stageSince: Ms | null
  holder: string | null
  run: string | null
  pr: number | null
  stuck: string | null
  open: boolean | null
  trusted: boolean | null
  labels: string[] | null
  blockedBy: number | null
  // the open issues waiting on this one, or null if unread
  blocking: number | null
  subIssues: number | null
  // the open issues of this repo this one blocks, from the read's `blocking` list; null if unread
  blockingList: number[] | null
  // the newest closed_at among its listed closed blockers; null if none or unread
  blockersClosedAt: Ms | null
  // the parent's number when the parent is in this repo; null if none or unread
  parent: number | null
  // the parent's other sub-issues in this repo (itself left out); null if unread
  siblings: { number: number; open: boolean }[] | null
  // the title marks it a tracker (config trackerTitle, e.g. 'Epic: ...'), or null if unread
  epic: boolean | null
  // a tracker's open sub-issues, nested ones included, ascending, from its timeline; read only
  // for trackers named in control.only (D-35). null: not read.
  subIssueList: number[] | null
  brief: Brief | null
  delegatedBrief: string | null
  // the factory source shows the holder's claim lapsed: its lease ended then, with no renewal (v2 H1)
  claimLapsedAt: Ms | null
  // the newest `reclaimed` event of the issue: a sweep or a release gave its claim back (v2 H1)
  reclaimedAt: Ms | null
  // the newest `ready` event of the issue, or null if none
  readyAt: Ms | null
}

export type RunState =
  | 'merge-ready'
  | 'head-mismatch'
  | 'conflict'
  | 'ci-stalled'
  | 'parked'
  | 'failed'
  | 'cancelled'
  | 'running'
  | 'pending'

export type RunView = {
  branch: string
  issue: number | null
  run: string
  state: RunState
  head: string | null
  step: string | null
  detail: string | null
  pr: number | null
  since: Ms | null
  reviewFixRounds: number
  verdicts: string[]
  superseded: boolean
}

// The main checkout, where every agent the loop starts begins and its own commands run (#544):
// the branch checked out (null when HEAD is detached), its commit, origin's default branch and
// the tracked paths with changes (untracked files are not the checkout moving). A read that
// failed is { error }.
export type Checkout = { branch: string | null; head: string | null; defaultBranch: string; dirty: string[] } | { error: string }

// A treehouse pool slot (#563): the branch checked out (null when detached), and the lease's
// id, start and branch: the branch it has checked out, else the newest issue branch its HEAD
// reflog shows checked out since the lease began (an implementer detaches its slot once the
// pipeline holds the branch). dirty: uncommitted changes, untracked files included, read only for
// a slot rule H3 might return (null: not read).
export type Slot = {
  path: string
  branch: string | null
  state: string
  dirty: boolean | null
  busy: boolean
  lease: string | null
  leasedAt: Ms | null
  leaseBranch: string | null
}
export type Pool = { free: number; total: number; slots: Slot[] }

export type AgentStatus = 'pending' | 'running' | 'waiting' | 'idle' | 'completed' | 'failed' | 'killed'
export type AgentView = { id: string; type: string; status: AgentStatus }

export type Bump = 'patch' | 'minor' | 'major'
// openIssues: the numbers of the open issue lines (not PRs), in the order listed
// oldestClosedAt: when the oldest closed issue of the milestone closed (ISO); absent: not read; null: none, the list was full, or the read failed
export type Milestone = { open: number; closed: number; openIssues: number[]; expected: Bump | null; oldestClosedAt?: string | null }
// ReleaseInfo: the last release tag (null: the repo has no release yet) and when the oldest merge
// into the default branch since that tag happened (null: unknown or none)
export type ReleaseInfo = { tag: string | null; oldest: Ms | null }

export type Control = {
  paused: number[]
  noNewWork: boolean
  skip: number[]
  priority: number[]
  only: number[]
  serial: boolean
  usageOverride: { untilPct: number; expiresAt: Ms } | null
  // an update is due (rule H4, D-15): set by the reconciler or `/factory update`
  updateDue: { reason: string; at: Ms } | null
  // a v2 resume carries its note for the issue's next step (v2 SPEC 11, P1)
  resumed: { subject: string; at: Ms; note?: string }[]
  dropped: { issue: number; at: Ms }[]
  notes: { issue: number | null; text: string; at: Ms }[]
}

export type AgentType = 'designer' | 'implementer' | 'adjudicator' | 'fixer'
export type AdjudicatorPurpose = 'gate' | 'weakening' | 'merge'
export type FixerPurpose = 'gate' | 'conflict' | 'regate' | 'weakening' | 'review' | 'guard' | 'handoff' | 'resume'
export type Rollout = 'merge' | 'run-it' | 'keep-open'

// An adjudicator's one ACTION line, parsed (the retired v1 adjudicator reply). `merge` and `hold` answer purpose
// merge only (rule M4, D-05).
export type AdjudicatorAction =
  | { type: 'approve'; reason: string | null }
  // ignore: the judged findings the fix leaves unselected, declined by name (respond --ignore,
  // which no-mistakes 1.90+ requires); null when none
  | { type: 'fix'; findings: string | null; instructions: string | null; addFinding: string | null; ignore: string | null }
  | { type: 'skip' }
  | { type: 'escalate'; why: string }
  | { type: 'fixer'; instructions: string }
  | { type: 'merge' }
  | { type: 'hold'; reason: string }

// The merge adjudicator's report lines (the retired v1 adjudicator reply): SUMMARY, BUMP and FLAGS. A flag marks what
// release sequencing must know: a base image or template change, a restart, a run-it rollout.
export type MergeFlag = 'image' | 'template' | 'restart' | 'run-it'
export type MergeReport = { summary: string; bump: Bump; bumpReason: string; flags: MergeFlag[] }

// What an executor recorded about a finished action (v2 SPEC 13.7). An agent reply the parser
// cannot read is recorded as a failed attempt, except the designer's, which goes to the
// model as `judge(report)` and is recorded as { unparsed: true }.
export type Outcome =
  // a CLI's exit code; on failure the first 2 000 characters of its stderr (v2 SPEC 13.10 item 1)
  // a done ci-rerun also carries the job and test names its failed jobs' log named, null when none were read (v2 SPEC 8.5)
  | { kind: 'cli'; exit: number; detail?: string; failedJobs?: string[] | null; failedTests?: string[] | null }
  // park: the question a not-ready split child parks on and the parent that was split (v2 SPEC 8.7); only on a claimed result
  | { kind: 'claim'; result: 'claimed' | 'lost'; park?: { question: string; parent: number; parts?: ParkParts | null } }
  | { kind: 'designer'; brief: string | null; created: number[]; pendingDecision: boolean }
  | { kind: 'designer'; unparsed: true }
  | { kind: 'adjudicator'; verdicts: string[]; action: AdjudicatorAction; report: MergeReport | null }
  | { kind: 'handoff'; notGated: boolean; run: string | null; head: string | null; newBranch: string | null }
  // callum-flow-rollout for a merge the loop did not make (a hand merge, rule M7, D-29)
  | { kind: 'rollout'; rollout: Rollout | null; closeIssue: number | null }
  | {
      kind: 'wake'
      decision: string
      reason: string | null
      instructions: string | null
      bump: Bump | null
      bumpReason: string | null
      fields: Record<string, string | number | boolean | number[] | null>
    }
  | V2Outcome

export type ActionKind =
  | 'heartbeat'
  | 'sweep'
  | 'claim'
  | 'close-issue'
  | 'delete-branch'
  | 'release-parent'
  | 'milestone-later'
  | 'restart-self'
  | 'rollout'
  | 'stop-agent'
  | 'judge'
  | 'task'
  | 'tell'
  | 'title'
  | V2ActionKind

export type LedgerStatus = 'running' | 'done' | 'failed' | 'timed-out' | 'lost'

export type LedgerEntry = {
  key: string
  kind: ActionKind
  class: ActionClass
  rule: string
  issue: number | null
  run: string | null
  pr: number | null
  head: string | null
  wake?: string
  status: LedgerStatus
  attempts: number
  startedAt: Ms
  endedAt: Ms | null
  agentId?: string
  outcome?: Outcome
  // a wake's id (v2 SPEC 13.8.1 `id=`), the turn it started, whether its reminder went out (for an
  // agent, its one repair message, #548), and the session that submitted it (a restart ends the
  // wakes of the session before, v2 SPEC 13.7.5)
  wakeId?: string
  turnId?: string
  reminded?: boolean
  session?: string
  // the executor's last few words, for the decision log
  summary?: string
  // the wake's loop_entry payload fields (Action.loopData), written by `callum-flow-event loop --data`
  loopData?: LoopData
  // a v2 agent step's kind, which the per-issue rate cap counts by (D-24; v2 appendix B)
  step?: AgentStep
  // the key's own attempt cap, when its action set one (a v2 slot op's, appendix B)
  maxAttempts?: number
}

export type State = {
  now: Ms
  repo: string
  device: string
  loadedAt: Ms
  sources: Record<SourceName, Source>
  usage: Usage
  issues: IssueView[]
  queue: number[]
  runs: RunView[]
  pool: Pool | null
  agents: AgentView[]
  milestone: Milestone | null
  // null until the first successful read, which happens only while the milestone qualifies
  release: ReleaseInfo | null
  ledger: LedgerEntry[]
  control: Control
  lastTitle: string | null
  // when the last rename went out; null until one has since the module loaded
  lastTitleAt: Ms | null
  githubBackoffUntil: Ms | null
  // null: not read (the replay harness, a state built outside a pass)
  checkout: Checkout | null
  // what v2 reads besides (v2 SPEC 2.4)
  v2?: V2State
}

export type Mode = 'off' | 'observe' | 'act'

export type Config = {
  mode: Mode
  // observe mode only: plan as this device (the live orchestrator's) to shadow its work
  shadowDevice: string | null
  readyLabel: string
  // S1 claims issues with this label after the owner's list, before the rest: order only, never a filter
  priorityLabel: string
  inDevLabel: string
  skipLabels: string[]
  // a title matching this pattern marks a tracker, like sub-issues do (MEM: trackers are never claimed)
  trackerTitle: string
  usageSlowPct: number
  usageStopNewPct: number
  usageStopAllPct: number
  passEveryMs: Ms
  // the repo expects a release at least this often; the release wake names it (#772)
  minimumReleaseCadenceMs: Ms
  // the merge queue holds its merges while a release bump PR is open: the branch prefix that marks one (null: no hold), and the window from the PR's opening (0: no hold)
  releaseBranchPrefix: string | null
  releaseHoldMs: Ms
  // after a release task answered `done` (the judge started a release), no release review is planned until a newer tag is seen or this long has passed since it ended (0: no suppression)
  releaseInProgressMs: Ms
  // flake bugs (v2 SPEC 8.5 F1): the window in days, the flakes of one test that file a bug, the open flake bugs ready or in flight that hold a new one back from `ready`, and the epic a bug is linked under (null: none)
  flakeWindowDays: number
  flakeBugMin: number
  flakeBugReadyCap: number
  flakeEpic: number | null
  // the title is renamed at most this often (O1 is a throttle)
  titleEveryMs: Ms
  // the factory report is built at most this often (#684)
  reportEveryMs: Ms
  queueEveryMs: Ms
  githubEveryMs: Ms
  usageEveryMs: Ms
  milestoneEveryMs: Ms
  // a usage reading older than this counts as unavailable
  usageStaleMs: Ms
  heartbeatEveryMs: Ms
  sweepEveryMs: Ms
  // the main checkout is brought up to date with origin at least this often (rule H5, #555)
  checkoutEveryMs: Ms
  slowGapMs: Ms
  maxStartsPerPass: number
  // null: no cap on this device's live issues
  maxInFlightIssues: number | null
  worktreeReserve: number
  reviewFixCap: number
  guardRecheckMs: Ms
  guardTtlMs: Ms
  respondSettleMs: Ms
  updateBehindRetryMs: Ms
  updateBehindRetries: number
  ciStallRecheckMs: Ms
  blindNoticeAfterMs: Ms
  // a queue starved this long (ready issues, all blocked, nothing in flight) tells the owner (S1)
  starvedNoticeAfterMs: Ms
  agentTimeoutMs: Record<AgentType, Ms>
  wakeTimeoutMs: Record<WakeKind, Ms>
  maxAttempts: Partial<Record<ActionKind | AgentType, number>>
  retryBackoffMs: Ms
  // per rolling hour; merges are never capped (D-24)
  rateCaps: { start: number; spawn: number; wake: number; perIssueKind: number }
  // act mode without DEV_ROLE=orchestrator, for a testbed (v2 SPEC 13.11.2)
  allowActOutsideOrchestrator: boolean
  // one timing record per pass in trace-YYYY-MM-DD.jsonl (#552); the workspace file's own
  // `trace`, which `/factory trace` writes, overrides the repo's
  trace: boolean
  // the trace files' total size: the oldest go first, and today's is cut short past it
  traceMaxBytes: number
  // how the prompts and the repair message ask agents to answer (v2 SPEC 13.4.2): through the checked
  // answer script (script, the default: a workaround until a timer-spawned agent reaches the
  // loop's tool hook, #560, #561), through their answer tools (tool, the intended design, #548),
  // or in text alone; text stays every channel's fallback. The workspace file's own
  // `answerChannel` overrides the repo's
  answerChannel: AnswerChannel
  // where the record rebuild reads (v2 SPEC 3.3): the old store (old), the new one (new), or both,
  // compared, with the records from the old (shadow, the default)
  eventsSource: EventsSource
  // --- v2 (v2 SPEC 2.3, appendix A) ---
  // the step timeouts and the waiting states' tell periods (v2 SPEC 4.4)
  stateTimeoutMs: StateTimeouts
  // a wait on GitHub: no check started this long after the head was first seen, or one running
  // this long, is unknown (v2 SPEC 4.4)
  ciStartMs: Ms
  ciRunMs: Ms
  // a PR's read stands this long, unless something the loop knows makes it due sooner (v2 SPEC 2.4)
  prEveryMs: Ms
  // the default branch's state is read this often, in act mode, to be logged as main_state (v2 SPEC 2.4, 9.5)
  mainEveryMs: Ms
  // triage calls per life (v2 SPEC 5.1); its agent's model (5.2)
  maxTriages: number
  // minutes a requested wind-down may take before the stop (0: wind-down off; v2 SPEC 10.11)
  windDownMinutes: number
  // the lives an issue gets: a release at the last one rejects it instead of putting it back in the
  // queue (v2 SPEC 6.4)
  maxLives: number
  triageModel: Model
  // the review step's implementation and its model (v2 SPEC 8.2, 8.3)
  reviewer: string
  reviewerModel: Model
  // the stop gate's commands in the slot, joined with &&, and their one budget (v2 SPEC 10.6)
  gateCommands: string[]
  gateTimeoutMs: Ms
  // how many stop gates run at once across the companion's process: a whole number of at least 1, or
  // 'auto' (cpus / GATE_CPUS, config.ts resolveGateConcurrency); the longest a finished writer waits
  // for its turn (v2 SPEC 10.6)
  gateConcurrency: 'auto' | number
  gateWaitTimeoutMs: Ms
}

export type AnswerChannel = 'script' | 'tool' | 'text'
export type EventsSource = 'old' | 'new' | 'shadow'

export type WakeKind = 'judge' | 'task' | 'tell'

// The optional loop_entry fields a tell may carry (docs/factory-events/schemas/loop_entry.v1.json).
export type LoopData = Record<string, string | number | null>

// What every action carries. maxAttempts: the key's own cap, for a kind whose ops differ (v2's
// slot); otherwise config.maxAttempts holds the kind's.
export type ActionBase = { key: string; class: ActionClass; rule: string; reason: string; issue: number | null; maxAttempts?: number }
type Base = ActionBase

// What a wake asks: the line's first word is the action kind (judge, task, tell), the
// second this wake name, then key=value fields with no spaces. Context lines follow it in
// the visible prompt: a mod cannot attach hidden context to its own prompt (v2 SPEC 13.8.1).
export type Action =
  | (Base & { kind: 'heartbeat' | 'sweep' | 'milestone-later' })
  // logClosed: a done close also logs the `closed` event (reason completed) once the issue is closed
  | (Base & { kind: 'close-issue'; logClosed?: boolean })
  // a done close's branch on origin, deleted only while it still reads sha (a leased delete)
  | (Base & { kind: 'delete-branch'; branch: string; sha: string })
  // park: a split's not-ready child, claimed at once to park on its open decision (v2 SPEC 8.7)
  | (Base & { kind: 'claim'; park?: { question: string; parent: number; parts?: ParkParts | null } })
  // reasons and childWhys: the split's reasons and each child's why (childWhys aligned with created);
  // null when the life's design answer can no longer be read
  | (Base & { kind: 'release-parent'; created: number[]; reasons?: SplitReasons | null; childWhys?: string[] | null })
  // rule H4: why the update is due, and when it was asked for (the key's subject)
  | (Base & { kind: 'restart-self'; why: string; at: Ms; windDownAt?: Ms | null })
  // rule M7 for a hand merge: read the merged issue's rollout
  | (Base & { kind: 'rollout'; pr: number | null })
  | (Base & { kind: 'stop-agent'; agentId: string; entry: string })
  // loopData: payload fields the wake's loop_entry event carries beside its note (a flake bug tell's decision, v2 SPEC 8.5 F1)
  | (Base & { kind: WakeKind; wake: string; fields: Record<string, string>; context: string[]; loopData?: LoopData })
  | (Base & { kind: 'title'; text: string })
  | V2Action

export type Skip = { rule: string; issue: number | null; why: string }

export type PlanResult = {
  tier: Tier
  overridden: boolean
  actions: Action[]
  skipped: Skip[]
  title: string
  owner: number
  // each rate cap tripped this pass: a bucket (start, spawn, wake) or a per-issue key
  // '<kind>:<issue>' (v2 SPEC 13.11.4)
  capped: string[]
  // a claim was held back by maxInFlightIssues this pass (v2 SPEC 13.4.2)
  atCap: boolean
  // S1: the pass was starved (a ready queue, all of it unclaimable, nothing in flight); null: unknown (a source failed)
  starved?: boolean | null
}

files.hooks/within.ts:
import type { EngineInterface } from 'claude-code'

import type { Ms } from './types'

// within: the work, or a rejection once ms pass on $.clock.
export function within<T>($: EngineInterface, ms: Ms, work: Promise<T>, what: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const t = $.clock.after(ms, () => reject(new Error(`${what}: no answer within ${ms / 1000} s`)))
    work.then(
      v => {
        t.cancel()
        resolve(v)
      },
      err => {
        t.cancel()
        reject(err)
      },
    )
  })
}

