// R1, every pass (docs/factory-loop/v2/SPEC.md 6.2), before the record's rules: every issue that
// shows as active must have a live step.
//
// 1. Records are never released: the table keeps them live (every running step and waiting state
//    has a timeout, 4.4), and a stuck one goes down the unknown path to a park with a question.
// 2. A live claim with no record is a ghost: the `factory` source shows the issue live with this
//    device as the holder, it has no record and no claim action is in flight. R1 releases it at
//    once (release.ts): its agents stopped and its labels set by the release's outcome, then, once
//    those have ended and W2 has freed any loop slot leased for it, its event, last. The outcome
//    (6.4): back in the queue, `ready` re-added (`reclaimed`), unless the owner dropped the issue
//    since its claim (it leaves, `abandoned`), and unless this was its maxLives-th life (lives.ts):
//    then it is rejected, factory:rejected on, with one comment and one owner tell listing why
//    each life ended before its `abandoned`. A requeue waits for a read that shows the issue open
//    (a closed one is the sweep's, H2). In observe mode the same plan is logged, not executed. A release is keyed by the claim it ends (claimOf), and keeps the outcome it
//    began with. Once its event is done the issue is no ghost of that claim, whatever the factory
//    still shows, so S1 may claim it again.
// 3. Only this device's claims: another device's claims and labels are never looked at
//    (totality/T-02).
// 4. The main-checkout tripwire (10.7): a change to the main checkout since the checkout the
//    tripwire last settled on (new tracked changes, or a moved HEAD) tells the owner once, with the
//    paths and the steps that ran in that window. It is level-triggered: the change stays pending,
//    and its tell planned on every pass R1 runs, until the tell is done (checkoutBaseOf), so a pass
//    that drops it (one wake at a time, a rate cap, a store-blind pass) loses nothing. No step's
//    outcome changes, and the loop never cleans the checkout.
//
// R1 has no mode, no approval and no hold on claims (section 15, "Reconcile has no mode"). The
// one-shot migration for what v1 left behind is bin/factory-reconcile (6.3). Pure: the time is
// state.now.
import { gate, listedLive, skip, wake, want } from '../foundation'
import type { Gate } from '../foundation'
import type { Action, Checkout, IssueView, LedgerEntry, Ms, Stage } from '../types'
import { claimKey, lifeAt, lifeOf, short } from './keys'
import { claimedAt, livesBefore } from './lives'
import type { Lives } from './lives'
import { LIVE_STAGES, RELEASE_OPS, releaseClaimOf, releaseEffects, releaseEventAction, releaseKey, releaseOutcomeOf } from './release'
import type { ReleaseAgent, ReleaseOutcome } from './release'
import { REJECTED_LABEL } from './types'
import type { IssueRecord, Lease, V2Ctx } from './types'

const MIN = 60_000

// The agent kinds whose entries are steps an agent runs, for the tripwire's window.
const AGENT_KINDS: readonly string[] = ['agent-step']

// What the tripwire names at most, so the notice stays short.
const LIST_MAX = 10

// A ghost (6.2, 2): a live claim of this device with no record and no claim in flight.
export type Ghost = {
  issue: number
  // the claim the release ends, as its keys carry it (claimOf); null when no time is known
  claim: string | null
  stage: Stage
  // when the factory shows it entered its stage
  since: Ms | null
  // open on GitHub; null when not read (a closed one is never a ghost: the sweep ends its claim)
  open: boolean | null
  // the owner dropped it (`/factory drop N`) since its claim
  dropped: boolean
  // its lives before this claim, since the count last started (lives.ts)
  lives: Lives
  pr: number | null
  // the loop's agents still at work on it
  agents: ReleaseAgent[]
  // the loop slots leased for it, which W2 frees (10.1)
  slots: Lease[]
}

// reconcile (R1): the tripwire, then each ghost's release.
export function reconcile(ctx: V2Ctx): void {
  tripwire(ctx)
  for (const ghost of ghostsOf(ctx)) release(ctx, ghost)
}

// --- ghosts (6.2) ---------------------------------------------------------------------------------

// ghostsOf: this device's live claims with no record, no claim in flight and no done release, by
// issue number. S1 leaves these to R1, whose release ends their claim before any new one. A claim
// whose release is done is not one: the factory may still show it live (a no-mistakes run's stage
// outlives the release until the factory tools end it, 6.4), and S1 may claim it again, whose
// claim starts the new life.
export function ghostsOf(ctx: V2Ctx): Ghost[] {
  const { state } = ctx
  const out: Ghost[] = []
  for (const issue of [...state.issues].sort((a, b) => a.number - b.number)) {
    if (!liveClaim(issue, state.device)) continue
    if (heldByRecord(ctx.v2.records, issue)) continue
    if (claimInFlight(ctx, issue.number)) continue
    const claim = claimOf(state.ledger, issue)
    if (claim !== null && ctx.byKey.get(releaseKey(issue.number, claim, RELEASE_OPS.event))?.status === 'done') continue
    const claimAt = claim === null ? null : lifeAt(claim)
    out.push({
      issue: issue.number,
      claim,
      stage: issue.stage as Stage,
      since: issue.stageSince,
      open: issue.open,
      dropped: claimAt !== null && state.control.dropped.some(d => d.issue === issue.number && d.at >= claimAt),
      lives: claim === null ? { count: 0, ended: [], afterReject: false } : livesBefore(ctx.v2.records, state.ledger, issue.number, claim),
      pr: issue.pr,
      agents: agentsOn(ctx, issue.number),
      slots: ctx.v2.leases.filter(l => l.issue === issue.number),
    })
  }
  return out
}

// liveClaim: the factory shows the issue live with this device as the holder, and it is not
// known closed on GitHub (a closed issue's claim is ended by the sweep's `closed`, H2).
function liveClaim(issue: IssueView, device: string): boolean {
  return issue.holder === device && issue.stage !== null && LIVE_STAGES.includes(issue.stage) && issue.open !== false
}

// heldByRecord: a record holds the issue's claim: one that is not closed (rule 1), or a closed one
// at least as new as what the factory shows, whose closing events have not reached the factory yet
// (its own entry actions end its claim, 4.5). A factory view newer than every record's close is a
// claim no record holds.
function heldByRecord(records: readonly IssueRecord[], issue: IssueView): boolean {
  const mine = records.filter(r => r.issue === issue.number)
  if (mine.some(r => r.state !== 'closed')) return true
  if (mine.length === 0) return false
  return issue.stageSince === null || mine.some(r => r.since >= (issue.stageSince ?? 0))
}

// claimInFlight: a claim of the issue runs, or a v2 claim is done and its record is still to be
// made (row S0 makes one from every done claim, 3.3).
function claimInFlight(ctx: V2Ctx, n: number): boolean {
  const lives = ctx.v2.records.filter(r => r.issue === n).map(r => claimKey(n, r.life))
  return ctx.state.ledger.some(e => {
    if (e.kind !== 'claim' || e.issue !== n) return false
    if (e.status === 'running') return true
    if (e.status !== 'done' || !e.key.startsWith(claimKey(n, ''))) return false
    if (e.outcome?.kind === 'claim' && e.outcome.result === 'lost') return false
    return !lives.includes(e.key)
  })
}

// claimOf: the claim a ghost's release is dated by, as its keys carry it (keys.ts lifeOf), so a
// later claim never reuses an earlier release's keys and one claim's release never gets new ones:
// - the newest done claim entry of the issue (S1's, or one derived from its `claimed` event when
//   the ledger was rebuilt), a claim that was not lost;
// - else the claim the newest release begun for the issue is keyed by, so a release once begun
//   keeps its keys;
// - else, to begin one, when the factory shows it entered its stage. A run's stage moves that
//   time, which is why it never dates a release already begun.
// null when none is known.
export function claimOf(ledger: readonly LedgerEntry[], issue: IssueView): string | null {
  let at: Ms | null = null
  let begun: { claim: string; at: Ms } | null = null
  for (const e of ledger) {
    if (e.issue !== issue.number) continue
    if (e.kind === 'claim' && e.status === 'done' && !(e.outcome?.kind === 'claim' && e.outcome.result === 'lost')) {
      if (at === null || e.startedAt > at) at = e.startedAt
      continue
    }
    const claim = e.rule === 'R1' ? releaseClaimOf(issue.number, e.key) : null
    if (claim !== null && (begun === null || e.startedAt > begun.at)) begun = { claim, at: e.startedAt }
  }
  if (at !== null) return lifeOf(at)
  if (begun !== null) return begun.claim
  return issue.stageSince === null ? null : lifeOf(issue.stageSince)
}

// agentsOn: the loop's agents still at work on the issue: an entry of it that runs, or whose agent
// the session still lists at work, once per agent.
function agentsOn(ctx: V2Ctx, n: number): ReleaseAgent[] {
  const seen = new Map<string, string>()
  const entries = ctx.state.ledger.filter(e => e.issue === n && e.agentId !== undefined).sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0))
  for (const e of entries) {
    const id = e.agentId as string
    if (!seen.has(id) && (e.status === 'running' || listedLive(ctx.state.agents, id))) seen.set(id, e.key)
  }
  return [...seen].map(([agentId, entry]) => ({ agentId, entry }))
}

// --- the release (6.4) ----------------------------------------------------------------------------

// outcomeOf: how the ghost's release ends: the outcome it began with, else leave when the owner
// dropped it since its claim, reject at its maxLives-th life, and requeue once a read shows it
// open; null while that read is missing.
function outcomeOf(ctx: V2Ctx, g: Ghost, claim: string): ReleaseOutcome | null {
  const begun = releaseOutcomeOf(key => ctx.byKey.has(key), g.issue, claim)
  if (begun !== null) return begun
  if (g.dropped) return 'leave'
  if (g.lives.count + 1 >= ctx.config.maxLives) return 'reject'
  return g.open === true ? 'requeue' : null
}

// What each effect, not yet done, leaves the event waiting for.
const WAIT: Readonly<Record<string, string>> = {
  label: 'its labels set',
  comment: 'its comment posted',
}

// release: a ghost's effects, then its event once they have ended. A done event plans nothing
// more, whatever the factory still shows (property 17): ghostsOf leaves its claim out.
function release(ctx: V2Ctx, g: Ghost): void {
  const age = g.since === null ? '' : ` for ${Math.max(0, Math.round((ctx.state.now - g.since) / MIN))} min`
  if (g.claim === null) {
    skip(ctx, 'R1', g.issue, `ghost #${g.issue} in ${g.stage}: no claim time is known, so it is not released`)
    return
  }
  const claim = g.claim
  const why = `ghost #${g.issue}: a live claim of this device in ${g.stage}${age} with no record`
  const outcome = outcomeOf(ctx, g, claim)
  const lives = g.lives.count + 1
  const ended = [...g.lives.ended, `life ${lives}, claimed ${claimedAt(claim)}: released: a live claim of this device in ${g.stage} with no record`]
  const max = ctx.config.maxLives
  const waits: string[] = []
  // with no outcome yet, the stops still go: they are the same for every outcome
  const effects = releaseEffects({ issue: g.issue, claim, outcome: outcome ?? 'leave', lives }, g.agents, why, ctx.config.readyLabel, ended, max)
  for (const action of outcome === null ? effects.filter(a => a.kind === 'stop-agent') : effects) {
    const at = effect(ctx, action)
    if (action.kind === 'stop-agent') {
      // best effort, as an entry action's stop is (4.5): a stop that failed has ended too
      if (at !== 'done' && at !== 'exhausted') waits.push(`its agent ${action.agentId} stopped`)
    } else if (at === 'exhausted') {
      stalled(ctx, g.issue, action)
      return
    } else if (at !== 'done') {
      waits.push(WAIT[action.kind] ?? action.kind)
    }
  }
  if (outcome === null) waits.push(`a read of #${g.issue} that shows it open (it goes back to the queue)`)
  // a rejection's owner tell, planned until it is told (or its attempts are used up): the event
  // waits for it, since a done event ends the ghost and with it every plan of this release
  if (outcome === 'reject') {
    const tell = wake('tell', 'rejected', `tell:rejected:${releaseKey(g.issue, claim, 'reject')}`, 'R1', g.issue, { issue: g.issue, lives, max }, [
      ...ended.map(l => `- ${l}`),
      `bring it back: remove ${REJECTED_LABEL.name} and add ${ctx.config.readyLabel}`,
    ])
    const told = gate(ctx, tell.key, tell.kind)
    if (told !== 'done' && told !== 'exhausted') {
      want(ctx, tell)
      waits.push('its owner told')
    }
  }
  if (!ctx.v2.sources.leases.ok) waits.push('a read of the pool (its loop slots are not known)')
  for (const slot of g.slots) waits.push(`slot ${slot.path} freed (W2)`)
  if (waits.length > 0) {
    skip(ctx, 'R1', g.issue, `the release of ghost #${g.issue} waits for ${waits.join(', ')}`)
    return
  }
  const checked = `this device's live claim has no record and no claim in flight${g.agents.length > 0 ? `; ${g.agents.length} agent(s) stopped` : ''}`
  const event = releaseEventAction({ issue: g.issue, claim, outcome: outcome ?? 'leave', lives, stage: g.stage, checked, branch: null, pr: g.pr }, why)
  if (effect(ctx, event) === 'exhausted') stalled(ctx, g.issue, event)
}

// effect: an action of the release, planned unless its key is blocked; an exhausted key is the
// caller's to report as stalled.
function effect(ctx: V2Ctx, action: Action): Gate {
  const g = gate(ctx, action.key, action.kind, action.maxAttempts)
  return g === 'exhausted' ? g : want(ctx, action)
}

// stalled: a release effect used up its attempts (4.5): the release holds there, its skip line
// says why, and the owner hears once; `/factory retry N` clears it.
function stalled(ctx: V2Ctx, issue: number, action: Action): void {
  const error = ctx.byKey.get(action.key)?.summary ?? 'used up its attempts'
  skip(ctx, 'R1', issue, `stalled: ${action.key}: ${error}`)
  want(ctx, wake('tell', 'stalled', `tell:stalled:${action.key}`, 'R1', issue, { issue, key: action.key, kind: action.kind }))
}

// --- the main-checkout tripwire (10.7) ------------------------------------------------------------

// A main-checkout read that did not fail.
export type CheckoutRead = Exclude<Checkout, { error: string }>

// The checkout the tripwire last settled on (V2State.checkoutBase): the newest read with no change
// pending against the one before, or whose change the owner has been told of; at: when it was read.
export type CheckoutBase = { checkout: CheckoutRead; at: Ms }

// A change to the main checkout between two reads: where HEAD is now, whether it moved (or changed
// branch), and the tracked paths changed now that were not before.
export type CheckoutChange = { head: string | null; branch: string | null; moved: { from: string | null; to: string | null } | null; paths: string[] }

// checkoutChange: the change from one read to another; null when there is none, or when either
// read is missing or failed.
export function checkoutChange(before: Checkout | null, now: Checkout | null): CheckoutChange | null {
  if (before === null || now === null || 'error' in before || 'error' in now) return null
  const moved = before.head !== now.head || before.branch !== now.branch
  const paths = now.dirty.filter(p => !before.dirty.includes(p)).sort()
  if (!moved && paths.length === 0) return null
  return { head: now.head, branch: now.branch, moved: moved ? { from: before.head, to: now.head } : null, paths }
}

// tripwireKey: the notice's key, by what the checkout now is (its HEAD, branch and changed paths),
// so one change is told once and a different one again.
export function tripwireKey(now: CheckoutRead): string {
  const text = [now.head ?? 'none', now.branch ?? '(detached)', ...[...now.dirty].sort()].join('\n')
  return `tell:checkout:${short(now.head ?? 'none')}:${fnv(text)}`
}

// checkoutBaseOf: the base the tripwire compares this pass's read with, from the last one, the
// read and the ledger (observe keeps it between passes, v2/observe.ts). Pure. It moves only when
// nothing is left untold:
// - a failed or missing read keeps it;
// - the first read after a load has none to compare with: a read whose notice is done becomes the
//   base, else a clean checkout at its HEAD, so changes left untold before a restart are told
//   after it (a HEAD that moved while the loop was down is not seen);
// - a read with no change against the base, or whose notice is done, becomes the base;
// - any other read leaves the change pending: the base stays, and R1 plans its notice again.
export function checkoutBaseOf(base: CheckoutBase | null, now: Checkout | null, ledger: readonly LedgerEntry[], at: Ms): CheckoutBase | null {
  if (now === null || 'error' in now) return base
  const told = ledger.some(e => e.key === tripwireKey(now) && e.status === 'done')
  if (told) return { checkout: now, at }
  if (base === null) return { checkout: { ...now, dirty: [] }, at }
  if (checkoutChange(base.checkout, now) === null) return { checkout: now, at }
  return base
}

// tripwire: tell(checkout) for a change against the base until it is told, with its paths and the
// agent steps that ran in that window: running now, or ended since the base was read (and at least
// within two pass intervals, the last pass with slack for a late one).
function tripwire(ctx: V2Ctx): void {
  const now = ctx.state.checkout
  const base = ctx.v2.checkoutBase
  if (base === null || now === null || 'error' in now) return
  const change = checkoutChange(base.checkout, now)
  const key = tripwireKey(now)
  if (change === null || ctx.byKey.get(key)?.status === 'done') return
  const since = Math.min(base.at, ctx.state.now - 2 * ctx.config.passEveryMs)
  const steps = ctx.state.ledger
    .filter(e => AGENT_KINDS.includes(e.kind) && (e.status === 'running' || (e.endedAt !== null && e.endedAt >= since)))
    .sort((a, b) => a.startedAt - b.startedAt)
    .map(e => `${e.key} (${e.status}${e.issue === null ? '' : `, #${e.issue}`})`)
  const context = [
    ...(change.moved === null ? [] : [`HEAD moved: ${short(change.moved.from ?? 'none')} -> ${short(change.moved.to ?? 'none')} on ${change.branch ?? 'a detached HEAD'}`]),
    ...listed('changed', change.paths),
    ...listed('steps in that window', steps),
  ]
  const fields = { branch: change.branch ?? 'detached', head: short(change.head ?? 'none'), moved: change.moved === null ? 'no' : 'yes', paths: change.paths.length, steps: steps.length }
  want(ctx, wake('tell', 'checkout', key, 'R1', null, fields, context))
}

// listed: a heading line and up to LIST_MAX items, then how many more.
function listed(heading: string, items: readonly string[]): string[] {
  if (items.length === 0) return []
  const more = items.length > LIST_MAX ? [`and ${items.length - LIST_MAX} more`] : []
  return [`${heading}:`, ...items.slice(0, LIST_MAX).map(i => `- ${i}`), ...more]
}

// fnv: FNV-1a of a text, as 8 hex digits (state.ts digestOf's hash).
function fnv(text: string): string {
  let hash = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash.toString(16).padStart(8, '0')
}

files.hooks/v2/sources-interventions.ts:
// The facts the interventions of docs/factory-loop/v2/SPEC.md 7.2 come from, beside the ledger and
// the records: the companion's log (<loop dir>/companion.jsonl: one line per refusal and per stop
// gate run, of which only a gate that could not run is an intervention, 10.4, 10.6), and the
// owner's files: control.json, the workspace config.json and the repo-local settings file.
// rules-interventions.ts turns each fact into one
// `intervention` event; the pushes no loop step produced are read there, from the records and the
// PRs.
//
// A hand edit is a difference between an owner's file and the last version the loop read or wrote,
// which the store keeps beside the records (files:<repo>, store.ts): an acting pass under planner
// v2 keeps what it read with the edit it found, to log (keepFiles); an owner op and the clearing
// of a done update keep what they wrote (store.ts noteWritten), and an op that finds its file
// already changed keeps that edit to log. The loop never writes the OFF file, so the kill switch is
// an edit of its own, kept when a pass finds it (store.ts noteKillSwitch). Nothing here is held in
// the module: what the loop last read or wrote survives a reload, and edits made while the loop was
// down are found on its next acting read.
import type { Ms, Source } from '../types'
import { interventionKey } from './keys'
import type { SourceCtx } from './observe'
import { GATE_RUN_CAUSES } from './rules-gates'
import type { GateRunCause } from './rules-gates'
import { FACT_WINDOW_MS, digest, editFacts, editsOf } from './rules-interventions'

// the companion's lines older than this are left alone (rules-interventions.ts FACT_WINDOW_MS)
export const COMPANION_WINDOW_MS = FACT_WINDOW_MS
// the companion's log is read whole; past this, only its newest lines
const COMPANION_MAX_LINES = 2_000

// The companion's causes that are interventions (7.2): a refused file write, push, command, or
// call in the background (10.4), a stop gate that could not run (10.6), and a call refused because
// it would have waited on a prompt nobody answers (10.10, `prompt-denied`), and a stop gate the
// loop's restart cut, which the recovery re-runs (`gate-rerun`) or gives up (`gate-cut`, 10.6). Its
// other lines (`gate-start`, every gate run, `gate-pass` and `gate-fail`) are its record for an
// audit and are skipped here.
export const COMPANION_CAUSES = ['guard:write', 'guard:push', 'guard:command', 'gate-unknown', 'prompt-denied', 'gate-rerun', 'gate-cut'] as const

// One line of the companion's log (10.4, 10.6).
export type CompanionLine = { at: number; issue: number | null; life: string | null; seq: number | null; cause: string; reason: string }

// One version of an owner's file: its text (a missing file reads as empty) and that text's digest.
export type FileSeen = { digest: string; text: string }

// A hand edit kept to log: of control.json (and the kill switch) or of the settings, when it was
// found, the issues whose control entries changed (none: fleet-level) and what changed.
export type FileEdit = { what: 'control' | 'config'; at: Ms; issues: number[]; detail: string }

// files:<repo>: the last version of each file the loop read or wrote (null: none yet), the edits
// found outside an acting read, still to log, and whether the kill switch is already kept as one.
// v 2: settings is the repo-local file as written (v 1 kept it resolved, and reads as none).
export type FilesSeen = { v: 2; control: FileSeen | null; workspace: FileSeen | null; settings: FileSeen | null; edits: FileEdit[]; off: boolean }

// One gate line of the companion's log, its fields as written and checked for their type only
// (null: absent or not of the type); rules-gates.ts checks them against the `gate_run` schema.
// head: undefined when it is neither a string nor null; concurrency likewise (null is no limit).
// startedAt and queuedBehind are the companion's own (a companion from before them writes none).
export type GateLine = {
  at: number
  issue: number
  life: string
  seq: number
  cause: GateRunCause | 'gate-wait'
  head: string | null | undefined
  ms: number | null
  waitMs: number | null
  concurrency: number | null | undefined
  startedAt: string | null
  // startedAt as a time (null: absent, or not a time), and the start a line without startedAt implies:
  // its time less its run and its wait, as an ISO string and a time (null: the line holds no such
  // time). Read here because the planner reads no clock, nor parses a date (rules-gates.ts).
  startedMs: number | null
  derived: { iso: string; ms: number } | null
  queuedBehind: number | null
  // the slot's tree was clean and its head did not move during the run (null: not known, or absent);
  // hasClean: the line carries the field at all (a companion before it does not)
  clean: boolean | null
  hasClean: boolean
  // the names of the tests a failed run reported (null: none, or absent)
  failedTests: string[] | null
  // the run is the companion's re-run of a gate the loop's restart cut (false: absent), with no agent
  // left to refuse
  rerun: boolean
}

export type InterventionFacts = {
  companion: CompanionLine[]
  // the gate lines of the same window, for `gate_run` (rules-gates.ts); absent: none
  gates?: GateLine[]
  // the digests of this pass's control.json and settings, for the decision log
  controlDigest: string | null
  configDigest: string | null
  // this pass's reads: control.json, the workspace config.json, and what the repo-local settings
  // file says; absent or null when not read
  control?: FileSeen | null
  workspace?: FileSeen | null
  settings?: FileSeen | null
  // files:<repo> as the pass found it; absent or null when the loop keeps none yet
  seen?: FilesSeen | null
}

export const EMPTY_INTERVENTIONS: InterventionFacts = { companion: [], gates: [], controlDigest: null, configDigest: null }

export const EMPTY_FILES: FilesSeen = { v: 2, control: null, workspace: null, settings: null, edits: [], off: false }

export function seenOf(text: string): FileSeen {
  return { digest: digest(text), text }
}

// --- files:<repo> -------------------------------------------------------------------------------------

export const filesKey = (repo: string) => `files:${repo}`

const isSeen = (v: unknown): v is FileSeen | null =>
  v === null || (v !== null && typeof v === 'object' && typeof (v as FileSeen).digest === 'string' && typeof (v as FileSeen).text === 'string')

function editOfStore(v: unknown): FileEdit | null {
  const o = v !== null && typeof v === 'object' ? (v as Record<string, unknown>) : null
  if (o === null || (o.what !== 'control' && o.what !== 'config') || typeof o.at !== 'number' || typeof o.detail !== 'string') return null
  if (!Array.isArray(o.issues) || !o.issues.every(n => typeof n === 'number' && Number.isInteger(n) && n > 0)) return null
  return { what: o.what, at: o.at, issues: [...(o.issues as number[])], detail: o.detail }
}

// filesFromStore: files:<repo> as the store holds it; null when it holds none, or nothing that reads.
export function filesFromStore(raw: unknown): FilesSeen | null {
  const o = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : null
  if (o === null || o.v !== 2 || !isSeen(o.control) || !isSeen(o.workspace) || !isSeen(o.settings) || !Array.isArray(o.edits)) return null
  const edits = o.edits.map(editOfStore).filter((e): e is FileEdit => e !== null)
  return { v: 2, control: o.control, workspace: o.workspace, settings: o.settings, edits, off: o.off === true }
}

const sameSeen = (a: FileSeen | null, b: FileSeen | null) => (a === null ? b === null : b !== null && a.digest === b.digest)

// keepFiles: what an acting pass under planner v2 keeps once it has read the files (store.ts
// keepV2), at `at`. kept: the record as it is now (an op may have written it since the pass read
// it); facts: the pass's reads, with the record as the pass found it; logged: whether an
// intervention key is done. Each version read is kept at once, with what changed since the version
// before as an edit found at `at`, which the next pass logs, so a change is logged once whatever
// version it goes back to; a part an op wrote since the read keeps the op's version (the op keeps
// what it found); a part not read keeps the last. An edit kept goes once logged, and the kill
// switch's flag clears: an acting pass runs only without it. null: nothing changes.
export function keepFiles(kept: FilesSeen | null, facts: InterventionFacts, at: Ms, logged: (key: string) => boolean): FilesSeen | null {
  const base = kept ?? EMPTY_FILES
  const found = facts.seen ?? null
  const take = (part: 'control' | 'workspace') => {
    const read = facts[part] ?? null
    return read !== null && sameSeen(base[part], found?.[part] ?? null) ? read : base[part]
  }
  const taken = { control: take('control'), workspace: take('workspace'), settings: facts.settings ?? base.settings }
  const edits = [...base.edits.filter(e => !editFacts(e).every(f => logged(interventionKey(f.fact)))), ...editsOf(base, taken, at)]
  const next: FilesSeen = { v: 2, ...taken, edits, off: false }
  return JSON.stringify(next) === JSON.stringify(kept) ? null : next
}

// --- the companion's log ------------------------------------------------------------------------------

// windowed: the companion's log, one JSON object per line, as the objects of the lines that read and
// are within the window, with their time; the newest COMPANION_MAX_LINES lines only.
function windowed(text: string | null, now: Ms): { o: Record<string, unknown>; at: number }[] {
  if (text === null) return []
  const out: { o: Record<string, unknown>; at: number }[] = []
  for (const raw of text.split('\n').slice(-COMPANION_MAX_LINES)) {
    if (raw.trim() === '') continue
    let o: Record<string, unknown>
    try {
      const v: unknown = JSON.parse(raw)
      if (v === null || typeof v !== 'object' || Array.isArray(v)) continue
      o = v as Record<string, unknown>
    } catch {
      continue
    }
    const at = typeof o.at === 'number' ? o.at : typeof o.at === 'string' ? Date.parse(o.at) : Number.NaN
    if (!Number.isFinite(at) || now - at > COMPANION_WINDOW_MS) continue
    out.push({ o, at })
  }
  return out
}

const natural = (v: unknown) => (typeof v === 'number' && Number.isInteger(v) && v >= 0 ? v : null)

// companionLines: the companion's log; a line that does not read, or names a cause it does not log, is
// skipped. Only lines within the window.
export function companionLines(text: string | null, now: Ms): CompanionLine[] {
  const out: CompanionLine[] = []
  for (const { o, at } of windowed(text, now)) {
    const cause = COMPANION_CAUSES.find(c => c === o.cause)
    if (cause === undefined) continue
    out.push({
      at,
      issue: natural(o.issue) === 0 ? null : natural(o.issue),
      life: typeof o.life === 'string' && /^[0-9a-z]+$/.test(o.life) ? o.life : null,
      seq: natural(o.seq),
      cause,
      reason: typeof o.reason === 'string' ? o.reason : '',
    })
  }
  return out
}

// gateLines: the companion's gate lines (`gate-pass`, `gate-fail`, `gate-unknown`, `gate-wait`) that
// name an issue, a life and a seq, within the window. Their values are kept as written, for
// rules-gates.ts to check against the schema.
export function gateLines(text: string | null, now: Ms): GateLine[] {
  const out: GateLine[] = []
  const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : null)
  for (const { o, at } of windowed(text, now)) {
    const cause = [...GATE_RUN_CAUSES, 'gate-wait' as const].find(c => c === o.cause)
    const issue = natural(o.issue)
    const seq = natural(o.seq)
    if (cause === undefined || issue === null || issue === 0 || seq === null || typeof o.life !== 'string' || !/^[0-9a-z]+$/.test(o.life)) continue
    const ms = num(o.ms)
    const waitMs = num(o.waitMs)
    const startedAt = typeof o.startedAt === 'string' ? o.startedAt : null
    const parsed = startedAt === null ? Number.NaN : Date.parse(startedAt)
    const start = ms === null || waitMs === null ? Number.NaN : at - ms - waitMs
    out.push({
      at,
      issue,
      life: o.life,
      seq,
      cause,
      head: o.head === null || typeof o.head === 'string' ? o.head : undefined,
      ms,
      waitMs,
      concurrency: o.concurrency === null ? null : (num(o.concurrency) ?? undefined),
      startedAt,
      startedMs: Number.isFinite(parsed) ? parsed : null,
      derived: Number.isFinite(start) && Math.abs(start) <= 8.64e15 ? { iso: new Date(start).toISOString(), ms: Math.trunc(start) } : null,
      queuedBehind: num(o.queuedBehind),
      clean: typeof o.clean === 'boolean' ? o.clean : null,
      hasClean: 'clean' in o,
      failedTests: Array.isArray(o.failedTests) && o.failedTests.every(t => typeof t === 'string') ? (o.failedTests as string[]) : null,
      rerun: o.rerun === true,
    })
  }
  return out
}

// --- one pass's read ----------------------------------------------------------------------------------

// The loop's base directory: the loop dir's parent (contract.mjs loopDirOf), where the workspace
// config.json and the OFF file live.
export function baseOf(loopDir: string): string {
  return loopDir.replace(/\/[^/]+\/?$/, '')
}

// readInterventions: the companion's lines and the owner's files as they are now. A file that
// could not be read is null, and the source says why.
export async function readInterventions(ctx: SourceCtx): Promise<{ read: InterventionFacts; source: Source }> {
  const now = ctx.now
  const errors: string[] = []
  const read = async (path: string): Promise<string | null | undefined> => {
    try {
      return await ctx.readFile(path)
    } catch (err) {
      errors.push(`${path}: ${String(err).slice(0, 120)}`)
      return undefined
    }
  }
  const [companion, control, workspace] = await Promise.all([
    read(`${ctx.rt.loopDir}/companion.jsonl`),
    read(`${ctx.rt.loopDir}/control.json`),
    read(`${baseOf(ctx.rt.loopDir)}/config.json`),
  ])
  const controlSeen = control === undefined ? null : seenOf(control ?? '')
  const workspaceSeen = workspace === undefined ? null : seenOf(workspace ?? '')
  // the settings are what the repo-local file says, which a person edits, never the defaults a build
  // fills in; not read when origin's default branch was not, so the checkout's file stands in for
  // this pass only (v2/settings.ts)
  const settingsSeen = ctx.rt.repoSettings == null ? null : seenOf(JSON.stringify(ctx.rt.repoSettings))
  const facts: InterventionFacts = {
    companion: companionLines(companion ?? null, now),
    gates: gateLines(companion ?? null, now),
    controlDigest: controlSeen?.digest ?? null,
    configDigest: workspaceSeen === null || settingsSeen === null ? null : digest(`${workspaceSeen.text}\n${settingsSeen.text}`),
    control: controlSeen,
    workspace: workspaceSeen,
    settings: settingsSeen,
  }
  const source: Source = errors.length === 0 ? { ok: true, at: now } : { ok: false, at: now, error: errors.join('; ').slice(0, 300) }
  return { read: facts, source }
}

files.hooks/v2/sources-prs.ts:
// The `prs` source (docs/factory-loop/v2/SPEC.md 2.4): for each record in reviewing or the merge
// queue whose life has a PR (rules-review.ts lifePr: the record's, else the one the life's done
// ensure named, 8.1, so a PR the ensure just opened is read on the next pass), the PR
// (callum-flow-issue-read --json --pr <n>: state, merged, merged head, closedAt, head,
// mergeable_state, author, base commit), its check runs (gh pr checks <n> --repo R --json
// name,state,bucket,startedAt,completedAt,link, the run id from the link) plus its workflow runs
// (gh api repos/R/actions/runs?head_sha=H, the latest per workflow and event, a synthetic check
// for a run no visible check shows: one with no job yet is in no `gh pr checks` view) and, when the head moved,
// its patch id (8.4: callum-flow-patch-id <head> <default branch>, kept per head, so it is computed
// once); main's head on origin when a merge-queue PR is open, for Q1 (9.2); and the time
// observe first saw each head (heads:<repo>), whose entries go when their PR closes or its record
// does. Reads go in 2.4's order, the queue's head first, then the other records in reviewing and
// the merge queue, for at most ctx.prBudget records (K, a budget of its own; none during a GitHub
// backoff), and stop at a rate limit met this pass (ctx.limited). A PR whose read fails in any
// part (the PR, its checks, its workflow runs, its patch id) is left out and listed in `unread` with why (and whether
// the reader refused it for an untrusted author, exit 3): only its own record waits on it, never
// the others, so the source fails only when `cut` says why reads stopped before every record was
// read. The rules read a missing PR as not read, never as a fact, except an untrusted author's,
// which is one (9.3, policy). A PR is read only when its read is due (observe.ts readDue): until
// then an earlier pass's view stands for it (ctx.kept), with its own read time.
import type { RunResult } from '../exec'
import type { LedgerEntry, Ms, Source } from '../types'
import { jobIdOf } from './refused'
import { checkRunAnnotationsArgv, lsRemoteArgv, patchIdArgv, prChecksArgv, prReadArgv, prRunsArgv, runJobsArgv } from './argv'
import type { SourceCtx } from './observe'
import { excludedOf, queueOf } from './rules-queue'
import { lifePr } from './rules-review'
import type { HeadSeen, IssueRecord } from './types'

export type CheckRun = {
  name: string
  state: string
  // refused: a GitHub Actions job GitHub did not start (the account's billing, not the code), see notStartedOf
  bucket: 'pass' | 'fail' | 'pending' | 'skipping' | 'cancel' | 'refused'
  startedAt: number | null
  completedAt: number | null
  runId: string | null
  link: string | null
  // GitHub's own message for a refused job, clipped to REFUSED_MAX
  refusedWhy?: string | null
}

export type PrView = {
  pr: number
  issue: number
  state: 'open' | 'closed' | 'merged'
  head: string | null
  mergedHead: string | null
  closedAt: string | null
  mergeable: string | null
  author: string | null
  // the commit of main the PR's head was last based on (the REST pull's base.sha)
  base: string | null
  // the branch the PR targets (the REST pull's base.ref)
  baseRef: string | null
  // the PR's label names; null when the read did not show them
  labels: string[] | null
  checks: CheckRun[]
  patch: string | null
  readAt: number
}

// A PR whose read was tried this pass and failed: why, whether the reader refused it because its
// author is not trusted (callum-flow-issue-read exit 3), and since when its reads have failed: the
// first of the passes in a row that tried it and failed (ctx.unread, the last pass's), which the
// rules' bound on its wait counts from, so one failed read holds and only one that keeps failing
// ends the step.
export type PrUnread = { pr: number; issue: number; why: string; untrusted: boolean; since: Ms }

// main: the default branch and its head on origin, read when a merge-queue PR is open (sha
// null when that read failed); absent when nothing needed it. unread: the PRs tried that did not
// read. cut: why the reads stopped before every record's PR was tried (a GitHub rate limit, or no
// budget during a backoff); absent when none was left untried.
export type PrsRead = { prs: PrView[]; main?: { branch: string; sha: string | null } | null; unread?: PrUnread[]; cut?: string }

export const EMPTY_PRS: PrsRead = { prs: [] }

const READ_MS = 60_000
// a patch id fetches the head and main first
const PATCH_MS = 120_000

// --- parsing what the CLIs print ----------------------------------------------------------------------

// The REST pull object as callum-flow-issue-read --json --pr prints it ({ pr, stripped }), read
// for what the loop needs; null when it does not read.
export type Pull = { state: PrView['state']; head: string | null; mergedHead: string | null; closedAt: string | null; mergeable: string | null; author: string | null; base: string | null; baseSha: string | null; labels: string[] | null }

// labelsOf: the names of a REST pull's labels; null when the field is missing or is not a list of
// named objects (the hold then fails closed).
function labelsOf(v: unknown): string[] | null {
  if (!Array.isArray(v)) return null
  const names: string[] = []
  for (const l of v) {
    const n = l !== null && typeof l === 'object' ? (l as Record<string, unknown>).name : undefined
    if (typeof n !== 'string' || n === '') return null
    names.push(n)
  }
  return names
}

export function pullOf(json: string): Pull | null {
  let o: Record<string, unknown>
  try {
    const top = JSON.parse(json) as Record<string, unknown> | null
    const pr = top?.pr
    if (pr === null || typeof pr !== 'object' || Array.isArray(pr)) return null
    o = pr as Record<string, unknown>
  } catch {
    return null
  }
  const str = (v: unknown): string | null => (typeof v === 'string' && v !== '' ? v : null)
  const sub = (v: unknown, k: string): unknown => (v !== null && typeof v === 'object' ? (v as Record<string, unknown>)[k] : undefined)
  if (o.state !== 'open' && o.state !== 'closed') return null
  const head = str(sub(o.head, 'sha'))
  const merged = o.merged === true || str(o.merged_at) !== null
  return {
    state: merged ? 'merged' : o.state,
    head,
    mergedHead: merged ? head : null,
    closedAt: str(o.closed_at),
    mergeable: str(o.mergeable_state)?.toLowerCase() ?? null,
    author: str(sub(o.user, 'login')),
    base: str(sub(o.base, 'ref')),
    baseSha: str(sub(o.base, 'sha')),
    labels: labelsOf(o.labels),
  }
}

// the buckets `gh pr checks` names; `refused` is the loop's own (classifyRefused)
const BUCKETS: readonly CheckRun['bucket'][] = ['pass', 'fail', 'pending', 'skipping', 'cancel']

// timeOf: a check's start or end; GitHub gives the zero time for one not started or not done.
function timeOf(v: unknown): Ms | null {
  const t = typeof v === 'string' ? Date.parse(v) : Number.NaN
  return Number.isFinite(t) && t > 0 ? t : null
}

// checksOf: the head's check runs from `gh pr checks --json`, which exits 8 while one is pending
// and 1 when one failed, so the output decides, not the exit; a head with no check yet is an
// empty list. null when it does not read.
export function checksOf(r: RunResult): CheckRun[] | null {
  let list: unknown
  try {
    list = JSON.parse(r.stdout)
  } catch {
    return /no checks reported/i.test(`${r.stderr}\n${r.stdout}`) ? [] : null
  }
  if (!Array.isArray(list)) return null
  const out: CheckRun[] = []
  for (const raw of list) {
    const c = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
    if (typeof c.name !== 'string') return null
    const link = typeof c.link === 'string' && c.link !== '' ? c.link : null
    out.push({
      name: c.name,
      state: typeof c.state === 'string' ? c.state : '',
      // a bucket gh does not name waits, bounded like any pending check
      bucket: BUCKETS.find(b => b === c.bucket) ?? 'pending',
      startedAt: timeOf(c.startedAt),
      completedAt: timeOf(c.completedAt),
      runId: /\/actions\/runs\/(\d+)/.exec(link ?? '')?.[1] ?? null,
      link,
    })
  }
  return out
}

export type WorkflowRun = {
  id: string
  name: string
  kind: 'pending' | 'done' | 'fail' | 'cancel'
  link: string | null
  startedAt: Ms | null
  completedAt: Ms | null
}

// runsOf: the head's workflow runs from `gh api repos/R/actions/runs?head_sha=H&per_page=100`,
// the latest run per (workflow_id, event) only (the highest run id; an older one a newer run
// replaced, for example one concurrency cancelled, is ignored), each classified. null when the
// read fails, does not parse, or lists fewer runs than total_count (fail closed).
export function runsOf(r: RunResult): WorkflowRun[] | null {
  if (r.exitCode !== 0) return null
  let o: unknown
  try {
    o = JSON.parse(r.stdout)
  } catch {
    return null
  }
  if (o === null || typeof o !== 'object') return null
  const { total_count: total, workflow_runs: list } = o as Record<string, unknown>
  if (!Array.isArray(list) || typeof total !== 'number' || total > list.length) return null
  const latest = new Map<string, { n: number; run: WorkflowRun }>()
  for (const raw of list) {
    const x = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
    if (typeof x.id !== 'number' || !Number.isInteger(x.id)) return null
    const name = typeof x.name === 'string' && x.name !== '' ? x.name : typeof x.path === 'string' ? x.path : `workflow ${String(x.workflow_id)}`
    const status = typeof x.status === 'string' ? x.status : ''
    const conclusion = typeof x.conclusion === 'string' ? x.conclusion : null
    let kind: WorkflowRun['kind'] = 'pending'
    if (status === 'completed') {
      if (conclusion === 'success' || conclusion === 'skipped' || conclusion === 'neutral') kind = 'done'
      else if (conclusion === 'failure' || conclusion === 'timed_out' || conclusion === 'startup_failure') kind = 'fail'
      else if (conclusion === 'cancelled') kind = 'cancel'
    }
    const link = typeof x.html_url === 'string' && x.html_url !== '' ? x.html_url : null
    const run: WorkflowRun = {
      id: String(x.id),
      name,
      kind,
      link,
      startedAt: timeOf(x.run_started_at) ?? timeOf(x.created_at),
      completedAt: status === 'completed' ? timeOf(x.updated_at) : null,
    }
    const key = `${String(x.workflow_id)}\u0000${String(x.event)}`
    const seen = latest.get(key)
    if (seen === undefined || x.id > seen.n) latest.set(key, { n: x.id, run: run })
  }
  return [...latest.values()].map(v => v.run)
}

// withRuns: the visible checks plus one synthetic check for each latest run whose state no visible
// check of that run shows (a run with no job yet): a pending run when no check of it is pending,
// a failed or cancelled one when no check of it is fail or cancel.
export function withRuns(checks: readonly CheckRun[], runs: readonly WorkflowRun[]): CheckRun[] {
  const out = [...checks]
  for (const run of runs) {
    if (run.kind === 'done') continue
    const mine = checks.filter(c => c.runId === run.id)
    const shown = run.kind === 'pending' ? mine.some(c => c.bucket === 'pending') : mine.some(c => c.bucket === 'fail' || c.bucket === 'cancel')
    if (shown) continue
    out.push({
      name: `${run.name} (workflow run, no job yet)`,
      state: run.kind === 'pending' ? 'PENDING' : run.kind === 'fail' ? 'FAILURE' : 'CANCELLED',
      bucket: run.kind,
      startedAt: run.startedAt,
      completedAt: run.completedAt,
      runId: run.id,
      link: run.link,
    })
  }
  return out
}

// --- refused jobs (docs/factory-loop/v2/SPEC.md 8.5, "Refused jobs") --------------------------------------

export const REFUSED_MAX = 200
// the start of the annotation GitHub puts on a job it did not start for the account's sake
const NOT_STARTED = 'The job was not started'

// A latest job of a run, as far as the classification reads it.
export type RunJob = { id: string; failed: boolean; steps: number; runnerless: boolean }

// jobsOf: the latest jobs of a run from `gh api repos/R/actions/runs/<run>/jobs?filter=latest&per_page=100`.
// null when the read fails, does not parse, or lists fewer jobs than total_count (fail closed).
export function jobsOf(r: RunResult): RunJob[] | null {
  if (r.exitCode !== 0) return null
  let o: unknown
  try {
    o = JSON.parse(r.stdout)
  } catch {
    return null
  }
  if (o === null || typeof o !== 'object') return null
  const { total_count: total, jobs: list } = o as Record<string, unknown>
  if (!Array.isArray(list) || typeof total !== 'number' || total > list.length) return null
  const out: RunJob[] = []
  for (const raw of list) {
    const x = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
    if (typeof x.id !== 'number' || !Number.isInteger(x.id)) return null
    const runner = x.runner_id === 0 || x.runner_id === null || x.runner_id === undefined
    const named = typeof x.runner_name === 'string' && x.runner_name !== ''
    out.push({
      id: String(x.id),
      failed: x.status === 'completed' && x.conclusion === 'failure',
      steps: Array.isArray(x.steps) ? x.steps.length : 1,
      runnerless: runner && !named,
    })
  }
  return out
}

// notStartedOf: GitHub's message when a check run's annotations say the job was not started (the
// account's payments failed or its spending limit is reached), clipped; null when none says so, or
// the read fails or does not parse (the job then stays failed).
export function notStartedOf(r: RunResult): string | null {
  if (r.exitCode !== 0) return null
  let list: unknown
  try {
    list = JSON.parse(r.stdout)
  } catch {
    return null
  }
  if (!Array.isArray(list)) return null
  for (const raw of list) {
    const x = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
    const m = typeof x.message === 'string' ? x.message.replace(/\s+/g, ' ').trim() : ''
    if (m.startsWith(NOT_STARTED)) return m.length > REFUSED_MAX ? `${m.slice(0, REFUSED_MAX - 3)}...` : m
  }
  return null
}

// A job's classification never changes (a re-run makes a new job id): its refusal message, or null
// when it failed on its own. Kept by repo and job id, like PATCHES.
const JOBS = new Map<string, string | null>()

type Failed = { why: string }

// classifyRefused: the failed checks of Actions runs, with a job id, that GitHub refused to start
// (zero steps, no runner, and the annotation "The job was not started ...") become `refused`. One
// jobs read per run with checks not yet classified, one annotations read per zero-step, runnerless
// failed job. A read that fails or does not parse fails the PR's read (fail closed: never red,
// never green on a guess).
async function classifyRefused(ctx: SourceCtx, checks: CheckRun[]): Promise<CheckRun[] | Failed> {
  const repo = ctx.rt.repo
  const fresh = checks.filter(c => c.bucket === 'fail' && c.runId !== null && jobIdOf(c.link) !== null && !JOBS.has(`${repo} ${jobIdOf(c.link)}`))
  for (const runId of new Set(fresh.map(c => c.runId))) {
    if (runId === null) continue
    const w = await ctx.run(runJobsArgv(repo, runId), undefined, READ_MS).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
    const jobs = jobsOf(w)
    if (jobs === null) return { why: `gh api actions/runs/${runId}/jobs exit ${w.exitCode}: ${lastLine(w) || 'the jobs do not read whole'}` }
    for (const c of fresh.filter(x => x.runId === runId)) {
      const id = jobIdOf(c.link) ?? ''
      const job = jobs.find(j => j.id === id)
      // a job the latest attempt does not list is an older attempt's: failed, and read again next time
      if (job === undefined) continue
      if (!job.failed || job.steps > 0 || !job.runnerless) {
        JOBS.set(`${repo} ${id}`, null)
        continue
      }
      const a = await ctx.run(checkRunAnnotationsArgv(repo, id), undefined, READ_MS).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
      if (a.exitCode !== 0) return { why: `gh api check-runs/${id}/annotations exit ${a.exitCode}: ${lastLine(a)}` }
      let parses = true
      try {
        parses = Array.isArray(JSON.parse(a.stdout))
      } catch {
        parses = false
      }
      if (!parses) return { why: `the annotations of job ${id} do not parse` }
      JOBS.set(`${repo} ${id}`, notStartedOf(a))
    }
  }
  return checks.map(c => {
    const why = c.bucket === 'fail' ? JOBS.get(`${repo} ${jobIdOf(c.link)}`) : undefined
    return why === undefined || why === null ? c : { ...c, bucket: 'refused', refusedWhy: why }
  })
}

// shaOf: the head `git ls-remote origin refs/heads/<branch>` prints, or null.
export function shaOf(stdout: string, branch: string): string | null {
  for (const line of stdout.split('\n')) {
    const [sha, ref] = line.trim().split(/\s+/)
    if (ref === `refs/heads/${branch}` && sha !== undefined && /^[0-9a-f]{40,64}$/.test(sha)) return sha
  }
  return null
}

// --- one pass's reads ----------------------------------------------------------------------------------

// The patch ids computed, by repo, base and head: a head's patch id is fixed once its merge base
// is, so it is computed when the head moves and kept while the head is.
const PATCHES = new Map<string, string>()

// prRecords: the records whose PR the source reads, each with its life's PR (lifePr), in 2.4's
// order: the queue's head, then the other records in reviewing and the merge queue, oldest seq
// first.
export function prRecords(records: readonly IssueRecord[], excluded: readonly number[], ledger: readonly LedgerEntry[]): (IssueRecord & { pr: number })[] {
  const head = queueOf(records, excluded)[0]
  const rank = (r: IssueRecord) => (r === head ? 0 : 1)
  return records
    .filter(r => r.state === 'reviewing' || r.state === 'merge-queue')
    .sort((a, b) => rank(a) - rank(b) || a.seqAt - b.seqAt || a.issue - b.issue)
    .flatMap(r => {
      const pr = lifePr(ledger, r)
      return pr === null ? [] : [{ ...r, pr }]
    })
}

// readPrs: the PRs of the records that have one, main's head when a merge-queue PR is open, and
// the heads first seen, updated.
export async function readPrs(ctx: SourceCtx): Promise<{ read: PrsRead; source: Source; heads: Record<string, HeadSeen> }> {
  const now = ctx.now
  const want = prRecords(ctx.records, (ctx.reads === undefined ? ctx.state.control.paused : excludedOf(ctx.records, ctx.state.control.paused, ctx.reads, ctx.kept)), ctx.state.ledger)
  const kept = ctx.kept.filter(v => want.some(r => r.pr === v.pr && r.issue === v.issue))
  const due = want.filter(r => !kept.some(v => v.pr === r.pr && v.issue === r.issue))
  const checkout = ctx.state.checkout
  const defaultBranch = checkout !== null && !('error' in checkout) ? checkout.defaultBranch : null
  const prs: PrView[] = []
  const unread: PrUnread[] = []
  let cut: string | undefined
  if (due.length > 0 && ctx.prBudget <= 0) cut = 'GitHub rate limit: no PR is read this pass'
  for (const r of due.slice(0, Math.max(0, ctx.prBudget))) {
    if (ctx.limited()) {
      cut = 'a GitHub rate limit met this pass ended the PR reads'
      break
    }
    const v = await readOne(ctx, r, defaultBranch)
    if ('why' in v) {
      const since = ctx.unread.find(u => u.pr === r.pr && u.issue === r.issue)?.since ?? now
      unread.push({ pr: r.pr, issue: r.issue, why: v.why, untrusted: v.untrusted, since })
      continue
    }
    prs.push(v)
  }
  prs.push(...kept)
  let main: PrsRead['main'] = null
  const queued = prs.findIndex(v => v.state === 'open' && want.some(r => r.pr === v.pr && r.state === 'merge-queue'))
  // the default branch's name, the head's base when the main checkout's read failed
  const branch = defaultBranch ?? prs[queued]?.baseRef ?? null
  if (queued >= 0 && branch !== null && !ctx.limited()) {
    const r = await ctx.run(lsRemoteArgv(branch), undefined, READ_MS).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
    // a sha that did not read holds that head alone (rules-queue.ts update)
    main = { branch, sha: r.exitCode === 0 ? shaOf(r.stdout, branch) : null }
  }
  const heads = headsOf(ctx.heads, ctx.records, prs, now, ctx.state.ledger)
  for (const k of [...PATCHES.keys()]) {
    const sha = k.split(' ').at(-1) ?? ''
    if (heads[sha] === undefined) PATCHES.delete(k)
  }
  const source: Source = cut === undefined ? { ok: true, at: now } : { ok: false, at: now, error: cut }
  const read: PrsRead = { prs, main }
  if (unread.length > 0) read.unread = unread
  if (cut !== undefined) read.cut = cut
  return { read, source, heads }
}

// readOne: one record's PR: the PR itself, and for an open one its checks and its head's patch id.
async function readOne(ctx: SourceCtx, r: IssueRecord & { pr: number }, defaultBranch: string | null): Promise<PrView | { why: string; untrusted: boolean }> {
  const failed = (why: string, untrusted = false) => ({ why, untrusted })
  const read = await ctx.run(prReadArgv(r.pr), undefined, READ_MS).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
  if (read.exitCode === 3) return failed('not by a trusted author (callum-flow-issue-read exit 3)', true)
  if (read.exitCode !== 0) return failed(`callum-flow-issue-read exit ${read.exitCode}: ${lastLine(read)}`)
  const pull = pullOf(read.stdout)
  if (pull === null) return failed('the PR read does not parse')
  let checks: CheckRun[] = []
  let patch: string | null = null
  if (pull.state === 'open') {
    const c = await ctx.run(prChecksArgv(ctx.rt.repo, r.pr), undefined, READ_MS).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
    const parsed = checksOf(c)
    if (parsed === null) return failed(`gh pr checks exit ${c.exitCode}: ${lastLine(c)}`)
    checks = parsed
    if (pull.head !== null) {
      const w = await ctx.run(prRunsArgv(ctx.rt.repo, pull.head), undefined, READ_MS).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
      const runs = runsOf(w)
      if (runs === null) return failed(`gh api actions/runs exit ${w.exitCode}: ${lastLine(w) || 'the workflow runs do not read whole'}`)
      const classified = await classifyRefused(ctx, withRuns(parsed, runs))
      if ('why' in classified) return failed(classified.why)
      checks = classified
    }
    const base = defaultBranch ?? pull.base
    if (pull.head !== null && base !== null) {
      const p = await patchOf(ctx, pull.head, base)
      if (typeof p !== 'string') return failed(p.why)
      patch = p
    }
  }
  return { pr: r.pr, issue: r.issue, state: pull.state, head: pull.head, mergedHead: pull.mergedHead, closedAt: pull.closedAt, mergeable: pull.mergeable, author: pull.author, base: pull.baseSha, baseRef: pull.base, labels: pull.labels, checks, patch, readAt: ctx.now }
}

async function patchOf(ctx: SourceCtx, head: string, base: string): Promise<string | { why: string }> {
  const key = `${ctx.rt.repo} ${base} ${head}`
  const kept = PATCHES.get(key)
  if (kept !== undefined) return kept
  const r = await ctx.run(patchIdArgv(head, base), undefined, PATCH_MS).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
  const id = r.stdout.trim()
  if (r.exitCode !== 0 || !/^[0-9a-f]{40,64}$/.test(id)) return { why: `the patch id of ${head.slice(0, 7)} did not compute: ${lastLine(r) || `exit ${r.exitCode}`}` }
  PATCHES.set(key, id)
  return id
}

// headsOf: the heads first seen (2.4): an open PR's head the first time it is read; a head goes
// when its PR is read closed or merged, or its record closed (a closed record stays in the store
// for a week). A record's PR is its life's (lifePr). A head whose PR no record names stays:
// records that could not be read are no reason to forget when a head was first seen.
export function headsOf(before: Readonly<Record<string, HeadSeen>>, records: readonly IssueRecord[], prs: readonly PrView[], now: Ms, ledger: readonly LedgerEntry[]): Record<string, HeadSeen> {
  const prsOf = (rs: IssueRecord[]) => rs.flatMap(r => lifePr(ledger, r) ?? [])
  const live = new Set(prsOf(records.filter(r => r.state !== 'closed')))
  const closed = new Set(prsOf(records.filter(r => r.state === 'closed')).filter(pr => !live.has(pr)))
  const ended = new Set(prs.filter(v => v.state !== 'open').map(v => v.pr))
  const out: Record<string, HeadSeen> = {}
  for (const [sha, h] of Object.entries(before)) if (!closed.has(h.pr) && !ended.has(h.pr)) out[sha] = h
  for (const v of prs) if (v.state === 'open' && v.head !== null && out[v.head] === undefined) out[v.head] = { pr: v.pr, at: now }
  return out
}

function lastLine(r: { stdout: string; stderr: string }): string {
  return (r.stderr.trim() || r.stdout.trim()).split('\n').pop()?.slice(0, 200) ?? ''
}

