// The facts and the ledger rebuild's read of the event log (docs/factory-loop/v2/SPEC.md 3.3) and its
// source switch `eventsSource`, the same switch as the record rebuild's (sources-records.ts): `old` reads
// factory.events (EVENTS_SQL), `new` reads factory.event_store (NEW_EVENTS_SQL), and `shadow` (opt-in; `new`
// is the default since #978) decides on the old read and compares it with the new one, once per load and then at most
// hourly. Four things are compared: the newest `reclaimed` and the newest `ready` per issue
// (facts.reclaimed, facts.readyAt), the ledger
// deriveLedger rebuilds for this device, and the once keys v2's `logged` reads. The compare is written
// as a `shadow_read` event (reader `loop-facts`) and told to the owner by rules-shadow.ts.
//
// The new rows are mapped to the FactoryEvent that factsOf, deriveLedger and onceKey read, with the
// old state name, so those stay the one code path. A failing new read never fails a pass under
// `shadow`; under `new` it fails the read, and no row is ever skipped.
//
// The production new store holds only dual-written events, so the old read's window reaches back before
// it begins. The compare therefore reads each device's first new-store time for the repo (NEW_FLOORS_SQL)
// and leaves out of both sides the events of a device older than its floor (docs/factory-events/replay.md).
//
// The facts no v2 path reads (briefs, reviewFixes, verdicts, superseded, answered, pipeline) come out
// empty under `new`: only runsFromEvents reads them, and only the plan replay and the state digest read
// its runs (docs/factory-events/replay.md).
import { EVENTS_SQL, deriveLedger, eventsFromRows, factsOf, loopNote } from '../derive'
import type { FactoryEvent } from '../derive'
import { parseCsv } from '../parse'
import type { LedgerEntry } from '../types'
import { readEvent } from './event-reader'
import { eventNote, onceKey } from './events'
import type { ShadowReadData } from './events'
import { sameValue } from './same-value'
import { failedShadow, SETTLE_MS, SHADOW_EVERY_MS } from './sources-records'
import type { Ctx, Read } from './sources-records'

export const FACTS_SHADOW_READER = 'loop-facts'
const MAX_KEYS = 50

// The new types the facts read, each under the old state name the facts code reads: requeued as
// `reclaimed`, claim_renewed as `renewed`, loop_entry as `loop`. A `closed` event counts only from
// the sweep, whose actor deriveLedger reads.
export const FACTS_TYPES = ['requeued', 'claimed', 'claim_renewed', 'merged', 'loop_entry', 'intervention', 'reviewed', 'ready'] as const

// The dev-query SQL that reads the new store's events for the facts and the ledger rebuild, with the
// variables repo, at and days (EVENTS_SQL's), over all devices, oldest first, in the columns
// eventsFromNewRows reads.
export const NEW_EVENTS_SQL = `select
  envelope, event_id,
  to_char(ts at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') as ts,
  type, type_version, repo, device, actor, session_id, issue, base_image, dev_image, template_version,
  plugin_version, device_seq, data
from factory.event_store
where repo = :'repo'
  and ts <= :'at'::timestamptz
  and ts > :'at'::timestamptz - make_interval(days => :'days'::int)
  and (type in (${FACTS_TYPES.map(t => `'${t}'`).join(', ')}) or (type = 'closed' and actor = 'sweep'))
order by ts, device, device_seq;
`

// The dev-query SQL that reads each device's first time in the new store for the repo (variable repo),
// over every type, cut to whole seconds as the old log stores times: the columns device and floor.
export const NEW_FLOORS_SQL = `select device,
  to_char(date_trunc('second', min(ts)) at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') as floor
from factory.event_store
where repo = :'repo' and device is not null
group by device
order by device;
`

// floorsFromRows: the floors of the rows of NEW_FLOORS_SQL, by device, in ms. A row that does not read
// throws, so the floor read fails (and the compare with it) rather than compare with a partial floor.
export function floorsFromRows(rows: readonly Record<string, string>[]): Map<string, number> {
  const floors = new Map<string, number>()
  for (const row of rows) {
    const at = Date.parse(row.floor ?? '')
    if (row.device === undefined || row.device === '' || Number.isNaN(at)) throw new Error(`source new: floor row does not read: ${JSON.stringify(row).slice(0, 150)}`)
    floors.set(row.device, at)
  }
  return floors
}

// One compare: the data of its `shadow_read` event, and each differing key with its text (ordered:
// reclaimed, ledger, once), for the owner's tell.
export type FactsShadow = { at: number; data: ShadowReadData; diffs: readonly { key: string; text: string }[] }

// --- the new rows as events (pure) ----------------------------------------------------------------

const orNull = (v: string | undefined): string | null => (v === undefined || v === '' ? null : v)
const numOrNull = (v: string | undefined): number | null => (v === undefined || v === '' ? null : Number(v))

// eventsFromNewRows: the FactoryEvents of the rows of NEW_EVENTS_SQL, oldest first. A row of an
// unknown type or version, or one the shared reader refuses, throws an Error that names its event_id
// and the source `new`, so the whole read fails. The time is cut to whole seconds, as the old log
// stores it, so the keys derived from it (claim:N:derived:<ts>) and the facts agree.
export function eventsFromNewRows(rows: readonly Record<string, string>[]): FactoryEvent[] {
  const events: FactoryEvent[] = []
  for (const row of rows) {
    try {
      events.push(eventOfRow(row))
    } catch (err) {
      throw new Error(`source new: event ${row.event_id ?? 'unknown'}: ${err instanceof Error ? err.message : String(err)}`.slice(0, 300))
    }
  }
  return events.sort((a, b) => a.ts - b.ts)
}

function eventOfRow(row: Record<string, string>): FactoryEvent {
  const at = Date.parse(row.ts ?? '')
  if (Number.isNaN(at)) throw new Error('ts does not read')
  let data: unknown
  try {
    data = JSON.parse(row.data ?? '')
  } catch {
    throw new Error('data is not JSON')
  }
  const e = readEvent({ envelope: Number(row.envelope), type: row.type, type_version: Number(row.type_version), data })
  const d = e.data
  const issue = numOrNull(row.issue)
  const event: FactoryEvent = { ts: Math.floor(at / 1000) * 1000, state: '', issue, run: null, branch: null, pr: null, head: null, note: null, actor: orNull(row.actor), device: orNull(row.device) }
  switch (e.type) {
    case 'requeued':
      return { ...event, state: 'reclaimed', branch: d.branch as string | null, pr: d.pr as number | null }
    case 'claimed':
      return { ...event, state: 'claimed' }
    case 'claim_renewed':
      return { ...event, state: 'renewed' }
    case 'closed':
      return { ...event, state: 'closed' }
    case 'ready':
      return { ...event, state: 'ready' }
    case 'merged':
      return { ...event, state: 'merged', branch: d.branch as string | null, pr: d.pr as number | null, head: d.head as string | null }
    case 'loop_entry': {
      // the note the loop's own writer builds, so entryFromLoop reads the entry back; the outcome
      // tokens and the run, PR and head columns are not in the new event (replay.md)
      const entry: LedgerEntry = {
        key: d.key as string,
        kind: d.kind as LedgerEntry['kind'],
        class: d.class as LedgerEntry['class'],
        rule: d.rule as string,
        issue: null,
        run: null,
        pr: null,
        head: null,
        status: d.status as LedgerEntry['status'],
        attempts: d.attempts as number,
        startedAt: Date.parse(d.started_at as string),
        endedAt: d.ended_at === null ? null : Date.parse(d.ended_at as string),
      }
      if (d.agent_id !== null) entry.agentId = d.agent_id as string
      if (d.wake !== null) entry.wake = d.wake as string
      return { ...event, state: 'loop', note: loopNote(entry) }
    }
    case 'intervention':
      return {
        ...event,
        state: 'intervention',
        pr: d.pr as number | null,
        note: eventNote({ state: 'intervention', who: d.who as 'person' | 'loop', cause: d.cause as string, reason: d.detail as string, issue, life: d.life as string | null, pr: d.pr as number | null, fact: d.fact as string }),
      }
    case 'reviewed': {
      if (issue === null) throw new Error('issue is missing')
      const reviewed = {
        state: 'reviewed' as const,
        issue,
        branch: d.branch as string,
        pr: d.pr as number,
        head: d.head as string,
        verdict: d.verdict as 'approve' | 'changes' | 'unknown',
        round: d.round as number,
        patch: d.patch as string,
        errors: d.errors as number,
        warnings: d.warnings as number,
        infos: d.infos as number,
        reviewer: d.reviewer as string,
        answer: d.answer_path as string,
      }
      return { ...event, state: 'reviewed', branch: reviewed.branch, pr: reviewed.pr, head: reviewed.head, note: eventNote(reviewed) }
    }
    default:
      throw new Error(`unknown type ${e.type}`)
  }
}

// --- the compare (pure) ---------------------------------------------------------------------------

// What the compared things hold: the newest `reclaimed` and `ready` times per issue, the ledger by key,
// and the once keys.
export type View = { reclaimed: Map<number, number>; readyAt: Map<number, number>; ledger: Map<string, LedgerEntry>; once: Set<string> }

// viewOf: the compared things of one side's events. The ledger entries the loop logged lose what the
// new `loop_entry` does not carry: the outcome and the run, PR and head columns (v2 reads those only
// of the entries it keys itself, which it never logs through a `loop` event), so both sides drop them.
export function viewOf(events: readonly FactoryEvent[], device: string): View {
  const list = [...events]
  const ledger = new Map<string, LedgerEntry>()
  for (const entry of deriveLedger(list, device)) {
    // the start-up migrate's record (factory-db-migrate) is written to the new store only, so it is no
    // difference between the stores
    if (entry.rule === 'dev-init' && entry.wake === 'migrate') continue
    if (entry.rule === 'derived') ledger.set(entry.key, entry)
    else ledger.set(entry.key, { ...entry, run: null, pr: null, head: null, outcome: undefined })
  }
  const once = new Set(list.flatMap(e => (e.device === null || e.device === device ? (onceKey(e) ?? []) : [])))
  const facts = factsOf(list)
  return { reclaimed: facts.reclaimed, readyAt: facts.readyAt, ledger, once }
}

const iso = (ms: number | undefined): string => (ms === undefined ? 'absent' : new Date(ms).toISOString())

export function diffViews(a: View, b: View): { key: string; text: string }[] {
  const out: { key: string; text: string }[] = []
  for (const issue of [...new Set([...a.reclaimed.keys(), ...b.reclaimed.keys()])].sort((x, y) => x - y)) {
    if (a.reclaimed.get(issue) !== b.reclaimed.get(issue)) out.push({ key: `reclaimed:#${issue}`, text: `#${issue} reclaimed: old ${iso(a.reclaimed.get(issue))}, new ${iso(b.reclaimed.get(issue))}` })
  }
  for (const issue of [...new Set([...a.readyAt.keys(), ...b.readyAt.keys()])].sort((x, y) => x - y)) {
    if (a.readyAt.get(issue) !== b.readyAt.get(issue)) out.push({ key: `ready:#${issue}`, text: `#${issue} ready: old ${iso(a.readyAt.get(issue))}, new ${iso(b.readyAt.get(issue))}` })
  }
  for (const key of [...new Set([...a.ledger.keys(), ...b.ledger.keys()])].sort()) {
    const x = a.ledger.get(key)
    const y = b.ledger.get(key)
    if (!sameValue(x, y)) out.push({ key: `ledger:${key}`, text: `ledger ${key}: old ${x === undefined ? 'absent' : JSON.stringify(x)}, new ${y === undefined ? 'absent' : JSON.stringify(y)}` })
  }
  for (const key of [...new Set([...a.once, ...b.once])].sort()) {
    if (a.once.has(key) !== b.once.has(key)) out.push({ key: `once:${key}`, text: `once ${key}: old ${a.once.has(key) ? 'present' : 'absent'}, new ${b.once.has(key) ? 'present' : 'absent'}` })
  }
  return out
}

// inScope: the events a device's floor leaves in. An event of a device with a floor is out when older
// than it (both are whole seconds, so the floor's own second stays in); an event of a device with no
// floor, or with no device, stays in.
const inScope = (floors: ReadonlyMap<string, number>) => (e: FactoryEvent): boolean => {
  const floor = e.device === null ? undefined : floors.get(e.device)
  return floor === undefined || e.ts >= floor
}

// compareFacts: the two sides' events, compared once on everything read (live) and once with both
// sides cut SETTLE_MS back from now (the differences that count). Before that both sides lose the
// events older than their device's first new-store time (`floors`, by device in ms): history the new
// store never held. The data names this device's floor and how many events were left out.
export function compareFacts(oldEvents: readonly FactoryEvent[], newEvents: readonly FactoryEvent[], device: string, now: number, at: number, floors: ReadonlyMap<string, number> = new Map()): FactsShadow {
  const cut = now - SETTLE_MS
  const keep = inScope(floors)
  const outOfScope = oldEvents.filter(e => !keep(e)).length + newEvents.filter(e => !keep(e)).length
  oldEvents = oldEvents.filter(keep)
  newEvents = newEvents.filter(keep)
  const floor = floors.get(device)
  const a = viewOf(oldEvents, device)
  const b = viewOf(newEvents, device)
  const live = diffViews(a, b)
  const settled = diffViews(viewOf(oldEvents.filter(e => e.ts <= cut), device), viewOf(newEvents.filter(e => e.ts <= cut), device))
  const compared = new Set([...a.reclaimed.keys()].map(n => `r${n}`).concat([...b.reclaimed.keys()].map(n => `r${n}`), [...a.readyAt.keys(), ...b.readyAt.keys()].map(n => `y${n}`), [...a.ledger.keys(), ...b.ledger.keys()].map(k => `l${k}`), [...a.once, ...b.once].map(k => `o${k}`))).size
  const data: ShadowReadData = {
    reader: FACTS_SHADOW_READER,
    tool: 'factory-loop',
    compared,
    differences: settled.length,
    live_differences: live.length,
    diff_keys: settled.slice(0, MAX_KEYS).map(d => d.key),
    old_ok: true,
    new_ok: true,
    settle_seconds: SETTLE_MS / 1000,
    detail: settled[0] === undefined ? null : settled[0].text.slice(0, 500),
    scope_floor: floor === undefined ? null : new Date(floor).toISOString(),
    out_of_scope: outOfScope,
  }
  return { at, data, diffs: settled }
}

// --- the reads --------------------------------------------------------------------------------------

// exitFail: why a command failed, as observe reports it.
export const exitFail = (r: { exitCode: number; stderr: string }): string => `exit ${r.exitCode}: ${r.stderr.trim().split('\n').pop()?.slice(0, 200) ?? ''}`

const eventsArgv = (ctx: Ctx, days: number, factory: boolean): string[] => [
  'dev-query',
  ...(factory ? ['--factory'] : []),
  '--csv',
  '-v',
  `repo=${ctx.rt.repo}`,
  '-v',
  `at=${new Date(ctx.now).toISOString()}`,
  '-v',
  `days=${days}`,
]

async function readOld(ctx: Ctx, days: number): Promise<Read<FactoryEvent[]>> {
  try {
    const r = await ctx.run(eventsArgv(ctx, days, false), EVENTS_SQL)
    return r.exitCode === 0 ? { ok: true, value: eventsFromRows(parseCsv(r.stdout)) } : { ok: false, error: exitFail(r) }
  } catch (err) {
    return { ok: false, error: String(err) }
  }
}

// readNew: a missing factory URL (dev-query exit 77 or 78) or any refused row fails the read.
async function readNew(ctx: Ctx, days: number): Promise<Read<FactoryEvent[]>> {
  try {
    const r = await ctx.run(eventsArgv(ctx, days, true), NEW_EVENTS_SQL)
    if (r.exitCode !== 0) return { ok: false, error: `the event read failed (source new): ${exitFail(r)}` }
    return { ok: true, value: eventsFromNewRows(parseCsv(r.stdout)) }
  } catch (err) {
    const text = err instanceof Error ? err.message : String(err)
    return { ok: false, error: `the event read failed: ${text.includes('source new') ? text : `source new: ${text}`}`.slice(0, 300) }
  }
}

// readFloors: each device's first new-store time for the repo; a failing read fails the compare.
async function readFloors(ctx: Ctx): Promise<Read<Map<string, number>>> {
  try {
    const r = await ctx.run(['dev-query', '--factory', '--csv', '-v', `repo=${ctx.rt.repo}`], NEW_FLOORS_SQL)
    if (r.exitCode !== 0) return { ok: false, error: `the floor read failed (source new): ${exitFail(r)}` }
    return { ok: true, value: floorsFromRows(parseCsv(r.stdout)) }
  } catch (err) {
    const text = err instanceof Error ? err.message : String(err)
    return { ok: false, error: `the floor read failed: ${text.includes('source new') ? text : `source new: ${text}`}`.slice(0, 300) }
  }
}

// readFacts: the events of the last `days` from the source `eventsSource` picks. With `cache` (the
// facts read, not the ledger rebuild's) and the source `shadow`, the new store is also read and the
// two compared into cache.factsShadow on the first call of a load and then at most hourly; that
// compare's failure is never returned, and the events are the old read's.
export async function readFacts(ctx: Ctx, days: number, cache?: { factsShadow?: FactsShadow }): Promise<Read<FactoryEvent[]>> {
  const { now, rt } = ctx
  const source = rt.config.eventsSource
  if (source === 'new') return readNew(ctx, days)
  const old = await readOld(ctx, days)
  if (source !== 'shadow' || cache === undefined) return old
  if (cache.factsShadow !== undefined && now - cache.factsShadow.at < SHADOW_EVERY_MS) return old
  const fresh = await readNew(ctx, days)
  const floors = fresh.ok ? await readFloors(ctx) : null
  if (old.ok && fresh.ok && floors?.ok === true) {
    cache.factsShadow = compareFacts(old.value, fresh.value, rt.device, now, now, floors.value)
  } else {
    const newError = !fresh.ok ? fresh.error : floors?.ok === false ? floors.error : null
    cache.factsShadow = { at: now, data: failedShadow(FACTS_SHADOW_READER, old.ok ? null : old.error, newError), diffs: [] }
  }
  return old
}

files.hooks/v2/sources-flakes.ts:
// The `flakes` source (docs/factory-loop/v2/SPEC.md 2.4, 8.5 rule F1): the flakes of the last
// flakeWindowDays and the repo's open flake bugs. One flake is a gate flake (a gate_run pass row
// with `flaky` true, once per issue, life, seq and started_at) or a CI flake (a ci-rerun
// intervention row with `flaky` true, once per issue and fact), as docs/metrics.md section 2d
// counts them; this read gives one row per flake per test with the event id of the flake's first
// row. The bugs are the open issues by trusted authors carrying the flaky label, read through the
// reader (which drops an untrusted author's issue), with the marker and flake ids in each body.
// Read in act mode only, on the githubEveryMs cadence, and again at once after an action of F1's
// own ended. A missing factory URL (dev-query exit 77) is no flakes; any other failure fails the
// source, and F1 plans nothing.
import { parseCsv } from '../parse'
import type { Ms, Source } from '../types'
import type { SourceCtx } from './observe'

const DAY = 86_400_000

// One flake of one test. `hash` is the first 16 hex digits of the sha256 of the test's exact name (the query computes it; a hooks module may not import node:crypto).
export type Flake = { id: string; source: 'gate' | 'ci'; issue: number | null; head: string | null; at: Ms; test: string; job: string | null; hash: string }
// An open flake bug: its hash (null: no marker), whether it is labelled ready, and the ids of the flakes its body names.
export type FlakeBug = { number: number; hash: string | null; ready: boolean; known: string[] }
export type FlakesRead = { flakes: Flake[]; bugs: FlakeBug[] }
export type FlakesCache = { at: Ms | null; read: FlakesRead | null; source: Source | null }
export const EMPTY_FLAKES: FlakesCache = { at: null, read: null, source: null }

export const FLAKY_LABEL = 'flaky'

const MARKER = /<!-- factory-loop:flake:([0-9a-f]{16}) -->/
const KNOWN = /<!-- factory-loop:flake-bug\/[0-9a-f]{16}\/c\/([0-9a-f-]{36}) -->/g

// The per-flake rows of docs/metrics.md section 2d ("the bug rule's read"): the test of a saved
// query there, which tests/metrics-flakes.test.js runs against PostgreSQL; the two must match.
export const FLAKES_SQL = `WITH gate AS (
  SELECT repo, issue, life, seq, started_at, max(head) AS head, min(ts) AS passed_at,
    (array_agg(event_id ORDER BY ts, device, device_seq))[1] AS event_id,
    (array_agg(failed_tests ORDER BY ts, device, device_seq))[1] AS tests
  FROM factory.event_log
  WHERE type = 'gate_run' AND flaky = true AND repo = :'repo' AND ts >= :'since'
  GROUP BY repo, issue, life, seq, started_at
), ci AS (
  SELECT repo, issue, coalesce(fact, event_id::text) AS fact, max(head) AS head, min(ts) AS passed_at,
    (array_agg(event_id ORDER BY ts, device, device_seq))[1] AS event_id,
    (array_agg(failed_jobs ORDER BY ts, device, device_seq))[1] AS jobs,
    (array_agg(failed_tests ORDER BY ts, device, device_seq))[1] AS tests
  FROM factory.event_log
  WHERE type = 'intervention' AND cause = 'ci-rerun' AND flaky = true AND repo = :'repo' AND ts >= :'since'
  GROUP BY repo, issue, coalesce(fact, event_id::text)
), flakes AS (
  SELECT 'gate' AS source, event_id, issue, head, passed_at, NULL::text AS job,
    CASE WHEN jsonb_typeof(tests) = 'array' THEN tests ELSE '[]'::jsonb END AS tests
  FROM gate
  UNION ALL
  SELECT 'ci', event_id, issue, head, passed_at,
    (SELECT string_agg(j, ', ' ORDER BY j)
       FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(jobs) = 'array' THEN jobs ELSE '[]'::jsonb END) AS j),
    CASE WHEN jsonb_typeof(tests) = 'array' THEN tests ELSE '[]'::jsonb END
  FROM ci
)
SELECT f.event_id, f.source, f.issue, f.head,
  to_char(f.passed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS passed_at, t.test, f.job,
  left(encode(sha256(convert_to(t.test, 'UTF8')), 'hex'), 16) AS hash
FROM flakes f
CROSS JOIN LATERAL jsonb_array_elements_text(f.tests) AS t(test)
ORDER BY f.passed_at, f.event_id, t.test;
`

// flakesFromRows: the flakes of FLAKES_SQL's rows; a row that does not read is dropped.
export function flakesFromRows(rows: readonly Record<string, string>[]): Flake[] {
  const out: Flake[] = []
  for (const r of rows) {
    const id = r.event_id ?? ''
    const at = Date.parse(r.passed_at ?? '')
    const test = r.test ?? ''
    if (!/^[0-9a-f-]{36}$/.test(id) || Number.isNaN(at) || test === '' || (r.source !== 'gate' && r.source !== 'ci')) continue
    const hash = r.hash ?? ''
    if (!/^[0-9a-f]{16}$/.test(hash)) continue
    const issue = Number(r.issue)
    out.push({ id, source: r.source, issue: Number.isInteger(issue) && issue > 0 ? issue : null, head: r.head === undefined || r.head === '' ? null : r.head, at, test, job: r.job === undefined || r.job === '' ? null : r.job, hash })
  }
  return out
}

// bugsFromJson: the open flake bugs of `callum-flow-issue-read --json --list --label flaky`; null
// when the output is not that list. An issue with no marker is kept with a null hash (it is
// labelled flaky by someone else and counts against nothing).
export function bugsFromJson(json: string): FlakeBug[] | null {
  let doc: unknown
  try {
    doc = JSON.parse(json)
  } catch {
    return null
  }
  const issues = doc !== null && typeof doc === 'object' ? (doc as { issues?: unknown }).issues : undefined
  if (!Array.isArray(issues)) return null
  const out: FlakeBug[] = []
  for (const raw of issues) {
    const o = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
    if (typeof o.number !== 'number' || !Number.isInteger(o.number) || typeof o.body !== 'string') continue
    const labels = Array.isArray(o.labels) ? o.labels.map(l => (typeof l === 'string' ? l : (l as { name?: unknown } | null)?.name)).filter((l): l is string => typeof l === 'string') : []
    out.push({ number: o.number, hash: MARKER.exec(o.body)?.[1] ?? null, ready: labels.some(l => l.toLowerCase() === 'ready'), known: [...o.body.matchAll(KNOWN)].map(m => m[1] as string) })
  }
  return out
}

const failedRead = (why: string): { source: Source; read: null } => ({ source: { ok: false, at: null, error: why }, read: null })

// readFlakes: one read, the flakes then (when some test has enough of them) the bugs.
export async function readFlakes(ctx: SourceCtx, min: number): Promise<{ source: Source; read: FlakesRead | null }> {
  const { rt, now } = ctx
  const since = new Date(now - rt.config.flakeWindowDays * DAY).toISOString()
  let flakes: Flake[]
  try {
    const r = await ctx.run(['dev-query', '--factory', '--csv', '-v', `repo=${rt.repo}`, '-v', `since=${since}`], FLAKES_SQL)
    if (r.exitCode === 77) return { source: { ok: true, at: now }, read: { flakes: [], bugs: [] } }
    if (r.exitCode !== 0) return failedRead(`the flakes read failed: exit ${r.exitCode}`)
    flakes = flakesFromRows(parseCsv(r.stdout))
  } catch (err) {
    return failedRead(`the flakes read failed: ${String(err).slice(0, 200)}`)
  }
  const per = new Map<string, number>()
  for (const f of flakes) per.set(f.hash, (per.get(f.hash) ?? 0) + 1)
  if (![...per.values()].some(n => n >= min)) return { source: { ok: true, at: now }, read: { flakes, bugs: [] } }
  try {
    const r = await ctx.run(['callum-flow-issue-read', '--json', '--list', '--label', FLAKY_LABEL, '--state', 'open'])
    const bugs = r.exitCode === 0 ? bugsFromJson(r.stdout) : null
    if (bugs === null) return failedRead(`the flake bugs read failed: exit ${r.exitCode}`)
    return { source: { ok: true, at: now }, read: { flakes, bugs } }
  } catch (err) {
    return failedRead(`the flake bugs read failed: ${String(err).slice(0, 200)}`)
  }
}

// readFlakesCached: the cadence: act mode only, every githubEveryMs, at once after an action of F1's
// own ended since the last read, and none during a GitHub backoff or after a rate limit.
export async function readFlakesCached(ctx: SourceCtx, cache: FlakesCache, blocked: boolean): Promise<FlakesCache> {
  const { now, rt } = ctx
  if (rt.mode !== 'act') return { at: null, read: null, source: { ok: true, at: now } }
  const own = Math.max(-Infinity, ...ctx.state.ledger.flatMap(e => (e.kind === 'flake-bug' || e.key.startsWith('flake-bug/') ? [e.endedAt ?? e.startedAt] : [])))
  const due = cache.at === null || now - cache.at >= rt.config.githubEveryMs || own >= cache.at
  if (!due || blocked) return cache.source === null ? { ...cache, source: { ok: true, at: now } } : cache
  const r = await readFlakes(ctx, rt.config.flakeBugMin)
  return { at: now, read: r.read, source: r.source }
}

files.hooks/v2/sources-records.ts:
// The record rebuild's read (docs/factory-loop/v2/SPEC.md 3.3) and its source switch `eventsSource`:
// `old` rebuilds from factory.events (REBUILD_SQL), `new` from factory.event_store (NEW_REBUILD_SQL),
// and `shadow` (opt-in; `new` is the default since #978) reads both, compares the two rebuilds per issue and field by field, and
// leaves the records to the old read. The compare is written as a `shadow_read` event (reader
// `loop-records`) and told to the owner by rules-shadow.ts. A failing new read never fails a pass
// under `shadow`; under `new` it fails the rebuild, and no row is ever skipped.
import { eventsFromRows } from '../derive'
import type { FactoryEvent } from '../derive'
import { parseCsv } from '../parse'
import type { ShadowReadData } from './events'
import { NEW_REBUILD_SQL, REBUILD_DAYS, REBUILD_SQL, recordsFromEvents, recordsFromNewRows } from './record'
import type { SourceCtx } from './observe'
import { sameValue } from './same-value'
import type { IssueRecord } from './types'

export const SHADOW_READER = 'loop-records'
// the compare is made once per load, then at most this often
export const SHADOW_EVERY_MS = 60 * 60_000
// both sides are cut this far back so push lag is not counted as a difference
export const SETTLE_MS = 600_000
const MAX_KEYS = 50

// One compare: the data of its `shadow_read` event, and the first difference of each differing issue
// (ordered by issue), for the owner's tell.
export type RecordsShadow = { at: number; data: ShadowReadData; diffs: readonly { issue: number; text: string }[] }

// What survives between passes (V2Cache): the last rebuild and the last compare.
export type RecordsCache = { rebuilt: { at: number; records: IssueRecord[] } | null; shadow: RecordsShadow | null }

// --- the compare (pure) -----------------------------------------------------------------------------


// diffRecords: the issues whose records differ, each with its first differing field as
// `#n field: old X, new Y` (a record only one side holds is `#n record: old present, new absent`).
export function diffRecords(oldRecords: readonly IssueRecord[], newRecords: readonly IssueRecord[]): { issue: number; text: string }[] {
  const o = new Map(oldRecords.map(r => [r.issue, r]))
  const n = new Map(newRecords.map(r => [r.issue, r]))
  const out: { issue: number; text: string }[] = []
  for (const issue of [...new Set([...o.keys(), ...n.keys()])].sort((a, b) => a - b)) {
    const a = o.get(issue)
    const b = n.get(issue)
    if (a === undefined || b === undefined) {
      out.push({ issue, text: `#${issue} record: old ${a === undefined ? 'absent' : 'present'}, new ${b === undefined ? 'absent' : 'present'}` })
      continue
    }
    const field = (Object.keys(a) as (keyof IssueRecord)[]).find(k => !sameValue(a[k], b[k]))
    if (field !== undefined) out.push({ issue, text: `#${issue} ${field}: old ${JSON.stringify(a[field])}, new ${JSON.stringify(b[field])}` })
  }
  return out
}

// compareRebuilds: the two rebuilds of the same keys, once on everything read (live) and once with
// both sides cut SETTLE_MS back from now (the differences that count). Throws when the new rows
// are refused, which the caller reads as a failed new read.
export function compareRebuilds(events: readonly FactoryEvent[], rows: readonly Record<string, string>[], device: string, now: number, at: number): RecordsShadow {
  const cut = now - SETTLE_MS
  const live = diffRecords(recordsFromEvents(events, device), recordsFromNewRows(rows))
  const settled = diffRecords(
    recordsFromEvents(events.filter(e => e.ts <= cut), device),
    recordsFromNewRows(rows.filter(r => Date.parse(r.ts ?? '') <= cut)),
  )
  const issues = new Set([...recordsFromEvents(events, device), ...recordsFromNewRows(rows)].map(r => r.issue))
  const data: ShadowReadData = {
    reader: SHADOW_READER,
    tool: 'factory-loop',
    compared: issues.size,
    differences: settled.length,
    live_differences: live.length,
    diff_keys: settled.slice(0, MAX_KEYS).map(d => String(d.issue)),
    old_ok: true,
    new_ok: true,
    settle_seconds: SETTLE_MS / 1000,
    detail: settled[0] === undefined ? null : settled[0].text.slice(0, 500),
  }
  return { at, data, diffs: settled }
}

// failedShadow: the data of a compare that could not be made because a side failed to read (shared
// with sources-facts.ts); the reader names whose compare it is.
export function failedShadow(reader: string, oldError: string | null, newError: string | null): ShadowReadData {
  const detail = [oldError === null ? null : `old: ${oldError}`, newError === null ? null : `new: ${newError}`].filter(x => x !== null).join('; ')
  return {
    reader,
    tool: 'factory-loop',
    compared: 0,
    differences: 0,
    live_differences: 0,
    diff_keys: [],
    old_ok: oldError === null,
    new_ok: newError === null,
    settle_seconds: SETTLE_MS / 1000,
    detail: detail.slice(0, 500),
  }
}

// --- the reads --------------------------------------------------------------------------------------

export type Ctx = Pick<SourceCtx, 'now' | 'rt' | 'run'>
export type Read<T> = { ok: true; value: T } | { ok: false; error: string }

const vars = (ctx: Ctx): string[] => ['-v', `repo=${ctx.rt.repo}`, '-v', `device=${ctx.rt.device}`, '-v', `at=${new Date(ctx.now).toISOString()}`, '-v', `days=${REBUILD_DAYS}`]

async function readOld(ctx: Ctx): Promise<Read<FactoryEvent[]>> {
  if (REBUILD_SQL === null) return { ok: false, error: 'the rebuild has no query' }
  try {
    const r = await ctx.run(['dev-query', '--csv', ...vars(ctx)], REBUILD_SQL)
    if (r.exitCode !== 0) return { ok: false, error: `the rebuild's read failed: exit ${r.exitCode}` }
    return { ok: true, value: eventsFromRows(parseCsv(r.stdout)) }
  } catch (err) {
    return { ok: false, error: `the rebuild's read failed: ${String(err).slice(0, 200)}` }
  }
}

// readNew: the rows of the new store and their records; a missing factory URL (dev-query exit 77 or
// 78) or any refused row fails the read.
async function readNew(ctx: Ctx): Promise<Read<{ rows: Record<string, string>[]; records: IssueRecord[] }>> {
  try {
    const r = await ctx.run(['dev-query', '--factory', '--csv', ...vars(ctx)], NEW_REBUILD_SQL)
    if (r.exitCode !== 0) return { ok: false, error: `the rebuild's read failed (source new): exit ${r.exitCode}` }
    const rows = parseCsv(r.stdout)
    return { ok: true, value: { rows, records: recordsFromNewRows(rows) } }
  } catch (err) {
    const text = err instanceof Error ? err.message : String(err)
    return { ok: false, error: `the rebuild's read failed: ${text.includes('source new') ? text : `source new: ${text}`}`.slice(0, 300) }
  }
}

// readRecords: the pass's rebuild and compare, into the cache. storeEmpty: the store holds no records,
// so a rebuild is wanted (on the githubEveryMs cadence). Returns the error of a rebuild's read that
// failed (the store source's), else null. Under `shadow` the compare runs whether or not the store
// holds records, on its first pass of a load and then at most hourly; its failure is never returned.
export async function readRecords(ctx: Ctx, cache: RecordsCache, storeEmpty: boolean): Promise<string | null> {
  const { now, rt } = ctx
  const source = rt.config.eventsSource
  const rebuildDue = storeEmpty && (cache.rebuilt === null || now - cache.rebuilt.at >= rt.config.githubEveryMs)
  const shadowDue = source === 'shadow' && (cache.shadow === null || now - cache.shadow.at >= SHADOW_EVERY_MS)
  if (!rebuildDue && !shadowDue) return null
  const old = shadowDue || (rebuildDue && source !== 'new') ? await readOld(ctx) : null
  const fresh = shadowDue || (rebuildDue && source === 'new') ? await readNew(ctx) : null
  let error: string | null = null
  if (rebuildDue) {
    if (source === 'new') {
      if (fresh?.ok === true) cache.rebuilt = { at: now, records: fresh.value.records }
      else error = fresh?.ok === false ? fresh.error : null
    } else if (old?.ok === true) {
      cache.rebuilt = { at: now, records: recordsFromEvents(old.value, rt.device) }
    } else {
      error = old?.ok === false ? old.error : null
    }
  }
  if (shadowDue && old !== null && fresh !== null) {
    if (old.ok && fresh.ok) {
      try {
        cache.shadow = compareRebuilds(old.value, fresh.value.rows, rt.device, now, now)
      } catch (err) {
        cache.shadow = { at: now, data: failedShadow(SHADOW_READER, null, String(err).slice(0, 200)), diffs: [] }
      }
    } else {
      cache.shadow = { at: now, data: failedShadow(SHADOW_READER, old.ok ? null : old.error, fresh.ok ? null : fresh.error), diffs: [] }
    }
  }
  return error
}

files.hooks/v2/wind-down.ts:
// Wind-down (docs/factory-loop/v2/SPEC.md 10.11), pure: the owner (or the stop script of #842) asks
// the loop to finish what runs and start nothing, by writing `<loop dir>/wind-down.request`. While a
// request stands (and config windDownMinutes is above 0), one guard in the planner drops every
// action that starts work, before admission, and the loop writes `wind-down.status.json` each pass
// so the stopper can see when nothing runs. A request the stop never followed is removed after the
// cap plus a margin, and the loop plans normally again. This module decides and reads no clock;
// wind-down-files.ts reads and writes the files (observe.ts and register.ts call it).
import { skip, wake, want } from '../foundation'
import type { PlanCtx } from '../foundation'
import type { Action, LedgerEntry, Ms, State } from '../types'
import type { V2Ctx } from './types'

export const WIND_DOWN_REQUEST = 'wind-down.request'
export const WIND_DOWN_STATUS = 'wind-down.status.json'
export const WIND_DOWN_STOP_NOW = 'wind-down.stop-now'

export const windDownPaths = (loopDir: string) => ({
  request: `${loopDir}/${WIND_DOWN_REQUEST}`,
  status: `${loopDir}/${WIND_DOWN_STATUS}`,
  stopNow: `${loopDir}/${WIND_DOWN_STOP_NOW}`,
})

// A request older than the cap plus this, with the loop still running, is one the stop never followed.
export const WIND_DOWN_MARGIN_MS = 5 * 60_000

// What observe read: the request (null: none), whether the stop-now file exists, and the status
// file the loop wrote last pass (for started_at).
export type WindDownRead = {
  // iso: requestedAt as the writer's text, for the owner's tell (the planner reads no clock)
  // remembered: the session's own memory of the request it wrote (withRemembered), the file being gone
  request: { requestedAt: Ms; iso: string; trigger: string | null; problem: string | null; remembered?: true } | null
  stopNow: boolean
  previous: { requestedAt: Ms; startedAt: Ms } | null
}

export type WindDown =
  | { mode: 'off' }
  | { mode: 'active'; requestedAt: Ms; startedAt: Ms; capMs: Ms }
  | { mode: 'stale'; requestedAt: Ms; capMs: Ms }

// windDownOf: the mode this pass plans in.
export function windDownOf(state: State, config: { windDownMinutes: number }): WindDown {
  const read = state.v2?.windDown
  if (read === undefined || read.request === null || config.windDownMinutes <= 0) return { mode: 'off' }
  const { requestedAt } = read.request
  const capMs = config.windDownMinutes * 60_000
  if (state.now - requestedAt > capMs + WIND_DOWN_MARGIN_MS) return { mode: 'stale', requestedAt, capMs }
  const startedAt = read.previous !== null && read.previous.requestedAt === requestedAt ? read.previous.startedAt : state.now
  return { mode: 'active', requestedAt, startedAt, capMs }
}

// The closed drop list: every kind that starts work.
function starts(a: Action): boolean {
  switch (a.kind) {
    case 'claim':
    case 'agent-step':
    case 'queue-update':
    case 'queue-merge':
    case 'ci-rerun':
    case 'judge':
    case 'task':
      return true
    case 'slot':
      return a.op === 'lease'
    default:
      return false
  }
}

// windDownGuard: in wind-down, drops every start from the plan, each with a skip line. What finishes
// work (transition, pr, label, comment, event, split, slot frees and kills, stop-agent, tell,
// heartbeat, sweep) stays.
export function windDownGuard(ctx: PlanCtx, wd: WindDown): void {
  if (wd.mode !== 'active') return
  const kept: Action[] = []
  for (const a of ctx.out) {
    if (starts(a)) skip(ctx, a.rule, a.issue, `wind-down: no new start (${a.kind})`)
    else kept.push(a)
  }
  ctx.out.length = 0
  ctx.out.push(...kept)
}

// windDownTells: a stale request is told once, by its requested_at.
export function windDownTells(ctx: V2Ctx, wd: WindDown): void {
  if (wd.mode !== 'stale') return
  const at = ctx.v2.windDown?.request?.iso ?? String(wd.requestedAt)
  const minutes = wd.capMs / 60_000
  want(
    ctx,
    wake('tell', 'wind-down-stale', `tell:wind-down-stale:${wd.requestedAt}`, 'O2', null, { requested_at: at, cap_minutes: minutes }, [
      `A wind-down was requested at ${at} and the stop did not follow within ${minutes} minutes plus ${WIND_DOWN_MARGIN_MS / 60_000}. The loop removed the request and plans normally again.`,
    ]),
  )
}

// windDownTitle: the title's words: `winding down <m>m`, `<n> running`.
export function windDownTitle(state: State, wd: WindDown): string[] {
  if (wd.mode !== 'active') return []
  const n = state.ledger.filter(e => e.status === 'running' && e.kind === 'agent-step').length
  return [`winding down ${Math.floor((state.now - wd.startedAt) / 60_000)}m`, `${n} running`]
}

files.hooks/act-cli.ts:
// The executors that spend no tokens (v2 SPEC 13.6.1): the CLI kinds, plus stop-agent and title,
// which call the engine instead of a command. Each CLI kind turns its action into the steps of
// its catalogue row, runs them in order through ctx.cmd and ctx.event, stops at the first
// failure and says what happened. They decide nothing (plan did). The steps and the reading of
// their output are pure functions below, so tests, the replay harness and the argv safety test
// read them without the engine.
import { detailOf, rateLimited } from './exec'
import type { EventFields, Exec, ExecCtx, Executor, RunInit, RunResult } from './exec'
import { splitNote } from './v2/events'
import type { Action, ActionKind, LedgerEntry } from './types'
import { WIND_DOWN_WRITE_SCRIPT } from './v2/wind-down-files'
import { windDownPaths } from './v2/wind-down'

const SEC = 1000
const SUMMARY_MAX = 200

// The kinds this module runs as commands.
export type CliKind =
  | 'heartbeat'
  | 'sweep'
  | 'claim'
  | 'close-issue'
  | 'delete-branch'
  | 'release-parent'
  | 'milestone-later'
  | 'restart-self'

// Each command's timeout, by its action's kind (v2 SPEC 13.6.1). A step of a multi-step kind gets
// the kind's timeout. stop-agent (30 s) and title (10 s) are engine calls, timed by ActIo.
export const CLI_TIMEOUT_MS: Record<CliKind, number> = {
  heartbeat: 120 * SEC,
  sweep: 300 * SEC,
  claim: 120 * SEC,
  'close-issue': 60 * SEC,
  'delete-branch': 60 * SEC,
  'release-parent': 60 * SEC,
  'milestone-later': 60 * SEC,
  'restart-self': 600 * SEC,
}

// The exit recorded for a command that never exited: it could not start, or it outlived its
// timeout and $.process.run ended it. Either counts as failed (v2 SPEC 13.10 item 1).
export const NO_EXIT = -1

// One step of an action: a command, or a factory event through ctx.event (v2 SPEC 13.7.4). `ok`
// lists the exits that are an answer, not a failure (default: 0 only).
export type Step =
  | { argv: string[]; timeoutMs: number; stdin?: string; ok?: number[] }
  | { event: string; fields: EventFields }

// stepsOf: the steps one action runs, in order (v2 SPEC 13.6.1), or why it is refused: a loop bug,
// never retried. Every command runs from the main checkout. gh gets --repo, so a write can
// only reach the configured repo (v2 SPEC 13.11.5).
export function stepsOf(action: Action, repo: string, inDevLabel: string, loopDir: string): Step[] | string {
  const n = action.issue === null ? null : String(action.issue)
  const noIssue = `${action.kind} names no issue`
  const unlabel = (issue: string): Step => ({
    argv: ['gh', 'issue', 'edit', issue, '--repo', repo, '--remove-label', inDevLabel],
    timeoutMs: CLI_TIMEOUT_MS['release-parent'],
  })
  switch (action.kind) {
    case 'heartbeat':
      return [{ argv: ['callum-flow-claim', '--heartbeat'], timeoutMs: CLI_TIMEOUT_MS.heartbeat }]
    case 'sweep':
      return [{ argv: ['callum-flow-sweep'], timeoutMs: CLI_TIMEOUT_MS.sweep }]
    case 'claim':
      // exit 3: another device's live claim won, an answer (v2 SPEC 13.10 item 5)
      return n === null ? noIssue : [{ argv: ['callum-flow-claim', n], timeoutMs: CLI_TIMEOUT_MS.claim, ok: [0, 3] }]
    case 'close-issue':
      // a done close (logClosed) also logs the `closed` event, the way the tracker's close does
      return n === null
        ? noIssue
        : [
            { argv: ['gh', 'issue', 'close', n, '--repo', repo, '--reason', 'completed'], timeoutMs: CLI_TIMEOUT_MS['close-issue'] },
            ...(action.logClosed === true ? [{ event: 'closed', fields: { issue: action.issue, note: 'completed' } }] : []),
          ]
    case 'delete-branch':
      // leased on the head plan read: a branch that moved since is kept (exit 1, "stale info"), which
      // is an answer, not a failure
      return [{ argv: ['git', 'push', `--force-with-lease=refs/heads/${action.branch}:${action.sha}`, 'origin', `:refs/heads/${action.branch}`], timeoutMs: CLI_TIMEOUT_MS['delete-branch'], ok: [0, 1] }]
    case 'milestone-later':
      return n === null ? noIssue : [{ argv: ['callum-flow-milestone', 'plan', n, 'later'], timeoutMs: CLI_TIMEOUT_MS['milestone-later'] }]
    case 'release-parent':
      // the parent is now a tracker. The label comes off first, so the event records a release
      // that happened, and a retry after a failed event repeats only the label edit.
      return n === null
        ? noIssue
        : [unlabel(n), { event: 'abandoned', fields: { issue: action.issue, note: splitNote(action.created, action.reasons ?? null, action.childWhys ?? null) } }]
    case 'restart-self':
      // only once the drain for an update is complete (rule H4, D-15), or v2's restart after a
      // capped wind-down (rule R2, v2 SPEC 14.1): R2 with wind-down on first writes the request,
      // in the form the status file's times take (wind-down.sh compares them as text)
      if (action.rule !== 'H4' && action.rule !== 'R2') return `restart-self comes only from rule H4 or R2, not ${action.rule}`
      return [
        ...(action.rule === 'R2' && action.windDownAt != null
          ? [{
              argv: ['sh', '-c', WIND_DOWN_WRITE_SCRIPT, 'wind-down-request', windDownPaths(loopDir).request],
              timeoutMs: 10_000,
              stdin: `${JSON.stringify({ requested_at: new Date(action.windDownAt).toISOString(), trigger: 'restart-self' })}\n`,
            }]
          : []),
        { argv: ['dev-restart-self'], timeoutMs: CLI_TIMEOUT_MS['restart-self'] },
      ]
    default:
      return `${action.kind} runs no command`
  }
}

// Exit 2 is a usage error, a loop bug never retried (v2 SPEC 13.10 item 1), for the image's own CLIs
// (callum-flow-*, dev-restart-self). gh exits 2 when a command is cancelled and 1 on bad
// usage; treehouse exits 1 on bad usage too.
export function usageError(argv: readonly string[], exit: number): boolean {
  return exit === 2 && argv[0] !== 'gh' && argv[0] !== 'treehouse'
}

// commandFailure: a command that exited with a failure: its exit and detailOf() in the
// outcome (v2 SPEC 13.10 item 1), and a GitHub rate limit flagged for the driver's backoff (v2 SPEC 13.10 item 2).
export function commandFailure(argv: readonly string[], r: RunResult): Exec {
  const line = lastLine(r.stderr) || lastLine(r.stdout)
  const exec: Extract<Exec, { status: 'failed' }> = {
    status: 'failed',
    outcome: { kind: 'cli', exit: r.exitCode, detail: detailOf(r) },
    summary: clip(`${label(argv)}: exit ${r.exitCode}${line === '' ? '' : `: ${line}`}`),
  }
  if (usageError(argv, r.exitCode)) exec.noRetry = true
  if (rateLimited(r.stderr)) exec.rateLimited = true
  return exec
}

// eventFailure: ctx.event threw. callum-flow-event exits non-zero only on a usage error (exit
// 2; a failed write still exits 0), so an error carrying exitCode 2 is never retried.
export function eventFailure(state: string, err: unknown): Exec {
  const code = typeof err === 'object' && err !== null ? (err as { exitCode?: unknown }).exitCode : undefined
  const exit = typeof code === 'number' ? code : NO_EXIT
  const exec: Extract<Exec, { status: 'failed' }> = {
    status: 'failed',
    outcome: { kind: 'cli', exit, detail: message(err).slice(0, 2000) },
    summary: clip(`event ${state}: ${message(err)}`),
  }
  if (exit === 2) exec.noRetry = true
  return exec
}

// finish: what the steps' output says once every step passed (v2 SPEC 13.6.1 "Outcome recorded").
export function finish(action: Action, results: RunResult[]): Exec {
  const last = results[results.length - 1]
  const out = (r: RunResult | undefined) => (r === undefined ? '' : firstLine(r.stdout) || lastLine(r.stderr))
  const ok = (summary: string): Exec => ({ status: 'done', outcome: { kind: 'cli', exit: 0 }, summary: clip(summary) })
  switch (action.kind) {
    case 'claim':
      return last?.exitCode === 3
        ? { status: 'done', outcome: { kind: 'claim', result: 'lost' }, summary: clip(`lost #${action.issue}: ${lastLine(last.stderr)}`) }
        : { status: 'done', outcome: { kind: 'claim', result: 'claimed' }, summary: `claimed #${action.issue}` }
    case 'heartbeat':
      return ok('leases renewed')
    case 'sweep':
      return ok('swept')
    case 'close-issue':
      return ok(`closed #${action.issue}`)
    case 'delete-branch': {
      if (last?.exitCode === 0) return { status: 'done', outcome: { kind: 'cli', exit: 0, detail: 'deleted' }, summary: clip(`deleted ${action.branch}`) }
      const text = `${last?.stderr ?? ''}\n${last?.stdout ?? ''}`
      if (/stale info/i.test(text)) return { status: 'done', outcome: { kind: 'cli', exit: 0, detail: 'kept: moved' }, summary: clip(`kept ${action.branch}: it moved since it was read`) }
      return last === undefined ? { status: 'failed', summary: 'delete-branch ran no command' } : commandFailure(['git', 'push'], last)
    }
    case 'release-parent':
      return ok(`released #${action.issue}, split into ${action.created.join(',')}`)
    case 'milestone-later':
      // the CLI prints what moved or the line it set; a repo not opted in is a no-op note
      return ok(out(last) || action.kind)
    case 'restart-self':
      // the session ends; the loop resumes on load (v2 SPEC 13.7.5)
      return ok('restart requested')
    default:
      return { status: 'failed', summary: `${action.kind} runs no command`, noRetry: true }
  }
}

// runSteps: the steps in order, stopping at the first failure.
async function runSteps(ctx: ExecCtx, steps: Step[]): Promise<{ results: RunResult[] } | { failed: Exec }> {
  const results: RunResult[] = []
  for (const step of steps) {
    if ('event' in step) {
      try {
        await ctx.event(step.event, step.fields)
      } catch (err) {
        return { failed: eventFailure(step.event, err) }
      }
      continue
    }
    const init: RunInit = { timeoutMs: step.timeoutMs }
    if (step.stdin !== undefined) init.stdin = step.stdin
    let r: RunResult
    try {
      r = await ctx.cmd(step.argv, init)
    } catch (err) {
      const failed: Exec = {
        status: 'failed',
        outcome: { kind: 'cli', exit: NO_EXIT, detail: message(err).slice(0, 2000) },
        summary: clip(`${label(step.argv)}: ${message(err)}`),
      }
      return { failed }
    }
    if (!(step.ok ?? [0]).includes(r.exitCode)) return { failed: commandFailure(step.argv, r) }
    results.push(r)
  }
  return { results }
}

function refused(why: string): Exec {
  return { status: 'failed', summary: clip(`refused: ${why}`), noRetry: true }
}

function command(kind: CliKind): Executor {
  return async (ctx, action) => {
    if (action.kind !== kind) return refused(`the ${kind} executor got a ${action.kind} action`)
    const steps = stepsOf(action, ctx.rt.repo, ctx.rt.config.inDevLabel, ctx.rt.loopDir)
    if (typeof steps === 'string') return refused(steps)
    const ran = await runSteps(ctx, steps)
    return 'failed' in ran ? ran.failed : finish(action, ran.results)
  }
}

// restartSelf: the restart's steps; when dev-restart-self itself fails after the request was
// written, the request comes off (best effort), so a restart that never came does not wind the
// loop down.
const restartSelf: Executor = async (ctx, action) => {
  if (action.kind !== 'restart-self') return refused(`the restart-self executor got a ${action.kind} action`)
  const steps = stepsOf(action, ctx.rt.repo, ctx.rt.config.inDevLabel, ctx.rt.loopDir)
  if (typeof steps === 'string') return refused(steps)
  // the request write (if any) is every step but the last
  const written = steps.slice(0, -1)
  const wrote = await runSteps(ctx, written)
  if ('failed' in wrote) return wrote.failed
  const ran = await runSteps(ctx, steps.slice(-1))
  if (!('failed' in ran)) return finish(action, [...wrote.results, ...ran.results])
  if (written.length > 0) await ctx.cmd(['rm', '-f', '--', windDownPaths(ctx.rt.loopDir).request], { timeoutMs: 10_000 }).catch(() => undefined)
  return ran.failed
}

// ownAgent: the ledger holds this agent id on an entry still running, so the loop spawned it and
// still waits on it. An agent the loop did not spawn is never stopped (v2 SPEC 13.6.1).
export function ownAgent(ledger: readonly LedgerEntry[], agentId: string): boolean {
  return ledger.some(e => e.agentId === agentId && e.status === 'running')
}

// stop-agent: TaskStop through ActIo, for one of the loop's own agents (rules A1, A2). A stop
// that is not supported is recorded as failed with the reason (v2 SPEC 13.13). TaskStop is expected to
// end the background shells the agent left running too, which is what keeps an agent at work
// past its answer (#587): Claude Code (2.1.296) kills an agent's running shell tasks as
// its loop exits. A process that detached from its shell outlives it.
const stopAgent: Executor = async (ctx, action) => {
  if (action.kind !== 'stop-agent') return refused(`the stop-agent executor got a ${action.kind} action`)
  if (!ownAgent(ctx.state.ledger, action.agentId)) return refused(`agent ${action.agentId} is not a running agent of the loop`)
  let r: { stopped: boolean; error?: string }
  try {
    r = await ctx.io.stopAgent(action.agentId)
  } catch (err) {
    r = { stopped: false, error: message(err) }
  }
  if (r.stopped) return { status: 'done', summary: `stopped ${action.agentId} (${action.reason})` }
  return { status: 'failed', summary: clip(`not stopped ${action.agentId}: ${r.error ?? 'no reason given'}`) }
}

// title: /rename through ActIo (rule O1, v2 SPEC 13.9.1).
const title: Executor = async (ctx, action) => {
  if (action.kind !== 'title') return refused(`the title executor got a ${action.kind} action`)
  try {
    await ctx.io.rename(action.text)
  } catch (err) {
    return { status: 'failed', summary: clip(`rename failed: ${message(err)}`) }
  }
  return { status: 'done', summary: clip(action.text) }
}

export const cliExecutors: Partial<Record<ActionKind, Executor>> = {
  heartbeat: command('heartbeat'),
  sweep: command('sweep'),
  claim: command('claim'),
  'close-issue': command('close-issue'),
  'delete-branch': command('delete-branch'),
  'release-parent': command('release-parent'),
  'milestone-later': command('milestone-later'),
  'restart-self': restartSelf,
  'stop-agent': stopAgent,
  title,
}

// --- small text helpers ---------------------------------------------------------------------

// label: a command's name for a summary: gh with its noun and verb, others with one argument.
function label(argv: readonly string[]): string {
  return argv.slice(0, argv[0] === 'gh' ? 3 : 2).join(' ')
}

function firstLine(text: string): string {
  return text.split('\n').map(l => l.trim()).find(l => l !== '') ?? ''
}

function lastLine(text: string): string {
  return text.split('\n').map(l => l.trim()).filter(l => l !== '').pop() ?? ''
}

function clip(text: string): string {
  return text.length > SUMMARY_MAX ? `${text.slice(0, SUMMARY_MAX - 3)}...` : text
}

function message(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

