// The factory report (#712, epic #684): a pure view of the v2 records as two markdown tables, the
// issues in flight and the last merges, and a digest that changes when the picture does and not
// when only time passes. Nothing here reads a clock, a store or GitHub; delivery comes later. It
// lives in hooks/, not hooks/v2/, so it stays out of the planner's import closure.
import type { Ms } from './types'
import { lifeAt } from './v2/keys'
import { SLOT_STATES } from './v2/types'
import type { IssueRecord, IssueState } from './v2/types'

export const MERGED_SHOWN = 5
export const WHAT_MAX = 40

const SEC = 1000
const MIN = 60 * SEC
const HOUR = 60 * MIN
const DAY = 24 * HOUR

// duration: Xs under a minute, Xm under an hour, XhYm under a day, XdYh from a day up.
export function duration(ms: Ms): string {
  const t = Math.max(0, ms)
  if (t < MIN) return `${Math.floor(t / SEC)}s`
  if (t < HOUR) return `${Math.floor(t / MIN)}m`
  if (t < DAY) return `${Math.floor(t / HOUR)}h${Math.floor((t % HOUR) / MIN)}m`
  return `${Math.floor(t / DAY)}d${Math.floor((t % DAY) / HOUR)}h`
}

// The state in words (the one table); a detail, where one helps, comes from stageOf.
const STAGE_WORDS: Readonly<Record<IssueState, string>> = {
  queued: 'queued',
  designing: 'designing',
  building: 'building',
  reviewing: 'reviewing',
  fixing: 'fixing',
  'merge-queue': 'merge queue',
  parked: 'parked',
  waiting: 'waiting',
  closed: 'closed',
}

export function stageOf(r: IssueRecord): string {
  const word = STAGE_WORDS[r.state]
  if (r.state === 'reviewing' && r.approvedPatch !== null) return `${word} (approved, heading to merge)`
  if (r.state === 'parked' && r.question) return `${word} (owner question)`
  return word
}

// whatOf: a title shortened: the prefix up to the first ": " dropped, the rest cut at a word
// boundary to at most WHAT_MAX characters, "|" escaped. No title gives an empty string.
export function whatOf(title: string | undefined): string {
  if (!title) return ''
  const i = title.indexOf(': ')
  let s = (i >= 0 ? title.slice(i + 2) : title).trim().replace(/\s+/g, ' ')
  if (s.length > WHAT_MAX) {
    const cut = s.slice(0, WHAT_MAX + 1)
    const space = cut.lastIndexOf(' ')
    s = space > 0 ? cut.slice(0, space) : cut.slice(0, WHAT_MAX)
  }
  return s.trim().replace(/\|/g, '\\|')
}

const isMerged = (r: IssueRecord) => r.state === 'closed' && (r.why === 'merged' || r.why === 'merged-by-hand')
const isInFlight = (r: IssueRecord) => SLOT_STATES.includes(r.state) || r.state === 'parked' || r.state === 'waiting'

const claimAt = (r: IssueRecord): Ms | null => lifeAt(r.life)

function table(head: string[], rows: string[][]): string {
  return [`| ${head.join(' | ')} |`, `|${head.map(() => ' --- ').join('|')}|`, ...rows.map(r => `| ${r.join(' | ')} |`)].join('\n')
}

export type Report = { text: string | null; digest: string }

export function reportOf(records: readonly IssueRecord[], titles: Readonly<Record<number, string>> | ReadonlyMap<number, string>, now: Ms, repo: string): Report {
  const title = (n: number) => (titles instanceof Map ? titles.get(n) : (titles as Readonly<Record<number, string>>)[n])
  const link = (n: number) => `[#${n}](https://github.com/${repo}/issues/${n})`

  const flight = records.filter(isInFlight).sort((a, b) => {
    const x = claimAt(a)
    const y = claimAt(b)
    if (x === null || y === null) return x === y ? a.issue - b.issue : x === null ? 1 : -1
    return x - y || a.issue - b.issue
  })
  const merged = records.filter(isMerged).sort((a, b) => b.since - a.since || a.issue - b.issue)

  const digest = [
    flight.map(r => `${r.issue}:${r.life}:${r.state}:${r.seq}`).join(','),
    merged.map(r => `${r.issue}:${r.life}`).sort().join(','),
  ].join('|')
  if (flight.length === 0 && merged.length === 0) return { text: null, digest }

  const flightRows = flight.map(r => {
    const at = claimAt(r)
    return [link(r.issue), whatOf(title(r.issue)), stageOf(r), duration(now - r.since), at === null ? '' : duration(now - at)]
  })
  const mergedRows = merged.slice(0, MERGED_SHOWN).map(r => {
    const at = claimAt(r)
    return [link(r.issue), whatOf(title(r.issue)), at === null ? '' : duration(r.since - at), String(r.fixes)]
  })
  const text = [
    `### In flight (${flight.length})`,
    flightRows.length > 0 ? table(['Issue', 'What', 'Stage', 'In stage', 'Since claim'], flightRows) : 'Nothing in flight.',
    '',
    '### Merged',
    mergedRows.length > 0 ? table(['Issue', 'What', 'Claim to merge', 'Fix rounds'], mergedRows) : 'Nothing merged yet.',
  ].join('\n')
  return { text, digest }
}

// titleBook: the title book after a pass: the known titles, with every title the pass's issue
// reads carry, and only for issues that have a v2 record. It makes no GitHub call.
export function titleBook(prev: unknown, reads: ReadonlyMap<number, { facts: { title: string } | null }>, records: readonly Pick<IssueRecord, 'issue'>[]): Record<number, string> {
  const known: Record<number, string> = {}
  if (prev !== null && typeof prev === 'object' && !Array.isArray(prev)) {
    for (const [k, v] of Object.entries(prev)) if (typeof v === 'string' && /^\d+$/.test(k)) known[Number(k)] = v
  }
  for (const [n, g] of reads ?? []) if (g.facts && g.facts.title) known[n] = g.facts.title
  const out: Record<number, string> = {}
  for (const r of records) if (known[r.issue] !== undefined) out[r.issue] = known[r.issue]
  return out
}

// keepTitles: the title book in the store, written only when it changed. A store that cannot be
// read or written is a problem line, never a throw.
export async function keepTitles(
  io: { get: (key: string) => Promise<unknown>; set: (key: string, value: unknown) => Promise<unknown> },
  key: string,
  reads: ReadonlyMap<number, { facts: { title: string } | null }>,
  records: readonly Pick<IssueRecord, 'issue'>[],
  problems: string[],
): Promise<void> {
  try {
    const prev = await io.get(key)
    const next = titleBook(prev, reads, records)
    if (JSON.stringify(next) !== JSON.stringify(prev)) await io.set(key, next)
  } catch (err) {
    problems.push(`store: ${key} not saved: ${String(err instanceof Error ? err.message : err).slice(0, 200)}`)
  }
}

files.hooks/v2/rules-state.ts:
// The record's rules (docs/factory-loop/v2/SPEC.md 3, 4, 5, 11, 14.1): H1 renews and re-claims
// (rules-claim.ts); for each record, S3 plans its seq's entry actions (rules-entry.ts), then the
// one event that changes it this pass, the first present in 4.1's order (pr-merged, issue-closed,
// claim-lost, drop, pr-closed, the step's result, unpark), through the table (table.ts rowFor): a
// changing row is one `transition` action (S3 for a step result, S4 the unknown path, S5 triage,
// S6 the owner's and GitHub's events), and the rows that change nothing (E6's tell, E7's log line)
// run beside it and never stop it; S2 starts the record's step through its plan when nothing else
// takes the record (rules-agent.ts, and each unit's own step plans); then S0 and S1 make records
// and claim new work (rules-claim.ts). And O1's counts, which the title and the decision log show.
//
// - A running step past its timeout is unknown (timeout), in every state; a waiting record's
//   timeout is its tell period (E6); a held step has no clock (4.4).
// - GitHub events are edges (4.1): pr-closed compares GitHub's closedAt with the record's
//   prClosedAt, a drop and an unpark compare the op's time with the life's claim and the park.
// - 4.1's order holds across sources: the PRs are read every pass, the issue less often, so a
//   PR's close waits for a read of its issue made after it (observe makes that read due), and an
//   issue closed with its PR closes rather than parks.
// - The next transition waits until the seq's `transition` event is logged (3.3), and an effect
//   that used up its attempts holds the record's step (4.5).
// - Every record that is not closed ends a pass with a running step, a planned action or a skip
//   line naming why it waits (property 3).
//
// Pure: the time is state.now.
import { isoOf, skip, wake, want } from '../foundation'
import type { Ms } from '../types'
import { entryKey, hiddenKey, lifeAt, transitionKey } from './keys'
import { ticksOf, tickNote } from './park-text'
import { agentPlan, causeOf, leaseOf, leaseStep, lifeEntries, notBuiltStep, triggerOf } from './rules-agent'
import type { StepPlan, StepRead } from './rules-agent'
import { claimRules, heartbeatRules, reclaimLost } from './rules-claim'
import { dualWriteRules } from './rules-dualwrite'
import { shadowRules } from './rules-shadow'
import { ensureActions, entryDone, entryItems, parkedTell, stalledOf, stalledTell, transitionLogged } from './rules-entry'
import type { EntryItem } from './rules-entry'
import { PLANS as QUEUE, dontMergeOf } from './rules-queue'
import { PLANS as REVIEW, lifePr } from './rules-review'
import { PLANS as WORK } from './rules-work'
import { waitKey } from './sources-waits'
import { mayHaveMerged } from './steps-queue'
import { nextRecord, normalize, rowFor, viaOf } from './table'
import { FACTORY_LABELS } from './types'
import { workspaceHold } from './workspace'
import type { IssueRecord, Row, StepKind, TableEvent, Trigger, V2Ctx, WaitCondition } from './types'

const HOUR = 3_600_000
// The title's M: issues merged in this window (D-23).
const MERGED_WINDOW_MS = 6 * HOUR
const NOTE_MAX = 2000

// Each step's plan: the generic agent step and the lease here, each unit's own over them (U5's
// work steps, U6's review, U7's merge queue), triage always the generic agent step.
const PLANS: Readonly<Record<StepKind, StepPlan>> = {
  lease: leaseStep,
  design: agentPlan('design'),
  build: agentPlan('build'),
  fix: agentPlan('fix'),
  review: notBuiltStep('review', 'U6'),
  queue: notBuiltStep('queue', 'U7'),
  ...WORK,
  ...REVIEW,
  ...QUEUE,
  triage: agentPlan('triage'),
}

// An event present for a record this pass, and what its transition re-checks; wait: why the
// record holds instead, when an event before it in 4.1's order may not be read yet.
type Present = { event: TableEvent; trigger: Trigger; wait?: string }

const fact = (f: string): Trigger => ({ kind: 'fact', fact: f })

// ruleOf: the rule id a row's transition is planned under (14.1).
function ruleOf(row: Row): string {
  if (row.id === 'S0' || row.id === 'S7') return 'S1'
  if (row.id.startsWith('U')) return 'S4'
  if (row.id.startsWith('X')) return 'S5'
  return row.id.startsWith('T') ? 'S3' : 'S6'
}

function describe(e: TableEvent): string {
  const tail = e.choice ?? e.why ?? e.reason
  const text = `${e.kind}${tail === undefined ? '' : ` (${tail})`}`
  return text.length > 120 ? `${text.slice(0, 117)}...` : text
}

const sameSha = (a: string | null, b: string | null) => a !== null && b !== null && (a.startsWith(b) || b.startsWith(a))

// --- the owner's and GitHub's events (4.1) ---------------------------------------------------------------

// loopMerged: a queue-merge of this life merged, or may have (running or lost), at this head when
// one is given: the merge is the queue step's own result, never a hand merge (4.1). A refusal,
// done but not merged, is not one.
function loopMerged(ctx: V2Ctx, r: IssueRecord, head: string | null): boolean {
  return lifeEntries(ctx, r, 'queue-merge').some(e => mayHaveMerged(e) && (head === null || sameSha(e.head, head)))
}

// earlyEvents: the events present before the step's result, in 4.1's order.
function earlyEvents(ctx: V2Ctx, r: IssueRecord): Present[] {
  const out: Present[] = []
  const n = r.issue
  const born = lifeAt(r.life) ?? 0
  // the life's PR: the record's, else the one the review step's ensure named (8.1), so a PR merged
  // or closed by hand during its first review round is seen too
  const known = lifePr(ctx.state.ledger, r)
  const pr = known === null ? undefined : ctx.v2.prs.prs.find(p => p.pr === known)
  if (pr?.state === 'merged' && !loopMerged(ctx, r, pr.mergedHead)) {
    out.push({ event: { kind: 'pr-merged', data: { pr: pr.pr, ...(pr.mergedHead === null ? {} : { head: pr.mergedHead }) } }, trigger: fact(`pr-merged:${pr.pr}@${pr.mergedHead ?? 'unknown'}`) })
  }
  const read = ctx.v2.reads[n]
  const closedByLoop = loopMerged(ctx, r, null) || ctx.state.ledger.some(e => e.kind === 'close-issue' && e.issue === n && e.startedAt >= born && e.status !== 'failed')
  if (read !== undefined && read.open === false && read.at > born && !closedByLoop) out.push({ event: { kind: 'issue-closed' }, trigger: fact(`issue-closed:${n}@${read.at}`) })
  const lost = reclaimLost(ctx, r)
  if (lost !== null) out.push({ event: { kind: 'claim-lost', reason: lost.summary ?? 'another device holds a live claim' }, trigger: triggerOf(lost) })
  const drop = ctx.state.control.dropped.filter(d => d.issue === n && d.at > born).sort((a, b) => a.at - b.at).at(-1)
  if (drop !== undefined) out.push({ event: { kind: 'drop' }, trigger: fact(`drop:${n}@${drop.at}`) })
  if (pr?.state === 'closed' && pr.closedAt !== null && (r.prClosedAt === null || pr.closedAt > r.prClosedAt)) {
    const since = ctx.v2.changed[n]
    const wait = since !== undefined && (read === undefined || read.at <= since) ? { wait: `issue #${n} is not read since PR #${pr.pr} closed` } : {}
    out.push({ event: { kind: 'pr-closed', data: { pr: pr.pr, closedAt: pr.closedAt } }, trigger: fact(`pr-closed:${pr.pr}@${pr.closedAt}`), ...wait })
  }
  return out
}

// unparkOf: a parked or waiting record's unpark (4.1, 11): a `/factory resume N` newer than the park, with
// its note; or a read of the issue made after the park's label write that lacks `factory:parked`,
// with the owner's tick in the park's comment (the one of this seq) and the trusted comments
// posted after it as the note. 'wait': the label is
// gone, but those comments are not read yet.
function unparkOf(ctx: V2Ctx, r: IssueRecord): Present | 'wait' | null {
  const n = r.issue
  const pr = r.pr === null ? undefined : ctx.v2.prs.prs.find(p => p.pr === r.pr)
  const closedAt = pr?.state === 'closed' && pr.closedAt !== null ? { closedAt: pr.closedAt } : {}
  const ops = ctx.state.control.resumed.filter(x => x.subject === `issue:${n}` && x.at > r.since).sort((a, b) => a.at - b.at)
  const op = ops.at(-1)
  if (op !== undefined) {
    const note = ops.flatMap(x => (x.note === undefined ? [] : [x.note])).join('\n')
    return { event: { kind: 'unpark', reason: 'op', data: { ...closedAt, ...(note === '' ? {} : { note: clip(note) }) } }, trigger: fact(`unpark:${n}@${op.at}`) }
  }
  // a waiting record is resumed by the owner's op alone: a removed factory:waiting label is not one (11)
  if (r.state === 'waiting') return null
  const label = ctx.byKey.get(entryKey(r, 'label'))
  const read = ctx.v2.reads[n]
  if (label?.status !== 'done' || label.endedAt === null || read === undefined || read.at <= label.endedAt || read.labels === null) return null
  if (read.labels.some(l => l.toLowerCase() === FACTORY_LABELS.parked.name)) return null
  const comments = ctx.v2.comments[n]
  if (comments === undefined) return 'wait'
  const after = ctx.byKey.get(entryKey(r, 'comment'))?.endedAt ?? r.since
  // the owner's tick in this seq's park comment, current body, comes first; the factory's other
  // comments never become notes
  const marker = hiddenKey(entryKey(r, 'comment'))
  const parkComment = comments.find(c => c.body.includes(marker))
  const tick = parkComment === undefined ? null : tickNote(ticksOf(parkComment.body))
  const note = [...(tick === null ? [] : [tick]), ...comments.filter(c => c.at > after && !c.body.includes('<!-- factory-loop:')).map(c => c.body.trim())].join('\n\n')
  return { event: { kind: 'unpark', reason: 'label', data: { ...closedAt, ...(note === '' ? {} : { note: clip(note) }) } }, trigger: fact(`unpark-label:${n}@${read.at}`) }
}

function clip(text: string): string {
  return text.length > NOTE_MAX ? `${text.slice(0, NOTE_MAX - 3)}...` : text
}

// --- E6: the waiting states' tells (4.4) ---------------------------------------------------------------

// periodOf: a waiting state's tell period: queued, the merge queue behind its head, parked, waiting.
function periodOf(ctx: V2Ctx, r: IssueRecord): Ms {
  const t = ctx.config.stateTimeoutMs
  return r.state === 'parked' ? t.parked : r.state === 'waiting' ? t.waiting : r.state === 'queued' ? t.queued : t.queueWait
}

// openOf: the conditions of a waiting record no read has shown to hold (4.4): a condition not read,
// or whose read failed or was skipped, is open.
export function openOf(ctx: V2Ctx, r: IssueRecord): WaitCondition[] {
  return (r.wait ?? []).filter(c => ctx.v2.waits?.[waitKey(c)]?.held !== true)
}

// clearedData: the tag each of the record's tag-contains reads compared against, by waitKey, for the
// cleared note.
function clearedData(ctx: V2Ctx, r: IssueRecord): { tags: Record<string, string> } | undefined {
  const tags: Record<string, string> = {}
  for (const c of r.wait ?? []) {
    const tag = c.kind === 'tag-contains' ? ctx.v2.waits?.[waitKey(c)]?.tag : undefined
    if (tag !== undefined) tags[waitKey(c)] = tag
  }
  return Object.keys(tags).length === 0 ? undefined : { tags }
}

// openText: the open conditions in words, for the skip line and E6's tell; a condition the loop
// cannot read says so.
export function openText(ctx: V2Ctx, open: readonly WaitCondition[]): string {
  return open
    .map(c => {
      const text =
        c.kind === 'issue-closed'
          ? `${c.repo ?? ''}#${c.issue} (still open)`
          : c.kind === 'pr-merged'
            ? `PR #${c.pr} (not merged yet)`
            : `no release tag${c.repo === undefined ? '' : ` of ${c.repo}`} contains ${c.sha} yet`
      const u = ctx.v2.waitsUnread?.[waitKey(c)]
      return u === undefined ? text : `${text} (unread: ${u.why === 'read-failed' ? 'read failing' : 'no release'})`
    })
    .join(', ')
}

// unreadOf: the open conditions of a waiting record unread for at least the waiting period, with
// the line that says why each is.
function unreadOf(ctx: V2Ctx, r: IssueRecord): { key: string; line: string }[] {
  if (r.state !== 'waiting') return []
  const out: { key: string; line: string }[] = []
  for (const c of openOf(ctx, r)) {
    const key = waitKey(c)
    const u = ctx.v2.waitsUnread?.[key]
    if (u === undefined || ctx.state.now - u.since < periodOf(ctx, r)) continue
    const since = isoOf(u.since)
    const repo = c.kind === 'tag-contains' && c.repo !== undefined ? c.repo : 'this repo'
    out.push({ key, line: u.why === 'read-failed' ? `${key}: its read has failed since ${since}` : `${key}: no release tag of ${repo} is known since ${since}` })
  }
  return out
}

// waitingRules: a waiting record's events after the early ones (4.1): C1 when every condition
// holds, else E6's tell once a period has passed, and the owner's resume (P1).
function waitingRules(ctx: V2Ctx, r: IssueRecord, logged: boolean): void {
  const n = r.issue
  const open = openOf(ctx, r)
  if (open.length === 0 && (r.wait ?? []).length > 0) {
    if (take(ctx, r, { event: { kind: 'cleared', data: clearedData(ctx, r) }, trigger: fact(`cleared:${n}@${r.seq}`) }, logged, '')) return
  }
  if (ctx.state.now - r.since >= periodOf(ctx, r)) take(ctx, r, { event: { kind: 'timeout' }, trigger: fact(`waiting:${n}`) }, logged, `waiting for ${openText(ctx, open)}`)
  const u = unparkOf(ctx, r)
  if (u === null || u === 'wait') skip(ctx, 'S6', n, `waiting: for ${open.length === 0 ? 'its clear' : openText(ctx, open)}`)
  else take(ctx, r, u, logged, '')
}

// waitTell: E6, once per period: tell(waiting), tell(wait-unreadable) (an owner item) when a condition
// has been unread a whole period, or tell(parked) as the daily reminder (an owner
// item, counted once per record).
function waitTell(ctx: V2Ctx, r: IssueRecord, why: string): void {
  const k = Math.floor((ctx.state.now - r.since) / periodOf(ctx, r))
  if (k < 1) return
  if (r.state === 'parked') {
    want(ctx, parkedTell(r, k))
    ctx.owner.delete(entryKey(r, 'tell'))
    return
  }
  const hours = Math.floor((ctx.state.now - r.since) / HOUR)
  const unread = unreadOf(ctx, r)
  if (unread.length > 0) {
    want(ctx, wake('tell', 'wait-unreadable', `${entryKey(r, 'tell')}/wait-unreadable/${k}`, 'S6', r.issue, { issue: r.issue, hours, conditions: unread.map(u => u.key).join(',') }, unread.map(u => u.line)))
    return
  }
  want(ctx, wake('tell', 'waiting', `${entryKey(r, 'tell')}/waiting/${k}`, 'S6', r.issue, { issue: r.issue, state: r.state, hours }, [why]))
}

// --- one record ----------------------------------------------------------------------------------------------

// take: the row for this event. A changing row plans its transition, once the seq's transition
// event is logged; E6 tells and E7 logs, and neither stops the next event. True when the record
// is taken this pass.
function take(ctx: V2Ctx, r: IssueRecord, p: Present, logged: boolean, why: string): boolean {
  const row = rowFor(r, p.event, ctx.config)
  if (row.id === 'E7') {
    skip(ctx, 'S6', r.issue, `E7: ${describe(p.event)} means nothing in ${r.state}${r.step === null ? '' : `/${r.step}`}`)
    return false
  }
  if (row.id === 'E6') {
    waitTell(ctx, r, why)
    return false
  }
  const rule = ruleOf(row)
  if (!logged || p.wait !== undefined) {
    skip(ctx, rule, r.issue, `${row.id} waits: ${p.wait ?? `the transition event of seq ${r.seq} is not logged yet`}`)
    return true
  }
  const ev = normalize(r, p.event)
  const next = nextRecord(r, row, p.event, ctx.state.now)
  const key = transitionKey(next)
  const g = want(ctx, {
    kind: 'transition',
    key,
    class: 'free',
    rule,
    reason: `${row.id}: ${describe(ev)}`,
    issue: r.issue,
    row: row.id,
    event: p.event.kind,
    from: { issue: r.issue, life: r.life, seq: r.seq },
    fromState: r.state,
    fromStep: r.step,
    next,
    trigger: p.trigger,
    cause: ev.cause ?? null,
    via: viaOf(row, ev),
  })
  if (g === 'exhausted') {
    const e = ctx.byKey.get(key)
    skip(ctx, rule, r.issue, `stalled: ${key}: ${e?.summary ?? 'used up its attempts'}`)
    want(ctx, stalledTell(r, key, e?.summary ?? 'used up its attempts', e?.endedAt ?? 0))
  }
  return true
}

// stepRead: the record's step this pass, through its plan.
function stepRead(ctx: V2Ctx, r: IssueRecord, start: boolean, hold: string | null): StepRead | null {
  if (r.step === null) return null
  return PLANS[r.step]({ ctx, r, slot: leaseOf(ctx, r), start, hold })
}

function recordRules(ctx: V2Ctx, r: IssueRecord, items: readonly EntryItem[]): void {
  const { state } = ctx
  const n = r.issue
  const mark = { out: ctx.out.length, skipped: ctx.skipped.length }
  for (const item of items) {
    // a best-effort action that ended is done with, however it ended
    const e = item.soft ? ctx.byKey.get(item.action.key) : undefined
    if (e === undefined || e.status === 'running') want(ctx, item.action)
  }
  const stalled = stalledOf(ctx, r)
  if (stalled !== null) {
    skip(ctx, 'S3', n, `stalled: ${stalled.key}: ${stalled.error}`)
    want(ctx, stalledTell(r, stalled.key, stalled.error, stalled.at))
  }
  if (r.state === 'closed') return
  const logged = transitionLogged(ctx, r)
  for (const p of earlyEvents(ctx, r)) if (take(ctx, r, p, logged, '')) return
  let running = false
  if (r.state === 'waiting') {
    waitingRules(ctx, r, logged)
  } else if (r.state === 'parked') {
    if (state.now - r.since >= periodOf(ctx, r)) take(ctx, r, { event: { kind: 'timeout' }, trigger: fact(`parked:${n}`) }, logged, 'parked')
    const u = unparkOf(ctx, r)
    if (u === 'wait') skip(ctx, 'S6', n, 'unpark: the label is off; waits for the trusted comments to be read')
    else if (u === null) skip(ctx, 'S6', n, 'parked: waits on the owner')
    else take(ctx, r, u, logged, '')
  } else {
    const hold = !logged ? `its transition event of seq ${r.seq} is not logged yet` : stalled !== null ? `stalled: ${stalled.key}` : !entryDone(ctx, items) ? 'its entry actions run first' : workspaceHold(ctx, r.step)
    const read = stepRead(ctx, r, hold === null, hold)
    if (read?.kind === 'running') {
      running = true
      if (state.now - read.since > read.timeoutMs) {
        const entry = ctx.byKey.get(read.key) ?? null
        const reason = `${r.step ?? 'the step'} ran past its ${Math.round(read.timeoutMs / 60_000)} min`
        // a running step's timeout is its unknown, whatever the state: E6's tell is only for a
        // record that waits (below), so a hung merge-queue head takes U1 to U4 (4.3, 4.4)
        const event: TableEvent = { kind: 'unknown', why: 'timeout', reason, cause: causeOf(ctx, r, entry, 'timeout') ?? undefined }
        take(ctx, r, { event, trigger: entry === null ? fact(`timeout:${read.key}`) : triggerOf(entry) }, logged, '')
      }
    } else if (read?.kind === 'result') {
      if (stalled === null) take(ctx, r, { event: read.event, trigger: read.trigger }, logged, '')
    } else if (read?.kind === 'waiting') {
      if (state.now - r.since >= periodOf(ctx, r)) take(ctx, r, { event: { kind: 'timeout' }, trigger: fact(`waiting:${n}`) }, logged, read.why)
      skip(ctx, 'S2', n, read.why)
    } else if (read?.kind === 'held' && read.why !== '') {
      skip(ctx, r.step === 'triage' ? 'S5' : 'S2', n, read.why)
    }
  }
  // property 3: no record is silent
  const acted = ctx.out.slice(mark.out).some(a => a.issue === n)
  const said = ctx.skipped.slice(mark.skipped).some(s => s.issue === n)
  if (!acted && !said && !running) skip(ctx, 'S2', n, `${r.state}${r.step === null ? '' : `/${r.step}`}: its planned work runs`)
}

// stateRules: H1, then each record (S2 to S6), then S0 and S1. The seven labels are made first on a
// pass that writes one (3.4).
export function stateRules(ctx: V2Ctx): void {
  heartbeatRules(ctx)
  dualWriteRules(ctx)
  shadowRules(ctx)
  const records = [...ctx.v2.records].sort((a, b) => a.issue - b.issue || (lifeAt(a.life) ?? 0) - (lifeAt(b.life) ?? 0))
  const items = records.map(r => entryItems(ctx, r, leaseOf(ctx, r)))
  const labels = items.some(list => list.some(i => i.action.kind === 'label' && ctx.byKey.get(i.action.key)?.status !== 'done'))
  if (labels) for (const a of ensureActions(ctx)) want(ctx, a)
  records.forEach((r, i) => recordRules(ctx, r, items[i] ?? []))
  claimRules(ctx)
}

// The records by where they are: queued, in flight (designing to merge-queue) and parked.
export type StateCounts = { queued: number; flight: number; parked: number; waiting: number }

export function stateCounts(records: readonly IssueRecord[]): StateCounts {
  const out: StateCounts = { queued: 0, flight: 0, parked: 0, waiting: 0 }
  for (const r of records) {
    if (r.state === 'queued') out.queued += 1
    else if (r.state === 'parked') out.parked += 1
    else if (r.state === 'waiting') out.waiting += 1
    else if (r.state !== 'closed') out.flight += 1
  }
  return out
}

// stateTitle: the title's counts, Q (the ready queue and the queued records), D (in flight) and M
// (merged in the last 6 hours), and its words of the layer's own: parked <n>, waiting <n>, held <n>.
export function stateTitle(ctx: V2Ctx): { counts: string; after: string[] } {
  const c = stateCounts(ctx.v2.records)
  // held: the queue records the owner's `don't-merge` label holds (they are in flight as well)
  const held = ctx.v2.records.filter(r => r.state === 'merge-queue' && r.step === 'queue' && dontMergeOf(ctx, r) !== null).length
  const merged = ctx.v2.records.filter(r => r.state === 'closed' && (r.why === 'merged' || r.why === 'merged-by-hand') && ctx.state.now - r.since <= MERGED_WINDOW_MS).length
  return { counts: `Q:${ctx.state.queue.length + c.queued} - D:${c.flight} - M:${merged}`, after: [...(c.parked > 0 ? [`parked ${c.parked}`] : []), ...(c.waiting > 0 ? [`waiting ${c.waiting}`] : []), ...(held > 0 ? [`held ${held}`] : [])] }
}

files.hooks/v2/wind-down-files.ts:
// The files of a wind-down (docs/factory-loop/v2/SPEC.md 10.11): the request and status file as
// text, and the pass's writes. The planner reaches wind-down.ts only; this module is observe's and
// register's, so it may read dates.
import type { LedgerEntry, Ms, State } from '../types'
import { WIND_DOWN_REQUEST, WIND_DOWN_STATUS, windDownOf, windDownPaths } from './wind-down'
import type { WindDown, WindDownRead } from './wind-down'

const TRIGGERS = ['restart-self', 'coder-stop']

// requestOf: the request file's text as a request; a file that does not read as one is a request
// at the file's mtime (a bad write never leaves the loop starting work during a stop), with the
// problem.
export function requestOf(text: string, mtime: Ms): NonNullable<WindDownRead['request']> {
  try {
    const v: unknown = JSON.parse(text)
    if (v !== null && typeof v === 'object' && !Array.isArray(v)) {
      const o = v as Record<string, unknown>
      const at = typeof o.requested_at === 'string' ? Date.parse(o.requested_at) : Number.NaN
      if (!Number.isNaN(at)) {
        const trigger = typeof o.trigger === 'string' && TRIGGERS.some(t => t === o.trigger) ? o.trigger : null
        return { requestedAt: at, iso: new Date(at).toISOString(), trigger, problem: o.trigger === null || trigger !== null ? null : `wind-down: trigger ${JSON.stringify(o.trigger)} is not restart-self, coder-stop or null` }
      }
    }
  } catch {
    // falls through
  }
  return { requestedAt: mtime, iso: new Date(mtime).toISOString(), trigger: null, problem: `wind-down: ${WIND_DOWN_REQUEST} is not a request (needs a requested_at time); treated as a request at its modification time` }
}

// withRemembered: the state with the request this session wrote for its own restart (R2), when the
// read found none: the file may be lost (the stop script leaves it in place, #931) while the
// container still runs, and nothing may start in those seconds. A request read from the file wins.
export function withRemembered(state: State, requestedAt: Ms | null): State {
  if (requestedAt === null || state.v2 === undefined || state.v2.windDown?.request != null) return state
  const request = { requestedAt, iso: new Date(requestedAt).toISOString(), trigger: 'restart-self', problem: null, remembered: true as const }
  return { ...state, v2: { ...state.v2, windDown: { stopNow: false, previous: null, ...state.v2.windDown, request } } }
}

// previousOf: the status file's requested_at and started_at, or null.
export function previousOf(text: string | null): WindDownRead['previous'] {
  if (text === null) return null
  try {
    const o = JSON.parse(text) as Record<string, unknown>
    const requestedAt = typeof o.requested_at === 'string' ? Date.parse(o.requested_at) : Number.NaN
    const startedAt = typeof o.started_at === 'string' ? Date.parse(o.started_at) : Number.NaN
    return Number.isNaN(requestedAt) || Number.isNaN(startedAt) ? null : { requestedAt, startedAt }
  } catch {
    return null
  }
}

const running = (e: LedgerEntry) => e.status === 'running'

// windDownStatus: wind-down.status.json's object for an active wind-down.
export function windDownStatus(state: State, wd: Extract<WindDown, { mode: 'active' }>) {
  const iso = (t: Ms) => new Date(t).toISOString()
  const steps = state.ledger.filter(e => running(e) && e.kind === 'agent-step')
  const queue = state.ledger.some(e => running(e) && (e.kind === 'queue-update' || e.kind === 'queue-merge'))
  const release = state.ledger.some(e => running(e) && e.kind === 'task' && e.wake === 'release')
  // the loop cannot see a stop gate apart from its step: a writer step that runs may be in its gate
  const gate = steps.some(e => e.step === 'build' || e.step === 'fix')
  return {
    requested_at: iso(wd.requestedAt),
    started_at: iso(wd.startedAt),
    cap_ms: wd.capMs,
    running: { steps: steps.map(e => e.key), gate, queue, release },
    idle: steps.length === 0 && !gate && !queue && !release,
    stop_now: state.v2?.windDown?.stopNow === true,
    at: iso(state.now),
  }
}

// The status file lands whole or not at all: written beside itself, then renamed over it.
export const WIND_DOWN_WRITE_SCRIPT = ['set -e', 'tmp="$1.tmp.$$"', 'trap \'rm -f -- "$tmp"\' EXIT', 'cat > "$tmp"', 'mv -f -- "$tmp" "$1"'].join('\n')

export type WindDownIo = { run: (argv: string[], init: { stdin?: string; timeoutMs: number }) => Promise<{ exitCode: number; stderr: string }> }

// windDownFiles: the pass's writes. An active wind-down writes the status file; a stale request
// is removed (the planner tells the owner once, from the same state). Off writes and removes
// nothing. Returns the problems for the decision log; a failed write never fails the pass.
export async function windDownFiles(io: WindDownIo, loopDir: string, state: State, config: { windDownMinutes: number }): Promise<string[]> {
  const wd = windDownOf(state, config)
  if (wd.mode === 'off') return []
  const problems = state.v2?.windDown?.request?.problem != null ? [state.v2.windDown.request.problem] : []
  const paths = windDownPaths(loopDir)
  const active = wd.mode === 'active'
  // a remembered request has no file: no status file for it (the stop script took the request away)
  if (active && state.v2?.windDown?.request?.remembered === true) return problems
  const argv = active ? ['sh', '-c', WIND_DOWN_WRITE_SCRIPT, 'wind-down-status', paths.status] : ['rm', '-f', '--', paths.request]
  const init = active ? { stdin: `${JSON.stringify(windDownStatus(state, wd), null, 2)}\n`, timeoutMs: 10_000 } : { timeoutMs: 10_000 }
  try {
    const r = await io.run(argv, init)
    if (r.exitCode !== 0) problems.push(`wind-down: ${active ? `${WIND_DOWN_STATUS} not written` : `${WIND_DOWN_REQUEST} not removed`} (exit ${r.exitCode}: ${r.stderr.trim().slice(0, 200)})`)
  } catch (err) {
    problems.push(`wind-down: ${String(err).slice(0, 200)}`)
  }
  return problems
}

files.hooks/driver-pass-log.ts:
// What a pass leaves behind: its trace record (v2 SPEC 13.12.1), the action summaries of its decision-log
// line, the update drain's end (rule H4) and the owner's word that passes keep throwing (v2 SPEC 13.10 item 9).
import type { EngineInterface } from 'claude-code'

import { passErrorTell, sendNotice } from './act'
import { readControl, writeControl } from './control'
import type { Runtime } from './observe'
import { roleProblem } from './rails'
import { CUT_ROOM, byteLength, cutLine, isCutLine, traceName, traceRoom } from './trace'
import type { Action, Ms, PlanResult, State } from './types'
import { noteWritten, notingIo } from './v2/store'
import { append, appendLine, fileIo, killed, v2StoreIo } from './driver-io'
import { bareState, ensureLedger, hookEnv } from './driver-store'
import { S, liveV2 } from './driver-state'

// starvedOf: the pass line's `starved`, while the pass is starved: when the spell began (this pass, on its
// first) and its age in minutes; undefined otherwise, so a spell's start and end show in the log.
export function starvedOf(result: PlanResult, state: State): { since: string; minutes: number } | undefined {
  if (result.starved !== true) return undefined
  const since = state.v2?.starvedSince ?? state.now
  return { since: new Date(since).toISOString(), minutes: Math.floor((state.now - since) / 60_000) }
}

// tellError: three passes in a row threw; the owner hears of it once (v2 SPEC 13.10 item 9), from a session
// that may act: a role the rails refuse tells nothing, as checkRails does.
export async function tellError($: EngineInterface, rt: Runtime, now: Ms, error: string): Promise<boolean> {
  try {
    const problems: string[] = []
    if (roleProblem(await $.env.get('DEV_ROLE'), rt.config) !== null || (await killed($))) return false
    if (!(await ensureLedger($, rt, problems))) return false
    const env = hookEnv($, rt, now, await $.session.id())
    const sent = await sendNotice(env, S.lastState ?? bareState(rt, now), passErrorTell(S.failingSince ?? now, S.failures, error))
    return sent === 'sent'
  } catch {
    return false
  }
}

// writeTrace: the pass's trace record beside its decision log, within config traceMaxBytes
// (trace.ts traceRoom): the oldest trace files go first, and today's is cut short rather than
// pass the cap. A cut stays for the day across reloads: the first write of a load reads whether
// today's file already ends with the cut line (v2 SPEC 13.12.1). A trace that cannot be written never
// fails the pass.
export async function writeTrace($: EngineInterface, rt: Runtime, record: Record<string, unknown>) {
  const at = String(record.at)
  const day = at.slice(0, 10)
  const cap = rt.config.traceMaxBytes
  const dayCap = `${day}:${cap}`
  const line = JSON.stringify(record) + '\n'
  const files = (await $.fs.list(rt.loopDir)).filter(e => e.kind === 'file')
  const path = `${rt.loopDir}/${traceName(day)}`
  if (S.traceCut !== dayCap && S.traceChecked !== dayCap) {
    if (files.some(f => f.name === traceName(day) && f.size > 0) && (await endsCut($, path, cap))) S.traceCut = dayCap
    S.traceChecked = dayCap
  }
  const room = traceRoom(files, day, byteLength(line), cap, S.traceCut === dayCap)
  if (room.remove.length > 0) {
    const r = await $.process.run(['rm', '-f', '--', ...room.remove.map(name => `${rt.loopDir}/${name}`)], { timeoutMs: 10_000 })
    if (r.exitCode !== 0) return
  }
  if (room.write === 'record') await append($, path, line)
  if (room.write === 'cut') {
    await append($, path, cutLine(at, cap))
    S.traceCut = dayCap
  }
}

// endsCut: the trace file's last line is the cut line of this cap. Only its tail is read, since
// the file may be far larger than $.fs.read takes; the cut line fits in CUT_ROOM bytes.
export async function endsCut($: EngineInterface, path: string, cap: number): Promise<boolean> {
  const r = await $.process.run(['tail', '-c', String(CUT_ROOM), '--', path], { timeoutMs: 10_000 })
  return r.exitCode === 0 && isCutLine(r.stdout.trimEnd().split('\n').pop() ?? '', cap)
}

export function summaryOf(a: Action) {
  return {
    key: a.key,
    kind: a.kind,
    class: a.class,
    rule: a.rule,
    issue: a.issue,
    step: a.kind === 'agent-step' ? a.step : undefined,
    run: 'run' in a && typeof a.run === 'string' ? a.run : undefined,
    pr: 'pr' in a && typeof a.pr === 'number' ? a.pr : undefined,
    reason: a.reason,
    // a wake action's fields (a tell's since, roots, why...), so the decision log says what it named
    fields: 'fields' in a && typeof a.fields === 'object' && a.fields !== null ? a.fields : undefined,
  }
}

// clearUpdate: control.json without updateDue, once the restart for it ran (rule H4). Its line
// is appended outside the owner's op queue, which holds only file reads and writes (#558).
export async function clearUpdate($: EngineInterface, rt: Runtime, at: Ms | null): Promise<boolean> {
  if (at === null) return false
  const run = S.ops.then(async () => {
    const fio = notingIo(fileIo($), noteWritten(liveV2, v2StoreIo($), rt))
    const loaded = await readControl(fio, rt.loopDir)
    if (loaded.error !== null || loaded.control.updateDue?.at !== at) return false
    await writeControl(fio, rt.loopDir, { ...loaded.control, updateDue: null })
    return true
  })
  S.ops = run.catch(() => undefined)
  const cleared = await run.catch(() => false)
  if (cleared) await appendLine($, rt, { control: 'update off', text: `restart:${at} ran: the update is done and the drain ends` })
  return cleared
}

